INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('05195b7c-c697-531e-a439-823578bf9e5d', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 41, 41, 'and with them Heman and Jeduthun, and the rest who were chosen, who were mentioned by name, to give thanks to Yahweh, because his loving kindness endures forever;'),
  ('04dcf960-5d09-510e-aac6-882a6b3bf677', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 42, 42, 'and with them Heman and Jeduthun [with] trumpets and cymbals for those that should sound aloud, and [with] instruments for the songs of God; and the sons of Jeduthun to be at the gate.'),
  ('b8f13b55-0414-5181-ad2f-fcfe4c3cd3a2', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 43, 43, 'All the people departed every man to his house: and David returned to bless his house.'),
  ('198dcc91-a80e-52da-a942-18a3b34469f3', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 1, 1, 'It happened, when David lived in his house, that David said to Nathan the prophet, "Behold, I dwell in a house of cedar, but the ark of the covenant of Yahweh is under curtains."'),
  ('338c809f-5c1f-5909-a63d-1a5713561e6f', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 2, 2, 'Nathan said to David, "Do all that is in your heart; for God is with you."'),
  ('894915fa-5b55-5f0a-a157-c3edc0414096', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 3, 3, 'It happened the same night, that the word of God came to Nathan, saying,'),
  ('ba8ed306-e522-5d63-a205-f3acc7e3ed32', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 4, 4, '"Go and tell David my servant, ''Thus says Yahweh, "You shall not build me a house to dwell in;'),
  ('b8ba480b-2b4b-5179-aef8-170f15b908a8', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 5, 5, 'for I have not lived in a house since the day that I brought up Israel, to this day, but have gone from tent to tent, and from one tent to another.'),
  ('0df4ec0b-18de-583a-ad8f-bda4013716db', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 6, 6, 'In all places in which I have walked with all Israel, did I speak a word with any of the judges of Israel, whom I commanded to be shepherd of my people, saying, ''Why have you not built me a house of cedar?''"'''),
  ('e6ed81a4-6a71-58cd-a379-7d3bb69a1a0f', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 7, 7, '"Now therefore, you shall tell my servant David, ''Thus says Yahweh of Armies, "I took you from the sheep pen, from following the sheep, that you should be prince over my people Israel.'),
  ('c8d1200f-8e74-5776-aabd-163d2fa9bf48', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 8, 8, 'I have been with you wherever you have gone, and have cut off all your enemies from before you. I will make you a name, like the name of the great ones who are in the earth.'),
  ('71693759-fd08-537f-a014-ee130901cc6f', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 9, 9, 'I will appoint a place for my people Israel, and will plant them, that they may dwell in their own place, and be moved no more; neither shall the children of wickedness waste them any more, as at the first,'),
  ('5b8758ef-9447-50e8-aefa-f935588dd411', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 10, 10, 'and from the day that I commanded judges to be over my people Israel; and I will subdue all your enemies. Moreover I tell you that Yahweh will build you a house.'),
  ('8e940a37-cd63-5263-a777-4a52955a652f', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 11, 11, 'It shall happen, when your days are fulfilled that you must go to be with your fathers, that I will set up your seed after you, who shall be of your sons; and I will establish his kingdom.'),
  ('47a3b0ae-2383-5ac2-a8e4-9d87fcf4fcf1', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 12, 12, 'He shall build me a house, and I will establish his throne forever.'),
  ('2a3eb0ee-88c6-59db-a5de-35daa7ec45d4', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 13, 13, 'I will be his father, and he shall be my son. I will not take my loving kindness away from him, as I took it from him that was before you;'),
  ('47ec095f-1670-5be1-a87a-2f73bcf13e6f', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 14, 14, 'but I will settle him in my house and in my kingdom forever. His throne shall be established forever."''"'),
  ('3341918e-7bb3-5b77-a758-d647f8b93777', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 15, 15, 'According to all these words, and according to all this vision, so Nathan spoke to David.'),
  ('5b489b96-9326-5b82-abb9-b30528058ebe', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 16, 16, 'Then David the king went in, and sat before Yahweh; and he said, "Who am I, Yahweh God, and what is my house, that you have brought me thus far?'),
  ('8ba705d0-df87-5889-a39d-5930256b462e', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 17, 17, 'This was a small thing in your eyes, God; but you have spoken of your servant''s house for a great while to come, and have respected me according to the estate of a man of high degree, Yahweh God.'),
  ('c1a5ac13-5b55-5646-a186-126ec1e07a41', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 18, 18, 'What can David say yet more to you concerning the honor which is done to your servant? For you know your servant.'),
  ('08b71ea9-ccc8-5977-a717-2a2cd0448b4d', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 19, 19, 'Yahweh, for your servant''s sake, and according to your own heart, you have worked all this greatness, to make known all these great things.'),
  ('521237bb-268d-57c4-ad35-a30f592d4005', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 20, 20, 'Yahweh, there is none like you, neither is there any God besides you, according to all that we have heard with our ears.'),
  ('d51aefe7-f96c-5eca-a0e2-04cc12a93d6e', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 21, 21, 'What one nation in the earth is like your people Israel, whom God went to redeem to himself for a people, to make you a name by great and awesome things, in driving out nations from before your people, whom you redeem out of Egypt?'),
  ('0220b498-8e52-564c-aafe-d23e85bdd3dd', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 22, 22, 'For your people Israel you made your own people forever; and you, Yahweh, became their God.'),
  ('c31b0794-daf3-5116-a9ae-7413a8046d01', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 23, 23, 'Now, Yahweh, let the word that you have spoken concerning your servant, and concerning his house, be established forever, and do as you have spoken.'),
  ('b7818aa0-f6fb-54ca-a8e2-8e65c0308cd6', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 24, 24, 'Let your name be established and magnified forever, saying, ''Yahweh of Armies is the God of Israel, even a God to Israel. The house of David your servant is established before you.'''),
  ('303bbcb5-0224-506f-aa26-37e612afe9da', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 25, 25, 'For you, my God, have revealed to your servant that you will build him a house. Therefore your servant has found courage to pray before you.'),
  ('bbd9f33b-c244-5068-a6c9-b315450359d5', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 26, 26, 'Now, Yahweh, you are God, and have promised this good thing to your servant.'),
  ('0047001e-7a8d-5ed2-a1a8-d2725ef78f65', '55512c73-bc7b-5950-a8e2-b68de5578fa9', NULL, 27, 27, 'Now it has pleased you to bless the house of your servant, that it may continue forever before you; for you, Yahweh, have blessed, and it is blessed forever."'),
  ('8d00eba3-d570-5d8d-af36-4c12b0de4787', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 1, 1, 'After this it happened, that David struck the Philistines, and subdued them, and took Gath and its towns out of the hand of the Philistines.'),
  ('55a560ef-3f1f-5cfa-a067-6bd47673bb2b', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 2, 2, 'He struck Moab; and the Moabites became servants to David, and brought tribute.'),
  ('5b7db382-843e-560e-aef4-de7ec34c1432', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 3, 3, 'David struck Hadadezer king of Zobah to Hamath, as he went to establish his dominion by the river Euphrates.'),
  ('dd930617-b614-5b9a-a9ca-072d2dc0087a', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 4, 4, 'David took from him one thousand chariots, and seven thousand horsemen, and twenty thousand footmen; and David hamstrung all the chariot horses, but reserved of them for one hundred chariots.'),
  ('2e1edac2-a2a4-5224-aa67-143a65e7f67e', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 5, 5, 'When the Syrians of Damascus came to help Hadadezer king of Zobah, David struck of the Syrians twenty-two thousand men.'),
  ('afbc52bc-5386-5f2f-af8b-843d361928df', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 6, 6, 'Then David put [garrisons] in Syria of Damascus; and the Syrians became servants to David, and brought tribute. Yahweh gave victory to David wherever he went.'),
  ('7148d102-eb65-5cdb-a0a0-2549c26844e3', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 7, 7, 'David took the shields of gold that were on the servants of Hadadezer, and brought them to Jerusalem.'),
  ('1290e85d-55c2-5ae1-adbd-c9ddc1867bbb', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 8, 8, 'From Tibhath and from Cun, cities of Hadadezer, David took very much brass, with which Solomon made the bronze sea, and the pillars, and the vessels of brass.'),
  ('1c131906-9ac8-5d43-a3dc-b6843a4a03d4', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 9, 9, 'When Tou king of Hamath heard that David had struck all the army of Hadadezer king of Zobah,'),
  ('bc4f8998-0365-5273-a541-befd230f484c', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 10, 10, 'he sent Hadoram his son to king David, to Greet him, and to bless him, because he had fought against Hadadezer and struck him; (for Hadadezer had wars with Tou;) and [he had with him] all kinds of vessels of gold and silver and brass.'),
  ('4a405333-e606-5f14-ae62-19744ae830de', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 11, 11, 'These also did king David dedicate to Yahweh, with the silver and the gold that he carried away from all the nations; from Edom, and from Moab, and from the children of Ammon, and from the Philistines, and from Amalek.'),
  ('89bd6e9f-3058-5712-af62-eaedef50651a', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 12, 12, 'Moreover Abishai the son of Zeruiah struck of the Edomites in the Valley of Salt eighteen thousand.'),
  ('2472bcd3-5f0e-50e6-acd7-8e84baa9d340', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 13, 13, 'He put garrisons in Edom; and all the Edomites became servants to David. Yahweh gave victory to David wherever he went.'),
  ('378a07c2-b20b-509f-aa88-f58e79691e2f', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 14, 14, 'David reigned over all Israel; and he executed justice and righteousness to all his people.'),
  ('7e4199d4-45ad-535b-adc8-1d1610743f01', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 15, 15, 'Joab the son of Zeruiah was over the army; and Jehoshaphat the son of Ahilud was recorder;'),
  ('189b1081-ce46-504d-af4a-ed3e5e2c8b96', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 16, 16, 'and Zadok the son of Ahitub, and Abimelech the son of Abiathar, were priests; and Shavsha was scribe;'),
  ('4cec0d72-df30-5124-a35c-49312c2c33de', 'bd21aaec-7ed2-5e8d-a062-dca926ab5d27', NULL, 17, 17, 'and Benaiah the son of Jehoiada was over the Cherethites and the Pelethites; and the sons of David were chief about the king.'),
  ('6d0be51d-482a-531c-a9e5-8f52cf610ac3', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 1, 1, 'It happened after this, that Nahash the king of the children of Ammon died, and his son reigned in his place.'),
  ('957508e9-7373-58c5-a383-f3b17d9fb33c', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 2, 2, 'David said, "I will show kindness to Hanun the son of Nahash, because his father showed kindness to me." So David sent messengers to comfort him concerning his father. David''s servants came into the land of the children of Ammon to Hanun, to comfort him.'),
  ('9433290c-f086-50d7-a685-68f1e0d49fb6', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 3, 3, 'But the princes of the children of Ammon said to Hanun, "Do you think that David honors your father, in that he has sent comforters to you? Haven''t his servants come to you to search, to overthrow, and to spy out the land?"'),
  ('564ff08f-d98e-5f0a-a753-fe686a1d7e0a', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 4, 4, 'So Hanun took David''s servants, and shaved them, and cut off their garments in the middle, even to their buttocks, and sent them away.'),
  ('152835d2-8736-5b8b-aa40-31d8d5798f52', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 5, 5, 'Then there went certain persons, and told David how the men were served. He sent to meet them; for the men were greatly ashamed. The king said, "Stay at Jericho until your beards have grown, and then return."'),
  ('0a8c20e3-093c-5001-a20b-8485b11e5dec', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 6, 6, 'When the children of Ammon saw that they had made themselves odious to David, Hanun and the children of Ammon sent one thousand talents of silver to hire them chariots and horsemen out of Mesopotamia, and out of Arammaacah, and out of Zobah.'),
  ('b152f275-6387-5405-a896-59556caafb01', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 7, 7, 'So they hired for themselves thirty-two thousand chariots, and the king of Maacah and his people, who came and encamped before Medeba. The children of Ammon gathered themselves together from their cities, and came to battle.'),
  ('e083dd00-06ac-54c1-a130-2308c156022d', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 8, 8, 'When David heard of it, he sent Joab, and all the army of the mighty men.'),
  ('46fea976-be0d-522a-a111-9375bc48327a', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 9, 9, 'The children of Ammon came out, and put the battle in array at the gate of the city: and the kings who had come were by themselves in the field.'),
  ('f6e52e33-f0c4-5c3f-a425-3c2b7673ee60', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 10, 10, 'Now when Joab saw that the battle was set against him before and behind, he chose of all the choice men of Israel, and put them in array against the Syrians.'),
  ('7074ff96-4134-51e3-a48e-da76027a18bf', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 11, 11, 'The rest of the people he committed into the hand of Abishai his brother; and they put themselves in array against the children of Ammon.'),
  ('a0a386cb-1edd-5c6a-a4b5-abea84049bf7', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 12, 12, 'He said, "If the Syrians are too strong for me, then you are to help me; but if the children of Ammon are too strong for you, then I will help you.'),
  ('2b6ebbc0-c00c-58c9-ae68-234ac2b53272', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 13, 13, 'Be courageous, and let us be strong for our people, and for the cities of our God. May Yahweh do that which seems good to him."'),
  ('002fde6f-0e29-5633-a6ab-1f57417f4713', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 14, 14, 'So Joab and the people who were with him drew near before the Syrians to the battle; and they fled before him.'),
  ('045589fa-9a16-58e3-a866-948040762bae', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 15, 15, 'When the children of Ammon saw that the Syrians had fled, they likewise fled before Abishai his brother, and entered into the city. Then Joab came to Jerusalem.'),
  ('2eb3a57b-8ecf-5d55-ab6d-f1913862502c', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 16, 16, 'When the Syrians saw that they were defeated by Israel, they sent messengers, and drew forth the Syrians who were beyond the River, with Shophach the captain of the army of Hadadezer at their head.'),
  ('7ea76aef-1573-508d-ac8b-f99d85f3e40b', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 17, 17, 'It was told David; and he gathered all Israel together, and passed over the Jordan, and came on them, and set the battle in array against them. So when David had put the battle in array against the Syrians, they fought with him.'),
  ('370adbe8-e186-5827-a79f-b9f45a6e0c0b', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 18, 18, 'The Syrians fled before Israel; and David killed of the Syrians [the men of] seven thousand chariots, and forty thousand footmen, and killed Shophach the captain of the army.'),
  ('70915a33-3e1b-5d03-aaa1-e57bd96c5981', 'c7115a12-994b-50e9-a7d6-54217325c553', NULL, 19, 19, 'When the servants of Hadadezer saw that they were defeated by Israel, they made peace with David, and served him: neither would the Syrians help the children of Ammon any more.'),
  ('89ad7cb7-3c85-5f7d-a7bb-defc6da775da', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 1, 1, 'It happened, at the time of the return of the year, at the time when kings go out [to battle], that Joab led forth the army, and wasted the country of the children of Ammon, and came and besieged Rabbah. But David stayed at Jerusalem. Joab struck Rabbah, and overthrew it.'),
  ('797e91fb-862e-5999-a0a4-4d54fb7a5c00', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 2, 2, 'David took the crown of their king from off his head, and found it to weigh a talent of gold, and there were precious stones in it; and it was set on David''s head: and he brought forth the spoil of the city, exceeding much.'),
  ('cf133334-6e88-51f0-a84b-fdc5d2ebb3c4', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 3, 3, 'He brought forth the people who were therein, and cut [them] with saws, and with iron picks, and with axes. David did so to all the cities of the children of Ammon. David and all the people returned to Jerusalem.'),
  ('b587ec90-4b06-59d0-a28e-137458f5818d', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 4, 4, 'It happened after this, that there arose war at Gezer with the Philistines: then Sibbecai the Hushathite killed Sippai, of the sons of the giant; and they were subdued.'),
  ('6f1edb7d-d923-5aa1-a554-476a6dceafcb', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 5, 5, 'There was again war with the Philistines; and Elhanan the son of Jair killed Lahmi the brother of Goliath the Gittite, the staff of whose spear was like a weaver''s beam.'),
  ('a789ca16-05b7-5d8e-aad1-5500d2dcdba3', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 6, 6, 'There was again war at Gath, where there was a man of great stature, whose fingers and toes were twenty-four, six [on each hand], and six [on each foot]; and he also was born to the giant.'),
  ('bcc7b8d9-68c1-51a9-adbe-de854d5abc5e', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 7, 7, 'When he defied Israel, Jonathan the son of Shimea David''s brother killed him.'),
  ('1aa7a342-34f3-5cef-a2f3-6d4bfbac4298', 'c0f00616-3d11-5ffb-a2ba-f33572dd2925', NULL, 8, 8, 'These were born to the giant in Gath; and they fell by the hand of David, and by the hand of his servants.'),
  ('d8f818b4-7a21-5649-aa40-6e85418f884c', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 1, 1, 'Satan stood up against Israel, and moved David to number Israel.'),
  ('51a5eed9-a1ce-547e-ae3b-aca39039b0c8', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 2, 2, 'David said to Joab and to the princes of the people, "Go, number Israel from Beersheba even to Dan; and bring me word, that I may know the sum of them."'),
  ('75ab168d-c196-59a8-a914-9d6e64bb7436', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 3, 3, 'Joab said, "May Yahweh make his people a hundred times as many as they are. But, my lord the king, aren''t they all my lord''s servants? Why does my lord require this thing? Why will he be a cause of guilt to Israel?"'),
  ('d267c444-2f36-509b-ab6c-8badcc45e558', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 4, 4, 'Nevertheless the king''s word prevailed against Joab. Therefore Joab departed, and went throughout all Israel, and came to Jerusalem.'),
  ('69ffd6fa-7665-524d-a48b-d31d2547892e', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 5, 5, 'Joab gave up the sum of the numbering of the people to David. All those of Israel were one million one hundred thousand men who drew sword: and in Judah were four hundred seventy thousand men who drew sword.'),
  ('cf32dd68-274d-5df3-afca-3b2fb0db44ad', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 6, 6, 'But he didn''t count Levi and Benjamin among them; for the king''s word was abominable to Joab.'),
  ('215b1a9b-1b60-51cb-a1eb-fe32c86db3c3', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 7, 7, 'God was displeased with this thing; therefore he struck Israel.'),
  ('4e2df89b-f97c-5187-a282-9fe94288bb33', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 8, 8, 'David said to God, "I have sinned greatly, in that I have done this thing. But now, put away, I beg you, the iniquity of your servant; for I have done very foolishly."'),
  ('6c456659-0519-5a15-add6-aabda750d23b', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 9, 9, 'Yahweh spoke to Gad, David''s seer, saying,'),
  ('7f350ccb-2282-501f-a2ec-0f619c09804b', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 10, 10, '"Go and speak to David, saying, ''Thus says Yahweh, "I offer you three things. Choose one of them, that I may do it to you."''"'),
  ('76895666-0f78-5532-a543-d469ccd049d7', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 11, 11, 'So Gad came to David, and said to him, "Thus says Yahweh, ''Take your choice:'),
  ('0e517bdd-c19e-54a9-a570-63f020068767', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 12, 12, 'either three years of famine; or three months to be consumed before your foes, while the sword of your enemies overtakes you; or else three days the sword of Yahweh, even pestilence in the land, and the angel of Yahweh destroying throughout all the borders of Israel. Now therefore consider what answer I shall return to him who sent me.''"'),
  ('43f332cd-8e92-5d85-ab59-d90a5d57236d', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 13, 13, 'David said to Gad, "I am in distress. Let me fall, I pray, into the hand of Yahweh; for his mercies are very great. Let me not fall into the hand of man."'),
  ('9e8db340-583c-5c75-ab40-cfc481ef4c33', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 14, 14, 'So Yahweh sent a pestilence on Israel; and seventy thousand men of Israel fell.'),
  ('f8970ffb-efea-5209-adb5-559d7e524c1b', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 15, 15, 'God sent an angel to Jerusalem to destroy it. As he was about to destroy, Yahweh saw, and he relented of the disaster, and said to the destroying angel, "It is enough; now stay your hand." The angel of Yahweh was standing by the threshing floor of Ornan the Jebusite.'),
  ('384cf347-a399-5115-a4da-eb8b19c5d54d', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 16, 16, 'David lifted up his eyes, and saw the angel of Yahweh standing between earth and the sky, having a drawn sword in his hand stretched out over Jerusalem. Then David and the elders, clothed in sackcloth, fell on their faces.'),
  ('23871266-3112-5473-ab62-8df6efdf1d04', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 17, 17, 'David said to God, "Isn''t it I who commanded the people to be numbered? It is even I who have sinned and done very wickedly; but these sheep, what have they done? Please let your hand, O Yahweh my God, be against me, and against my father''s house; but not against your people, that they should be plagued."'),
  ('a200d503-efa3-5a32-a112-a83100f98ad8', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 18, 18, 'Then the angel of Yahweh commanded Gad to tell David that David should go up, and raise an altar to Yahweh in the threshing floor of Ornan the Jebusite.'),
  ('c1d8e2be-14fe-5573-a462-072cac89ad3b', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 19, 19, 'David went up at the saying of Gad, which he spoke in the name of Yahweh.'),
  ('002e2664-89d5-56dd-a8e9-5e03f20d0515', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 20, 20, 'Ornan turned back, and saw the angel; and his four sons who were with him hid themselves. Now Ornan was threshing wheat.'),
  ('399403d7-54a0-5d28-aac7-8ff245cb66ba', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 21, 21, 'As David came to Ornan, Ornan looked and saw David, and went out of the threshing floor, and bowed himself to David with his face to the ground.'),
  ('3c6a32c1-42a3-5b01-a1b7-21931a0fd0c3', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 22, 22, 'Then David said to Ornan, "Give me the place of this threshing floor, that I may build thereon an altar to Yahweh. You shall sell it to me for the full price, that the plague may be stopped from afflicting the people."'),
  ('72e7b1ba-955e-5f01-a092-afeda4384e52', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 23, 23, 'Ornan said to David, "Take it for yourself, and let my lord the king do that which is good in his eyes. Behold, I give the oxen for burnt offerings, and the threshing instruments for wood, and the wheat for the meal offering. I give it all."'),
  ('b311757d-4bcb-54bd-a603-aac59f974bdf', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 24, 24, 'King David said to Ornan, "No; but I will most certainly buy it for the full price. For I will not take that which is yours for Yahweh, nor offer a burnt offering without cost."'),
  ('af38bd5b-13d1-599b-a98d-75e566ee8e69', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 25, 25, 'So David gave to Ornan six hundred shekels of gold by weight for the place.'),
  ('15c84ce2-befb-5c1e-a6ea-64bf4a5d2823', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 26, 26, 'David built an altar to Yahweh there, and offered burnt offerings and peace offerings, and called on Yahweh; and he answered him from the sky by fire on the altar of burnt offering.'),
  ('a66ff9a2-299d-5df5-aa7e-a491dbf442a9', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 27, 27, 'Yahweh commanded the angel; and he put up his sword again into its sheath.'),
  ('dd5ccdb8-7e0e-5ca8-aae8-ca9a3715e6c7', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 28, 28, 'At that time, when David saw that Yahweh had answered him in the threshing floor of Ornan the Jebusite, then he sacrificed there.'),
  ('f168aeef-e1b5-5556-af54-018d7732051b', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 29, 29, 'For the tabernacle of Yahweh, which Moses made in the wilderness, and the altar of burnt offering, were at that time in the high place at Gibeon.'),
  ('ed1b10e1-e3a9-5a12-a853-d3ae4f1088c3', 'c07cac12-46df-5e6c-ad80-893d257572d8', NULL, 30, 30, 'But David couldn''t go before it to inquire of God; for he was afraid because of the sword of the angel of Yahweh.'),
  ('bd5a0bc3-c8b5-59eb-ae19-3c8584cadd6e', '408a1808-556b-526e-a334-325bdb145396', NULL, 1, 1, 'Then David said, "This is the house of Yahweh God, and this is the altar of burnt offering for Israel."'),
  ('6fbf8e43-f3ff-5cdf-a170-da4432c74531', '408a1808-556b-526e-a334-325bdb145396', NULL, 2, 2, 'David gave orders to gather together the foreigners who were in the land of Israel; and he set masons to cut worked stones to build the house of God.'),
  ('e979cbf7-cb7e-545c-adb5-68a9439b94c7', '408a1808-556b-526e-a334-325bdb145396', NULL, 3, 3, 'David prepared iron in abundance for the nails for the doors of the gates, and for the couplings; and brass in abundance without weight;'),
  ('c9428330-6c6a-5c18-aaec-6fa506e823ec', '408a1808-556b-526e-a334-325bdb145396', NULL, 4, 4, 'and cedar trees without number: for the Sidonians and they of Tyre brought cedar trees in abundance to David.'),
  ('143d8e68-99d8-5ea7-a34a-9b7a1156124f', '408a1808-556b-526e-a334-325bdb145396', NULL, 5, 5, 'David said, "Solomon my son is young and tender, and the house that is to be built for Yahweh must be exceedingly magnificent, of fame and of glory throughout all countries. I will therefore make preparation for it." So David prepared abundantly before his death.'),
  ('3cb6b499-0f9f-54f7-a822-39e58f96af1d', '408a1808-556b-526e-a334-325bdb145396', NULL, 6, 6, 'Then he called for Solomon his son, and commanded him to build a house for Yahweh, the God of Israel.'),
  ('4a3827b0-e7f0-5fc3-adf8-1f28e2a12551', '408a1808-556b-526e-a334-325bdb145396', NULL, 7, 7, 'David said to Solomon his son, "As for me, it was in my heart to build a house to the name of Yahweh my God.'),
  ('9328e42c-78c6-5dcf-a7da-625f72cb9dc0', '408a1808-556b-526e-a334-325bdb145396', NULL, 8, 8, 'But the word of Yahweh came to me, saying, ''You have shed blood abundantly, and have made great wars. You shall not build a house to my name, because you have shed much blood on the earth in my sight.'),
  ('26c3e983-3376-5924-aa47-1a549dff32ed', '408a1808-556b-526e-a334-325bdb145396', NULL, 9, 9, 'Behold, a son shall be born to you, who shall be a man of rest. I will give him rest from all his enemies all around; for his name shall be Solomon, and I will give peace and quietness to Israel in his days.'),
  ('7723b596-f6d9-5297-a547-938e77ebea3e', '408a1808-556b-526e-a334-325bdb145396', NULL, 10, 10, 'He shall build a house for my name; and he shall be my son, and I will be his father; and I will establish the throne of his kingdom over Israel for ever.'''),
  ('fccae252-ba01-50f1-a48d-033964f5cb96', '408a1808-556b-526e-a334-325bdb145396', NULL, 11, 11, 'Now, my son, may Yahweh be with you and prosper you, and build the house of Yahweh your God, as he has spoken concerning you.'),
  ('7b42a401-ad2b-58ea-a1cd-0547ae405570', '408a1808-556b-526e-a334-325bdb145396', NULL, 12, 12, 'May Yahweh give you discretion and understanding, and put you in charge of Israel; that so you may keep the law of Yahweh your God.'),
  ('c5bcd836-3d31-5e83-a687-b51ab5ef0f9f', '408a1808-556b-526e-a334-325bdb145396', NULL, 13, 13, 'Then you will prosper, if you observe to do the statutes and the ordinances which Yahweh gave Moses concerning Israel. Be strong, and courageous. Don''t be afraid, neither be dismayed.'),
  ('3c4d765f-2c94-5af3-a10e-bddc8ae1da58', '408a1808-556b-526e-a334-325bdb145396', NULL, 14, 14, 'Now, behold, in my affliction I have prepared for the house of Yahweh one hundred thousand talents of gold, one million talents of silver, and brass and iron without weight; for it is in abundance. I have also prepared timber and stone; and you may add to them.'),
  ('457efdb3-8d96-5044-af24-43eb363155c0', '408a1808-556b-526e-a334-325bdb145396', NULL, 15, 15, 'There are also workmen with you in abundance, cutters and workers of stone and timber, and all kinds of men who are skillful in every kind of work:'),
  ('8e22a738-493f-5637-a65a-a5e4d4123447', '408a1808-556b-526e-a334-325bdb145396', NULL, 16, 16, 'of the gold, the silver, and the brass, and the iron, there is no number. Arise and be doing, and may Yahweh be with you."'),
  ('60296bfd-e683-5d00-a5f4-2fde180f5b75', '408a1808-556b-526e-a334-325bdb145396', NULL, 17, 17, 'David also commanded all the princes of Israel to help Solomon his son, saying,'),
  ('4290d383-0318-5ff2-a260-9883d49553d7', '408a1808-556b-526e-a334-325bdb145396', NULL, 18, 18, '"Isn''t Yahweh your God with you? Hasn''t he given you rest on every side? For he has delivered the inhabitants of the land into my hand; and the land is subdued before Yahweh, and before his people.'),
  ('27d68511-df25-5259-a7d5-5c9a5b863de9', '408a1808-556b-526e-a334-325bdb145396', NULL, 19, 19, 'Now set your heart and your soul to seek after Yahweh your God. Arise therefore, and build the sanctuary of Yahweh God, to bring the ark of the covenant of Yahweh, and the holy vessels of God, into the house that is to be built to the name of Yahweh."'),
  ('5daac312-169a-5ba0-afbf-2bf3dd8af6d8', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 1, 1, 'Now David was old and full of days; and he made Solomon his son king over Israel.'),
  ('7d722345-6332-5ee7-adc4-832bd6b28dfc', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 2, 2, 'He gathered together all the princes of Israel, with the priests and the Levites.'),
  ('1ccdb45d-adbf-546c-a6ad-c10a400e7eee', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 3, 3, 'The Levites were numbered from thirty years old and upward: and their number by their polls, man by man, was thirty-eight thousand.'),
  ('c812d614-79b0-5327-ad9c-6a4f166bdc8e', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 4, 4, 'David said, "Of these, twenty-four thousand were to oversee the work of the house of Yahweh; six thousand were officers and judges;'),
  ('b37437a8-f1be-52a0-ab10-d2fa96645a9f', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 5, 5, 'four thousand were doorkeepers; and four thousand praised Yahweh with the instruments which I made, for giving praise."'),
  ('77acd64c-11c4-51e6-adc1-0d94a12185d7', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 6, 6, 'David divided them into divisions according to the sons of Levi: Gershon, Kohath, and Merari.'),
  ('f89ade2a-559f-5e75-a4ae-21a49a8d6f81', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 7, 7, 'Of the Gershonites: Ladan and Shimei.'),
  ('a2f0198d-b23e-5bdd-a732-6781f0e5ab30', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 8, 8, 'The sons of Ladan: Jehiel the chief, and Zetham, and Joel, three.'),
  ('da7b2ea5-378f-54d9-ac98-0f030e859d8d', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 9, 9, 'The sons of Shimei: Shelomoth, and Haziel, and Haran, three. These were the heads of the fathers'' [houses] of Ladan.'),
  ('a924c89c-0f5a-5f73-a342-62f526aef1ac', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 10, 10, 'The sons of Shimei: Jahath, Zina, and Jeush, and Beriah. These four were the sons of Shimei.'),
  ('8b132aa9-71bc-5a4e-a18f-f9544b2f67b7', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 11, 11, 'Jahath was the chief, and Zizah the second: but Jeush and Beriah didn''t have many sons; therefore they became a fathers'' house in one reckoning.'),
  ('6ca4414d-b047-5741-a50f-25c70759b61e', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 12, 12, 'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel, four.'),
  ('f377064b-6a68-53fa-a60e-4c1f15f825d6', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 13, 13, 'The sons of Amram: Aaron and Moses; and Aaron was separated, that he should sanctify the most holy things, he and his sons, forever, to burn incense before Yahweh, to minister to him, and to bless in his name, forever.'),
  ('1f4d5723-f667-5e7e-a44b-222fe0d5f416', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 14, 14, 'But as for Moses the man of God, his sons were named among the tribe of Levi.'),
  ('e135f7e9-9ad4-5eba-a4ff-c4611b1a46da', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 15, 15, 'The sons of Moses: Gershom and Eliezer.'),
  ('0525965d-bf77-547a-a99d-6cc43d790975', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 16, 16, 'The sons of Gershom: Shebuel the chief.'),
  ('42c4c169-3550-511a-a309-95e1ee8e8008', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 17, 17, 'The sons of Eliezer were: Rehabiah the chief; and Eliezer had no other sons; but the sons of Rehabiah were very many.'),
  ('83f43fec-850e-5b46-ae4e-ff531c30a5d8', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 18, 18, 'The sons of Izhar: Shelomith the chief.'),
  ('98e8da0d-f420-5e06-a354-a95feaf445e7', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 19, 19, 'The sons of Hebron: Jeriah the chief, Amariah the second, Jahaziel the third, and Jekameam the fourth.'),
  ('d53d286c-ada1-5587-ad3d-d69f44302de1', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 20, 20, 'The sons of Uzziel: Micah the chief, and Isshiah the second.'),
  ('a2ce08e1-828a-51de-a618-9d31fb1042d5', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 21, 21, 'The sons of Merari: Mahli and Mushi. The sons of Mahli: Eleazar and Kish.'),
  ('69f9e4e5-7a72-5dce-a372-0d95c1f5e335', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 22, 22, 'Eleazar died, and had no sons, but daughters only: and their brothers the sons of Kish took them [to wife].'),
  ('3e8e95c8-30ae-57c0-ab95-1ce46f32b887', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 23, 23, 'The sons of Mushi: Mahli, and Eder, and Jeremoth, three.'),
  ('47a66d9c-0cf6-5aae-a1cc-110c1fdf958a', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 24, 24, 'These were the sons of Levi after their fathers'' houses, even the heads of the fathers'' houses of those who were counted individually, in the number of names by their polls, who did the work for the service of the house of Yahweh, from twenty years old and upward.'),
  ('2c69fbdc-7b5d-5435-aebd-0b2499cd5768', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 25, 25, 'For David said, "Yahweh, the God of Israel, has given rest to his people; and he dwells in Jerusalem forever.'),
  ('b5096a14-51e3-5509-a56c-87f301d87301', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 26, 26, 'Also the Levites will no longer need to carry the tabernacle and all its vessels for its service."'),
  ('7a5ea603-9db3-50d2-a135-9cf11fb361c9', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 27, 27, 'For by the last words of David the sons of Levi were numbered, from twenty years old and upward.'),
  ('0cc5a0d2-65eb-5df5-a829-89d1c7eab7d9', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 28, 28, 'For their office was to wait on the sons of Aaron for the service of the house of Yahweh, in the courts, and in the rooms, and in the purifying of all holy things, even the work of the service of the house of God;'),
  ('24f73936-f191-58ba-aa1d-fc776551d738', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 29, 29, 'for the show bread also, and for the fine flour for a meal offering, whether of unleavened wafers, or of that which is baked in the pan, or of that which is soaked, and for all kinds of measure and size;'),
  ('047ee42a-09ae-5029-a848-07661a6955c6', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 30, 30, 'and to stand every morning to thank and praise Yahweh, and likewise in the evening;'),
  ('6009f3d5-f0ba-5889-a33f-a1dff90524df', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 31, 31, 'and to offer all burnt offerings to Yahweh, on the Sabbaths, on the new moons, and on the set feasts, in number according to the ordinance concerning them, continually before Yahweh;'),
  ('2dda50f9-2afe-5b48-a93c-90998f3562ba', '8b580bab-7ea5-505b-aa90-858e0d510747', NULL, 32, 32, 'and that they should keep the duty of the Tent of Meeting, and the duty of the holy place, and the duty of the sons of Aaron their brothers, for the service of the house of Yahweh.'),
  ('a16cf41c-7efd-59a3-a523-9df68960e590', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 1, 1, 'These were the divisions of the sons of Aaron. The sons of Aaron: Nadab and Abihu, Eleazar and Ithamar.'),
  ('5460d556-ea98-58b2-ab10-ed57982a4410', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 2, 2, 'But Nadab and Abihu died before their father, and had no children: therefore Eleazar and Ithamar executed the priest''s office.'),
  ('2e338c88-4808-5da2-a8c0-221e54173539', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 3, 3, 'David with Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, divided them according to their ordering in their service.'),
  ('8fa13441-2d9d-564a-a182-6bed86b07eee', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 4, 4, 'There were more chief men found of the sons of Eleazar than of the sons of Ithamar; and [thus] were they divided: of the sons of Eleazar there were sixteen, heads of fathers'' houses; and of the sons of Ithamar, according to their fathers'' houses, eight.'),
  ('3d862277-7da7-5f1d-ab59-5012437e1cc0', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 5, 5, 'Thus were they divided impartially by drawing lots; for there were princes of the sanctuary, and princes of God, both of the sons of Eleazar, and of the sons of Ithamar.'),
  ('071672de-4948-5429-af69-ba90287b40b2', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 6, 6, 'Shemaiah the son of Nethanel the scribe, who was of the Levites, wrote them in the presence of the king, and the princes, and Zadok the priest, and Ahimelech the son of Abiathar, and the heads of the fathers'' [houses] of the priests and of the Levites; one fathers'' house being taken for Eleazar, and one taken for Ithamar.'),
  ('a60f2229-587a-5ca3-a14e-611db1042a9c', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 7, 7, 'Now the first lot came forth to Jehoiarib, the second to Jedaiah,'),
  ('8be3701c-d3fe-5847-a342-5bffa49a61bd', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 8, 8, 'the third to Harim, the fourth to Seorim,'),
  ('7d99186a-c03c-562e-a0d8-c34526f92e9a', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 9, 9, 'the fifth to Malchijah, the sixth to Mijamin,'),
  ('c6f44d61-c6ae-5319-ad28-a5cad105705b', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 10, 10, 'the seventh to Hakkoz, the eighth to Abijah,'),
  ('9264349a-b5fc-5d95-ac54-4c6553c6d2fe', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 11, 11, 'the ninth to Jeshua, the tenth to Shecaniah,'),
  ('2b0c4212-3845-554e-af94-6630739232a7', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 12, 12, 'the eleventh to Eliashib, the twelfth to Jakim,'),
  ('ab5064c1-779b-5845-a29f-b6862f335600', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 13, 13, 'the thirteenth to Huppah, the fourteenth to Jeshebeab,'),
  ('209eeac8-f852-500a-ab4e-2891fee5fa98', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 14, 14, 'the fifteenth to Bilgah, the sixteenth to Immer,'),
  ('2b095139-0d33-50c0-a41f-6ac5b313e3f2', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 15, 15, 'the seventeenth to Hezir, the eighteenth to Happizzez,'),
  ('c75d2d93-c3a8-5bf6-afa5-138b3f324d78', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 16, 16, 'the nineteenth to Pethahiah, the twentieth to Jehezkel,'),
  ('7fe44d85-329d-58b5-a053-791d69f34251', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 17, 17, 'the twenty-first to Jachin, the twenty-second to Gamul,'),
  ('07f0afd7-c620-56d0-af8f-3f63dfee81b9', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 18, 18, 'the twenty-third to Delaiah, the twenty-fourth to Maaziah.'),
  ('91d89b32-ee8e-5381-aa32-f710ab3dea6d', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 19, 19, 'This was the ordering of them in their service, to come into the house of Yahweh according to the ordinance [given] to them by Aaron their father, as Yahweh, the God of Israel, had commanded him.'),
  ('b327b8af-b0d5-5e80-a53f-bd510da55d3e', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 20, 20, 'Of the rest of the sons of Levi: of the sons of Amram, Shubael; of the sons of Shubael, Jehdeiah.'),
  ('e228d582-359f-5293-a0ea-fa73297a2c7d', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 21, 21, 'Of Rehabiah: of the sons of Rehabiah, Isshiah the chief.'),
  ('78b6d2f2-a309-5271-ad75-211b94425e0a', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 22, 22, 'Of the Izharites, Shelomoth; of the sons of Shelomoth, Jahath.'),
  ('9be30982-6c74-5bf0-a57f-21ddf8a0b51e', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 23, 23, 'The sons [of Hebron]: Jeriah [the chief], Amariah the second, Jahaziel the third, Jekameam the fourth.'),
  ('11f749d7-3ce7-5e46-a6f4-aa5b8467df18', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 24, 24, 'The sons of Uzziel, Micah; of the sons of Micah, Shamir.'),
  ('e4a89e71-6109-5d81-a55d-3e0e6652ed73', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 25, 25, 'The brother of Micah, Isshiah; of the sons of Isshiah, Zechariah.'),
  ('8348288f-df50-5878-a225-f4108617b047', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 26, 26, 'The sons of Merari: Mahli and Mushi; the sons of Jaaziah: Beno.'),
  ('aeab4400-1f0c-5621-adc2-85f3d680f9fe', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 27, 27, 'The sons of Merari: of Jaaziah, Beno, and Shoham, and Zaccur, and Ibri.'),
  ('4ef60570-4993-53f1-ae90-90329141a7f8', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 28, 28, 'Of Mahli: Eleazar, who had no sons.'),
  ('969ba15b-dc65-56a7-af55-aaae6a9988cf', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 29, 29, 'Of Kish; the sons of Kish: Jerahmeel.'),
  ('46e56a3a-41ca-5f48-a846-d2115fd2f978', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 30, 30, 'The sons of Mushi: Mahli, and Eder, and Jerimoth. These were the sons of the Levites after their fathers'' houses.'),
  ('61c98931-6573-5c30-a77e-ba661fd54a0b', 'f8dd14fd-eb3c-5e23-a9a5-6066927c5815', NULL, 31, 31, 'These likewise cast lots even as their brothers the sons of Aaron in the presence of David the king, and Zadok, and Ahimelech, and the heads of the fathers'' [houses] of the priests and of the Levites; the fathers'' [houses] of the chief even as those of his younger brother.'),
  ('c8ec5823-ccf0-562f-a25e-cf264e610df2', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 1, 1, 'Moreover, David and the captains of the army set apart for the service certain of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with harps, with stringed instruments, and with cymbals: and the number of those who did the work according to their service was:'),
  ('0c6d9037-d917-5d49-a48f-6ab5567ee756', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 2, 2, 'of the sons of Asaph: Zaccur, and Joseph, and Nethaniah, and Asharelah, the sons of Asaph, under the hand of Asaph, who prophesied after the order of the king.'),
  ('466e1ba0-77c0-518e-a412-535e2d7c2a07', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 3, 3, 'Of Jeduthun; the sons of Jeduthun: Gedaliah, and Zeri, and Jeshaiah, Hashabiah, and Mattithiah, six, under the hands of their father Jeduthun with the harp, who prophesied in giving thanks and praising Yahweh.'),
  ('f8876984-8ac1-5844-a9de-221f622e8691', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 4, 4, 'Of Heman; the sons of Heman: Bukkiah, Mattaniah, Uzziel, Shebuel, and Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, and Romamti-Ezer, Joshbekashah, Mallothi, Hothir, Mahazioth.'),
  ('86d9400d-5ac7-5b4a-a4cb-4847c19532ba', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 5, 5, 'All these were the sons of Heman the king''s seer in the words of God, to lift up the horn. God gave to Heman fourteen sons and three daughters.'),
  ('019efc09-2378-550f-a0d5-dc276a886280', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 6, 6, 'All these were under the hands of their father for song in the house of Yahweh, with cymbals, stringed instruments, and harps, for the service of the house of God; Asaph, Jeduthun, and Heman being under the order of the king.'),
  ('1c82eca3-708e-5fc2-ac23-fef6c8d15ba3', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 7, 7, 'The number of them, with their brothers who were instructed in singing to Yahweh, even all who were skillful, was two hundred eighty-eight.'),
  ('5fd43f59-88f8-590a-a98b-22abfd5c69e3', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 8, 8, 'They cast lots for their offices, all alike, as well the small as the great, the teacher as the scholar.'),
  ('fec8194c-c64c-56f5-a288-b73a10eb4268', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 9, 9, 'Now the first lot came forth for Asaph to Joseph: the second to Gedaliah; he and his brothers and sons were twelve:'),
  ('0d64273f-be2d-5f42-a222-8dddc8b4ca49', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 10, 10, 'the third to Zaccur, his sons and his brothers, twelve:'),
  ('b06f86ca-a8b1-54ec-af72-84569ea29ba0', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 11, 11, 'the fourth to Izri, his sons and his brothers, twelve:'),
  ('01366cd3-099f-53f3-af70-c1a450290bfa', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 12, 12, 'the fifth to Nethaniah, his sons and his brothers, twelve:'),
  ('a98a842b-fb7c-534c-afaf-74a866c17367', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 13, 13, 'the sixth to Bukkiah, his sons and his brothers, twelve:'),
  ('b72cdf5c-a6fb-543d-a9e4-c81efd06f094', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 14, 14, 'the seventh to Jesharelah, his sons and his brothers, twelve:'),
  ('ab40fcc7-7221-5e11-aae6-56206f78b612', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 15, 15, 'the eighth to Jeshaiah, his sons and his brothers, twelve:'),
  ('747c517b-aa50-57c7-abeb-c9c014c6d375', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 16, 16, 'the ninth to Mattaniah, his sons and his brothers, twelve:'),
  ('fbeab1ce-0389-54c6-a7d4-2ee49f54adfb', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 17, 17, 'the tenth to Shimei, his sons and his brothers, twelve:'),
  ('99409a17-d458-5a04-a4d7-3a2b7b28c496', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 18, 18, 'the eleventh to Azarel, his sons and his brothers, twelve:'),
  ('4c3b5f16-ac23-59e8-a8f1-f9c17d3a509f', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 19, 19, 'the twelfth to Hashabiah, his sons and his brothers, twelve:'),
  ('f48a08db-81cb-5d7c-a475-361c349b93fe', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 20, 20, 'for the thirteenth, Shubael, his sons and his brothers, twelve:'),
  ('f8b0b212-3e16-5c60-a366-7f297a5b5ba2', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 21, 21, 'for the fourteenth, Mattithiah, his sons and his brothers, twelve:'),
  ('facde8c6-5db0-5f89-a5ea-1eacfa6b9378', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 22, 22, 'for the fifteenth to Jeremoth, his sons and his brothers, twelve:'),
  ('99f78cff-1762-5c67-a660-21ed38d308c8', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 23, 23, 'for the sixteenth to Hananiah, his sons and his brothers, twelve:'),
  ('ed309c76-a85c-597f-a8ee-fbd6c0803b6b', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 24, 24, 'for the seventeenth to Joshbekashah, his sons and his brothers, twelve:'),
  ('cb6a9696-d589-5ee9-a8b6-c6985fdd2002', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 25, 25, 'for the eighteenth to Hanani, his sons and his brothers, twelve:'),
  ('9170097a-36c9-5c96-a688-4d6946068490', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 26, 26, 'for the nineteenth to Mallothi, his sons and his brothers, twelve:'),
  ('85812ae2-ea28-522d-ac8a-950cf082a7a9', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 27, 27, 'for the twentieth to Eliathah, his sons and his brothers, twelve:'),
  ('2f7e981e-911f-588a-aa8f-495fb914c879', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 28, 28, 'for the one and twentieth to Hothir, his sons and his brothers, twelve:'),
  ('8221bacd-845b-57c4-a6f4-87203b1f0e80', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 29, 29, 'for the two and twentieth to Giddalti, his sons and his brothers, twelve:'),
  ('635447f1-b42b-59b4-ad3e-926678cda06d', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 30, 30, 'for the three and twentieth to Mahazioth, his sons and his brothers, twelve:'),
  ('63aa6a36-00b4-5c80-a621-6488de5bcb33', 'af2eb79a-fd3a-5942-a00b-8b229e9e7795', NULL, 31, 31, 'for the four and twentieth to Romamti-Ezer, his sons and his brothers, twelve.'),
  ('3c5ae51a-0891-5f4d-ab7c-7b93c8bcb20c', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 1, 1, 'For the divisions of the doorkeepers: of the Korahites, Meshelemiah the son of Kore, of the sons of Asaph.'),
  ('2bea84da-6ab1-5837-ac13-d47390452886', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 2, 2, 'Meshelemiah had sons: Zechariah the firstborn, Jediael the second, Zebadiah the third, Jathniel the fourth,'),
  ('0e262e65-1130-5733-a71f-2335e2206ab4', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 3, 3, 'Elam the fifth, Jehohanan the sixth, Eliehoenai the seventh.'),
  ('edbf3f78-e975-5fc5-ab79-9dd01c9aa247', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 4, 4, 'Obed-Edom had sons: Shemaiah the firstborn, Jehozabad the second, Joah the third, and Sacar the fourth, and Nethanel the fifth,'),
  ('f08db53a-d54b-55af-ab5e-a9a2cab57489', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 5, 5, 'Ammiel the sixth, Issachar the seventh, Peullethai the eighth; for God blessed him.'),
  ('defb275e-115f-51fd-a053-ee22f1eed2d7', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 6, 6, 'Also to Shemaiah his son were sons born, who ruled over the house of their father; for they were mighty men of valor.'),
  ('72a7d813-8ebf-5382-aeea-48885f58f1dc', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 7, 7, 'The sons of Shemaiah: Othni, and Rephael, and Obed, Elzabad, whose brothers were valiant men, Elihu, and Semachiah.'),
  ('d77f99c7-8998-5e49-ac35-08d238419c93', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 8, 8, 'All these were of the sons of Obed-Edom: they and their sons and their brothers, able men in strength for the service; sixty-two of Obed-Edom.'),
  ('e5553486-225a-50d3-ace3-02d1803c9b66', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 9, 9, 'Meshelemiah had sons and brothers, valiant men, eighteen.'),
  ('c83509e9-f0a4-5ae3-ac76-a9abd424d69d', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 10, 10, 'Also Hosah, of the children of Merari, had sons: Shimri the chief, (for though he was not the firstborn, yet his father made him chief),'),
  ('681cd7ce-00c3-5040-ad3b-0b1a3bd5710a', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 11, 11, 'Hilkiah the second, Tebaliah the third, Zechariah the fourth: all the sons and brothers of Hosah were thirteen.'),
  ('bab2546e-fb6a-5780-af63-5c5a47d02a03', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 12, 12, 'Of these were the divisions of the doorkeepers, even of the chief men, having offices like their brothers, to minister in the house of Yahweh.'),
  ('82bcb1bf-4991-5d12-aa44-6a2aa2695254', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 13, 13, 'They cast lots, the small as well as the great, according to their fathers'' houses, for every gate.'),
  ('2f48452a-0074-5037-a562-959638da78c3', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 14, 14, 'The lot eastward fell to Shelemiah. Then for Zechariah his son, a wise counselor, they cast lots; and his lot came out northward.'),
  ('5d7abdd3-68eb-5b64-a935-145005489c37', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 15, 15, 'To Obed-Edom southward; and to his sons the storehouse.'),
  ('e4c44dc6-0059-50d6-a5ad-a36db0cbd177', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 16, 16, 'To Shuppim and Hosah westward, by the gate of Shallecheth, at the causeway that goes up, watch against watch.'),
  ('32e65ead-3098-5411-af5f-7483a582bb19', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 17, 17, 'Eastward were six Levites, northward four a day, southward four a day, and for the storehouse two and two.'),
  ('e578a403-9040-59f1-a70e-b96719275ab5', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 18, 18, 'For Parbar westward, four at the causeway, and two at Parbar.'),
  ('f58f29db-24d5-57bb-a75b-4b578de85a0c', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 19, 19, 'These were the divisions of the doorkeepers; of the sons of the Korahites, and of the sons of Merari.'),
  ('1cfad594-dc2b-501c-a88d-d189b013c8e6', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 20, 20, 'Of the Levites, Ahijah was over the treasures of the house of God, and over the treasures of the dedicated things.'),
  ('d9294dd1-3fce-53d3-aa5f-ec6072146b69', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 21, 21, 'The sons of Ladan, the sons of the Gershonites belonging to Ladan, the heads of the fathers'' [houses] belonging to Ladan the Gershonite: Jehieli.'),
  ('a42d2d83-24bd-5990-a4ea-96c9ee77d7f2', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 22, 22, 'The sons of Jehieli: Zetham, and Joel his brother, over the treasures of the house of Yahweh.'),
  ('2c174dba-1786-5989-a38a-e37a2aa8b480', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 23, 23, 'Of the Amramites, of the Izharites, of the Hebronites, of the Uzzielites:'),
  ('63894313-ce34-5d6e-ab51-42038c43e4ad', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 24, 24, 'and Shebuel the son of Gershom, the son of Moses, was ruler over the treasures.'),
  ('af3c101c-514d-5345-a3fe-c94afe1489e3', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 25, 25, 'His brothers: of Eliezer [came] Rehabiah his son, and Jeshaiah his son, and Joram his son, and Zichri his son, and Shelomoth his son.'),
  ('10df18ea-1812-5595-af3a-77618775773e', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 26, 26, 'This Shelomoth and his brothers were over all the treasures of the dedicated things, which David the king, and the heads of the fathers'' [houses], the captains over thousands and hundreds, and the captains of the army, had dedicated.'),
  ('d8e28644-4b9a-5d9e-a4f4-cc0f7514b5f4', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 27, 27, 'Out of the spoil won in battles did they dedicate to repair the house of Yahweh.'),
  ('f4261945-9ae8-5a83-a2a7-4705d19d72c1', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 28, 28, 'All that Samuel the seer, and Saul the son of Kish, and Abner the son of Ner, and Joab the son of Zeruiah, had dedicated, whoever had dedicated anything, it was under the hand of Shelomoth, and of his brothers.'),
  ('1dcb7c26-3cc3-5781-ab49-a04f6afdde3d', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 29, 29, 'Of the Izharites, Chenaniah and his sons were for the outward business over Israel, for officers and judges.'),
  ('91a6349b-e506-5aab-a7e3-356d554220ab', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 30, 30, 'Of the Hebronites, Hashabiah and his brothers, men of valor, one thousand seven hundred, had the oversight of Israel beyond the Jordan westward, for all the business of Yahweh, and for the service of the king.'),
  ('f8ef34a1-57ad-5582-ab20-1f323d1a8c7c', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 31, 31, 'Of the Hebronites was Jerijah the chief, even of the Hebronites, according to their generations by fathers'' [houses]. In the fortieth year of the reign of David they were sought for, and there were found among them mighty men of valor at Jazer of Gilead.'),
  ('0a400b1d-4de8-5d77-af4c-3f833c94cbfe', '66622fd4-dd1e-5be8-aef8-f3d165099621', NULL, 32, 32, 'His brothers, men of valor, were two thousand seven hundred, heads of fathers'' [houses], whom king David made overseers over the Reubenites, and the Gadites, and the half-tribe of the Manassites, for every matter pertaining to God, and for the affairs of the king.'),
  ('48639907-f412-56b4-a48b-e98f1ce1a896', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 1, 1, 'Now the children of Israel after their number, the heads of fathers'' [houses] and the captains of thousands and of hundreds, and their officers who served the king, in any matter of the divisions which came in and went out month by month throughout all the months of the year--of every division were twenty-four thousand.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('72d0a940-601e-5590-a3de-d40f49bbe050', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 2, 2, 'Over the first division for the first month was Jashobeam the son of Zabdiel: and in his division were twenty-four thousand.'),
  ('3a5ca285-e23e-54d8-a7a3-6bf6e30e14da', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 3, 3, '[He was] of the children of Perez, the chief of all the captains of the army for the first month.'),
  ('ca40db05-36e5-5fe2-afb1-96eb5dc79dde', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 4, 4, 'Over the division of the second month was Dodai the Ahohite, and his division; and Mikloth the ruler: and in his division were twenty-four thousand.'),
  ('3da9cf2a-e3ac-5d33-a944-11e328387f5c', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 5, 5, 'The third captain of the army for the third month was Benaiah, the son of Jehoiada the priest, chief: and in his division were twenty-four thousand.'),
  ('9e868675-c651-5a6a-acfb-f1fc0e108d29', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 6, 6, 'This is that Benaiah, who was the mighty man of the thirty, and over the thirty: and [of] his division was Ammizabad his son.'),
  ('1f5d9e94-de41-559c-ae8b-ec36d04b771f', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 7, 7, 'The fourth [captain] for the fourth month was Asahel the brother of Joab, and Zebadiah his son after him: and in his division were twenty-four thousand.'),
  ('84f5d788-6eaf-5a40-aaab-ed0258b3f235', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 8, 8, 'The fifth captain for this fifth month was Shamhuth the Izrahite: and in his division were twenty-four thousand.'),
  ('c991ed39-97e5-5335-ab14-488b98ce4b16', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 9, 9, 'The sixth [captain] for the sixth month was Ira the son of Ikkesh the Tekoite: and in his division were twenty-four thousand.'),
  ('20967cdd-d896-5a03-ad30-a94e0df75db9', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 10, 10, 'The seventh [captain] for the seventh month was Helez the Pelonite, of the children of Ephraim: and in his division were twenty-four thousand.'),
  ('4a58f4e4-bcab-5240-ad92-c83c7d59bd42', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 11, 11, 'The eighth [captain] for the eighth month was Sibbecai the Hushathite, of the Zerahites: and in his division were twenty-four thousand.'),
  ('a4453d7b-94cb-53b0-ad5e-91cd77128253', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 12, 12, 'The ninth [captain] for the ninth month was Abiezer the Anathothite, of the Benjamites: and in his division were twenty-four thousand.'),
  ('5c57a8e0-5677-5366-a28e-974e087f4aa8', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 13, 13, 'The tenth [captain] for the tenth month was Maharai the Netophathite, of the Zerahites: and in his division were Twenty-four thousand.'),
  ('34d17e11-5f16-5400-a969-4ea796e97228', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 14, 14, 'The eleventh [captain] for the eleventh month was Benaiah the Pirathonite, of the children of Ephraim: and in his division were twenty-four thousand.'),
  ('e9e6dbd9-33b3-5c69-af9d-25782372c5cc', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 15, 15, 'The twelfth [captain] for the twelfth month was Heldai the Netophathite, of Othniel: and in his division were twenty-four thousand.'),
  ('c9ac5b11-5f11-596c-a60e-a4368746aa23', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 16, 16, 'Furthermore over the tribes of Israel: of the Reubenites was Eliezer the son of Zichri the ruler: of the Simeonites, Shephatiah the son of Maacah:'),
  ('8208716e-7c85-5b7d-afcf-aa2db53cc624', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 17, 17, 'of Levi, Hashabiah the son of Kemuel: of Aaron, Zadok:'),
  ('78002f67-292b-5dbf-a8af-bc31839a5922', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 18, 18, 'of Judah, Elihu, one of the brothers of David: of Issachar, Omri the son of Michael:'),
  ('72c93541-c271-5101-a6dc-5bbef6d7e20e', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 19, 19, 'of Zebulun, Ishmaiah the son of Obadiah: of Naphtali, Jeremoth the son of Azriel:'),
  ('caf1582a-6e25-5b57-a68d-10c578d5fe3f', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 20, 20, 'of the children of Ephraim, Hoshea the son of Azaziah: of the half-tribe of Manasseh, Joel the son of Pedaiah:'),
  ('ade9b99c-5615-56cb-a686-4c991b2cbc84', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 21, 21, 'of the half-tribe of Manasseh in Gilead, Iddo the son of Zechariah: of Benjamin, Jaasiel the son of Abner:'),
  ('070d2457-25e5-5044-a713-200f6241cb32', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 22, 22, 'of Dan, Azarel the son of Jeroham. These were the captains of the tribes of Israel.'),
  ('f8e62915-fb0f-562b-ad55-e66c68e70fcb', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 23, 23, 'But David didn''t take the number of them from twenty years old and under, because Yahweh had said he would increase Israel like the stars of the sky.'),
  ('5fdf0c1a-7a3c-54a5-a188-ab2b11a15a67', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 24, 24, 'Joab the son of Zeruiah began to number, but didn''t finish; and there came wrath for this on Israel; neither was the number put into the account in the chronicles of king David.'),
  ('1b0d6dd4-558e-56f8-ab2d-360994b554e5', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 25, 25, 'Over the king''s treasures was Azmaveth the son of Adiel: and over the treasures in the fields, in the cities, and in the villages, and in the towers, was Jonathan the son of Uzziah:'),
  ('dc0a7d32-9d58-5747-ab22-0c20d21c7920', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 26, 26, 'Over those who did the work of the field for tillage of the ground was Ezri the son of Chelub:'),
  ('9716c7be-41d6-550c-af3c-28b16925142b', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 27, 27, 'and over the vineyards was Shimei the Ramathite: and over the increase of the vineyards for the winecellars was Zabdi the Shiphmite:'),
  ('9e11ac47-162e-5f94-a721-3d48911a8072', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 28, 28, 'and over the olive trees and the sycamore trees that were in the lowland was Baal Hanan the Gederite: and over the cellars of oil was Joash:'),
  ('45a1c10f-93bc-5f1b-a3b5-38a7c16f6606', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 29, 29, 'and over the herds that fed in Sharon was Shitrai the Sharonite: and over the herds that were in the valleys was Shaphat the son of Adlai:'),
  ('020d3031-b2a6-53f6-ab38-52a974577268', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 30, 30, 'and over the camels was Obil the Ishmaelite: and over the donkeys was Jehdeiah the Meronothite: and over the flocks was Jaziz the Hagrite.'),
  ('e40a29c6-7169-58b3-aae4-bda5f185cfa9', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 31, 31, 'All these were the rulers of the substance which was king David''s.'),
  ('35c8e134-d235-5f18-a340-ccaf7ed5e28b', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 32, 32, 'Also Jonathan, David''s uncle, was a counselor, a man of understanding, and a scribe: and Jehiel the son of Hachmoni was with the king''s sons:'),
  ('37417147-7e8d-5a96-ac19-a06608b2f998', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 33, 33, 'Ahithophel was the king''s counselor: and Hushai the Archite was the king''s friend:'),
  ('85f7b0cc-59fc-5207-a9ee-d1c1207d5b8d', 'e6a14f9f-6ff8-56cb-a85f-c7ef84ce85d2', NULL, 34, 34, 'and after Ahithophel was Jehoiada the son of Benaiah, and Abiathar: and the captain of the king''s army was Joab.'),
  ('7c6cf5bb-fddb-526e-a2b2-0e59fd4f5e48', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 1, 1, 'David assembled all the princes of Israel, the princes of the tribes, and the captains of the companies who served the king by division, and the captains of thousands, and the captains of hundreds, and the rulers over all the substance and possessions of the king and of his sons, with the officers, and the mighty men, even all the mighty men of valor, to Jerusalem.'),
  ('50672949-402b-51d4-a858-ca324af3a51c', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 2, 2, 'Then David the king stood up on his feet, and said, "Hear me, my brothers, and my people! As for me, it was in my heart to build a house of rest for the ark of the covenant of Yahweh, and for the footstool of our God; and I had prepared for the building.'),
  ('bccc2618-9818-5677-a688-60cda4bc89ac', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 3, 3, 'But God said to me, ''You shall not build a house for my name, because you are a man of war, and have shed blood.'''),
  ('010f1db0-179a-5329-a79e-f74117fd1a5b', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 4, 4, 'However Yahweh, the God of Israel, chose me out of all the house of my father to be king over Israel forever. For he has chosen Judah to be prince; and in the house of Judah, the house of my father; and among the sons of my father he took pleasure in me to make me king over all Israel.'),
  ('9ee48511-c8f3-5df4-a5c1-a2e758b023c4', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 5, 5, 'Of all my sons (for Yahweh has given me many sons), he has chosen Solomon my son to sit on the throne of Yahweh''s kingdom over Israel.'),
  ('31ebd679-e6ba-5764-a3e9-04e905cc131c', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 6, 6, 'He said to me, ''Solomon, your son, shall build my house and my courts; for I have chosen him to be my son, and I will be his father.'),
  ('b2426a12-336c-57d2-a786-b58d8ecef657', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 7, 7, 'I will establish his kingdom forever, if he continues to do my commandments and my ordinances, as at this day.'''),
  ('24705a12-8a40-562e-a3e3-ee2105ba5fe3', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 8, 8, 'Now therefore, in the sight of all Israel, the assembly of Yahweh, and in the audience of our God, observe and seek out all the commandments of Yahweh your God; that you may possess this good land, and leave it for an inheritance to your children after you forever.'),
  ('fd554f61-cdc7-5a79-a31b-09ef49e20b58', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 9, 9, 'You, Solomon my son, know the God of your father, and serve him with a perfect heart and with a willing mind; for Yahweh searches all hearts, and understands all the imaginations of the thoughts. If you seek him, he will be found by you; but if you forsake him, he will cast you off forever.'),
  ('4b3de726-d7ab-5d46-a82e-718ea1f0d871', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 10, 10, 'Take heed now; for Yahweh has chosen you to build a house for the sanctuary. Be strong, and do it."'),
  ('4e9a49ab-2fda-5c32-a918-1598cb926a08', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 11, 11, 'Then David gave to Solomon his son the pattern of the porch [of the temple], and of its houses, and of its treasuries, and of the upper rooms of it, and of the inner rooms of it, and of the place of the mercy seat;'),
  ('c8367883-f7fa-5dd0-a9d3-8b633deb3225', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 12, 12, 'and the pattern of all that he had by the Spirit, for the courts of the house of Yahweh, and for all the surrounding rooms, for the treasuries of the house of God, and for the treasuries of the dedicated things;'),
  ('b7fd4e4f-85c4-5fff-a737-600cbcaed206', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 13, 13, 'also for the divisions of the priests and the Levites, and for all the work of the service of the house of Yahweh, and for all the vessels of service in the house of Yahweh;'),
  ('9dddf5b1-aa98-5ae0-ab38-7d8247fa79f5', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 14, 14, 'of gold by weight for the [vessels of] gold, for all vessels of every kind of service; [of silver] for all the vessels of silver by weight, for all vessels of every kind of service;'),
  ('0e205374-7fe4-5802-a904-7851833c452b', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 15, 15, 'by weight also for the lampstands of gold, and for its lamps, of gold, by weight for every lampstand and for its lamps; and for the lampstands of silver, [silver] by weight for [every] lampstand and for its lamps, according to the use of every lampstand;'),
  ('7c95f0f1-5fb0-59cc-a4f8-a942b619e11b', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 16, 16, 'and the gold by weight for the tables of show bread, for every table; and silver for the tables of silver;'),
  ('a84c3f1f-f0fd-513c-a884-58d0fbc0880c', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 17, 17, 'and the forks, and the basins, and the cups, of pure gold; and for the golden bowls by weight for every bowl; and for the silver bowls by weight for every bowl;'),
  ('4e7a17e6-33a3-50a9-a0a4-db232a5eb370', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 18, 18, 'and for the altar of incense refined gold by weight; and gold for the pattern of the chariot, [even] the cherubim, that spread out [their wings], and covered the ark of the covenant of Yahweh.'),
  ('7951f7f0-d2cf-56e4-a365-fa12ac2da8de', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 19, 19, '"All this," said David, "I have been made to understand in writing from the hand of Yahweh, even all the works of this pattern."'),
  ('88433d60-8892-5ee6-a7ea-dbd87a30e1a6', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 20, 20, 'David said to Solomon his son, "Be strong and courageous, and do it. Don''t be afraid, nor be dismayed; for Yahweh God, even my God, is with you. He will not fail you, nor forsake you, until all the work for the service of the house of Yahweh is finished.'),
  ('ca4ae95f-b1b8-515c-ac15-e9fb2cfcb8a2', 'c0e4864d-10e6-56af-a689-4be0b57c9226', NULL, 21, 21, 'Behold, there are the divisions of the priests and the Levites, for all the service of the house of God. There shall be with you in all kinds of work every willing man who has skill, for any kind of service. Also the captains and all the people will be entirely at your command."'),
  ('ed6fd6c4-e421-55c6-a0cd-d7930dcce662', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 1, 1, 'David the king said to all the assembly, "Solomon my son, whom alone God has chosen, is yet young and tender, and the work is great; for the palace is not for man, but for Yahweh God.'),
  ('22f80d08-216a-5395-a353-13ced168d15a', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 2, 2, 'Now I have prepared with all my might for the house of my God the gold for the [things of] gold, and the silver for the [things of] silver, and the brass for the [things of] brass, the iron for the [things of] iron, and wood for the [things of] wood; onyx stones, and [stones] to be set, stones for inlaid work, and of various colors, and all kinds of precious stones, and marble stones in abundance.'),
  ('9c0ba231-efdc-58e1-a933-53d4d8e6fcfd', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 3, 3, 'In addition, because I have set my affection on the house of my God, since I have a treasure of my own of gold and silver, I give it to the house of my God, over and above all that I have prepared for the holy house,'),
  ('6bbbee84-06aa-558b-a85b-008168e6408b', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 4, 4, 'even three thousand talents of gold, of the gold of Ophir, and seven thousand talents of refined silver, with which to overlay the walls of the houses;'),
  ('954aec23-ae05-5732-ae92-d142a19966d5', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 5, 5, 'of gold for the [things of] gold, and of silver for the [things of] silver, and for all kinds of work [to be made] by the hands of artificers. Who then offers willingly to consecrate himself this day to Yahweh?"'),
  ('6c3eedf5-2645-5d6c-a461-a9f5cd367a71', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 6, 6, 'Then the princes of the fathers'' [houses], and the princes of the tribes of Israel, and the captains of thousands and of hundreds, with the rulers over the king''s work, offered willingly;'),
  ('b9ac4d1d-f390-500d-a60a-026fdb3d25d0', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 7, 7, 'and they gave for the service of the house of God of gold five thousand talents and ten thousand darics, and of silver ten thousand talents, and of brass eighteen thousand talents, and of iron a hundred thousand talents.'),
  ('7392d023-bb8b-556f-a153-6aa612209dce', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 8, 8, 'They with whom [precious] stones were found gave them to the treasure of the house of Yahweh, under the hand of Jehiel the Gershonite.'),
  ('91ba7b50-05cc-5418-a85e-1f3ff5682072', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 9, 9, 'Then the people rejoiced, because they offered willingly, because with a perfect heart they offered willingly to Yahweh: and David the king also rejoiced with great joy.'),
  ('30f402b7-5de5-54b2-ac59-6d1c458cc273', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 10, 10, 'Therefore David blessed Yahweh before all the assembly; and David said, "You are blessed, Yahweh, the God of Israel our father, forever and ever.'),
  ('574088f0-4fb0-50c1-a532-0b484632f8b3', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 11, 11, 'Yours, Yahweh, is the greatness, the power, the glory, the victory, and the majesty! For all that is in the heavens and in the earth is yours. Yours is the kingdom, Yahweh, and you are exalted as head above all.'),
  ('86f6442c-df9c-55f6-ac83-198b1f24c681', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 12, 12, 'Both riches and honor come from you, and you rule over all; and in your hand is power and might; and it is in your hand to make great, and to give strength to all.'),
  ('925c37d2-4c7a-54d3-a8a4-a02281d74dfe', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 13, 13, 'Now therefore, our God, we thank you, and praise your glorious name.'),
  ('43ea3e7a-aa2a-52ac-a821-d4226f00f41e', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 14, 14, 'But who am I, and what is my people, that we should be able to offer so willingly as this? For all things come from you, and of your own have we given you.'),
  ('0756991c-1199-5279-ab34-df445b509e7b', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 15, 15, 'For we are strangers before you, and foreigners, as all our fathers were. Our days on the earth are as a shadow, and there is no remaining.'),
  ('d32f18fb-0eb2-51f4-a746-54663216d747', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 16, 16, 'Yahweh our God, all this store that we have prepared to build you a house for your holy name comes from your hand, and is all your own.'),
  ('9ea62475-8d14-5437-a369-df1873231234', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 17, 17, 'I know also, my God, that you try the heart, and have pleasure in uprightness. As for me, in the uprightness of my heart I have willingly offered all these things. Now have I seen with joy your people, that are present here, offer willingly to you.'),
  ('d889ce4b-85d5-5f60-ad12-66f21447fc88', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 18, 18, 'Yahweh, the God of Abraham, of Isaac, and of Israel, our fathers, keep this forever in the imagination of the thoughts of the heart of your people, and prepare their heart for you;'),
  ('c4d8d50f-bc4e-540b-a73b-e32d81ca67d3', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 19, 19, 'and give to Solomon my son a perfect heart, to keep your commandments, your testimonies, and your statutes, and to do all these things, and to build the palace, for which I have made provision."'),
  ('fd500b4b-9a9d-5c16-a308-6af05a6837ea', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 20, 20, 'David said to all the assembly, "Now bless Yahweh your God!" All the assembly blessed Yahweh, the God of their fathers, and bowed down their heads and prostrated themselves before Yahweh and the king.'),
  ('4590816a-f568-5ad2-ae32-d77410fa81c5', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 21, 21, 'They sacrificed sacrifices to Yahweh, and offered burnt offerings to Yahweh, on the next day after that day, even one thousand bulls, one thousand rams, and one thousand lambs, with their drink offerings, and sacrifices in abundance for all Israel,'),
  ('26fab967-5523-5627-a509-44e96a45fef8', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 22, 22, 'and ate and drink before Yahweh on that day with great gladness. They made Solomon the son of David king the second time, and anointed him to Yahweh to be prince, and Zadok to be priest.'),
  ('dda0873a-2000-5f7f-a64c-1e79cafadb33', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 23, 23, 'Then Solomon sat on the throne of Yahweh as king instead of David his father, and prospered; and all Israel obeyed him.'),
  ('9acfb417-e929-5953-a1fe-feafa36f25c6', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 24, 24, 'All the princes, the mighty men, and also all of the sons of king David submitted themselves to Solomon the king.'),
  ('d5867ad1-2b30-5197-ab33-9c01a7a63bd4', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 25, 25, 'Yahweh magnified Solomon exceedingly in the sight of all Israel, and bestowed on him such royal majesty as had not been on any king before him in Israel.'),
  ('b71d43ae-e3e0-5f39-ac04-d7250979dda9', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 26, 26, 'Now David the son of Jesse reigned over all Israel.'),
  ('7e00d624-5568-5769-acae-2c9bc32b13e9', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 27, 27, 'The time that he reigned over Israel was forty years; he reigned seven years in Hebron, and thirty-three [years] reigned he in Jerusalem.'),
  ('6c71fb63-9175-5ea9-a452-8ca2c2c98d32', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 28, 28, 'He died in a good old age, full of days, riches, and honor: and Solomon his son reigned in his place.'),
  ('be44378e-22ed-5c76-ad64-e3b83f22b734', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 29, 29, 'Now the acts of David the king, first and last, behold, they are written in the history of Samuel the seer, and in the history of Nathan the prophet, and in the history of Gad the seer,'),
  ('86db74ca-27b9-5240-a8c4-2fc5ee161269', 'cef00703-f8e6-5a9c-a779-76556c37c061', NULL, 30, 30, 'with all his reign and his might, and the times that went over him, and over Israel, and over all the kingdoms of the countries.'),
  ('ff5e9930-287b-5c1a-a173-f169b7da19ef', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 1, 1, 'Solomon the son of David was strengthened in his kingdom, and Yahweh his God was with him, and magnified him exceedingly.'),
  ('da2e0b44-1f72-50be-a156-8ef7c1544956', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 2, 2, 'Solomon spoke to all Israel, to the captains of thousands and of hundreds, and to the judges, and to every prince in all Israel, the heads of the fathers'' [houses].'),
  ('24570f7d-7dba-53ad-ac7b-30fae3333fb3', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 3, 3, 'So Solomon, and all the assembly with him, went to the high place that was at Gibeon; for there was the Tent of Meeting of God, which Moses the servant of Yahweh had made in the wilderness.'),
  ('ed59e385-52b3-5b39-a84c-4f43f0e917ec', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 4, 4, 'But David had brought the ark of God up from Kiriath Jearim to the place that David had prepared for it; for he had pitched a tent for it at Jerusalem.'),
  ('90124e2e-9906-5aed-a879-93e091ec3da8', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 5, 5, 'Moreover the bronze altar, that Bezalel the son of Uri, the son of Hur, had made, was there before the tabernacle of Yahweh: and Solomon and the assembly were seeking counsel there.'),
  ('721c58ff-6a63-5026-ae37-23f7e79d82d8', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 6, 6, 'Solomon went up there to the bronze altar before Yahweh, which was at the Tent of Meeting, and offered one thousand burnt offerings on it.'),
  ('8aa5808e-5e5d-544e-aa9b-b8d76f86d225', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 7, 7, 'In that night God appeared to Solomon, and said to him, "Ask what I shall give you."'),
  ('6654f901-b90e-5872-a0d1-418e7713bd5c', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 8, 8, 'Solomon said to God, "You have shown great loving kindness to David my father, and have made me king in his place.'),
  ('f3481010-0b70-53c8-a249-a69617704baf', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 9, 9, 'Now, Yahweh God, let your promise to David my father be established; for you have made me king over a people like the dust of the earth in multitude.'),
  ('b9df5593-c109-53fc-a16f-d189bc4fbdcb', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 10, 10, 'Now give me wisdom and knowledge, that I may go out and come in before this people; for who can judge this your people, that is so great?"'),
  ('b85f7ff3-c575-5d17-a7ae-59cbaca88019', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 11, 11, 'God said to Solomon, "Because this was in your heart, and you have not asked riches, wealth, or honor, nor the life of those who hate you, neither yet have asked long life; but have asked wisdom and knowledge for yourself, that you may judge my people, over whom I have made you king:'),
  ('776f1e3f-8348-5c13-a141-7219ace17ace', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 12, 12, 'wisdom and knowledge is granted to you. I will give you riches, wealth, and honor, such as none of the kings have had who have been before you; neither shall there any after you have the like."'),
  ('3f9989e5-0a14-5269-ad65-780664dc274b', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 13, 13, 'So Solomon came from the high place that was at Gibeon, from before the Tent of Meeting, to Jerusalem; and he reigned over Israel.'),
  ('9d298775-369c-58f6-a8c5-db51c6dcc2f8', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 14, 14, 'Solomon gathered chariots and horsemen: and he had one thousand four hundred chariots, and twelve thousand horsemen, that he placed in the chariot cities, and with the king at Jerusalem.'),
  ('5a360916-2679-5b0a-ade5-78e450ec560b', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 15, 15, 'The king made silver and gold to be in Jerusalem as stones, and cedars made he to be as the sycamore trees that are in the lowland, for abundance.'),
  ('4e1d415d-ff33-55cf-a5c4-24bc98dfd9d2', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 16, 16, 'The horses which Solomon had were brought out of Egypt and from Kue; the king''s merchants purchased them from Kue.'),
  ('fd8fb853-e00b-5c60-a8d9-1607d491a454', 'b3870242-cd59-5681-a636-fa94abf433de', NULL, 17, 17, 'They brought up and brought out of Egypt a chariot for six hundred pieces of silver, and a horse for one hundred fifty: and so for all the kings of the Hittites, and the kings of Syria, did they bring them out by their means.'),
  ('b35c4082-bda1-5521-a38b-dbaa9d663f6f', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 1, 1, 'Now Solomon purposed to build a house for the name of Yahweh, and a house for his kingdom.'),
  ('7b994032-6f1b-531c-ad84-a44b97193a33', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 2, 2, 'Solomon counted out seventy thousand men to bear burdens, and eighty thousand men who were stone cutters in the mountains, and three thousand and six hundred to oversee them.'),
  ('492c234b-e4e4-5f56-a889-459438a1a16c', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 3, 3, 'Solomon sent to Huram the king of Tyre, saying, "As you dealt with David my father, and sent him cedars to build him a house in which to dwell, [even so deal with me].'),
  ('97ae7b4f-30ed-5b03-a89d-c7282a729cc7', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 4, 4, 'Behold, I am about to build a house for the name of Yahweh my God, to dedicate it to him, and to burn before him incense of sweet spices, and for the continual show bread, and for the burnt offerings morning and evening, on the Sabbaths, and on the new moons, and on the set feasts of Yahweh our God. This is [an ordinance] forever to Israel.'),
  ('e637d16c-6248-58e0-a79a-dec7a8c67d7e', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 5, 5, '"The house which I build is great; for our God is great above all gods.'),
  ('86c2d931-c904-51e4-ae22-a449026d30d5', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 6, 6, 'But who is able to build him a house, since heaven and the heaven of heavens can''t contain him? who am I then, that I should build him a house, except just to burn incense before him?'),
  ('ebbb32d6-fd0a-561d-ac14-d82469a1dd3f', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 7, 7, '"Now therefore send me a man skillful to work in gold, and in silver, and in brass, and in iron, and in purple, and crimson, and blue, and who knows how to engrave [all kinds of] engravings, [to be] with the skillful men who are with me in Judah and in Jerusalem, whom David my father did provide.'),
  ('c0cf2003-a927-5cb5-adec-aec95ccd6dae', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 8, 8, '"Send me also cedar trees, fir trees, and algum trees, out of Lebanon; for I know that your servants know how to cut timber in Lebanon: and behold, my servants shall be with your servants,'),
  ('3336647f-68ca-5090-a221-3dea2b3373a2', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 9, 9, 'even to prepare me timber in abundance; for the house which I am about to build shall be great and wonderful.'),
  ('6f8ccc69-2ea1-56ac-a24f-d0f19ca32041', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 10, 10, 'Behold, I will give to your servants, the cutters who cut timber, twenty thousand measures of beaten wheat, and twenty thousand measures of barley, and twenty thousand baths of wine, and twenty thousand baths of oil."'),
  ('e86b5a1d-8011-57d3-a7f8-2374ef6df782', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 11, 11, 'Then Huram the king of Tyre answered in writing, which he sent to Solomon, "Because Yahweh loves his people, he has made you king over them."'),
  ('1cad5f13-b1ad-57a8-af11-c085d8dfc08e', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 12, 12, 'Huram continued, "Blessed be Yahweh, the God of Israel, that made heaven and earth, who has given to David the king a wise son, endowed with discretion and understanding, that should build a house for Yahweh, and a house for his kingdom.'),
  ('e1d47f68-c12d-562e-a5c5-575d8b7ae86c', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 13, 13, 'Now I have sent a skillful man, endowed with understanding, of Huram my father''s,'),
  ('749d4adf-61c7-580f-a7ae-5b2e5e3a9647', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 14, 14, 'the son of a woman of the daughters of Dan; and his father was a man of Tyre, skillful to work in gold, and in silver, in brass, in iron, in stone, and in timber, in purple, in blue, and in fine linen, and in crimson, also to engrave any kind of engraving, and to devise any device; that there may be a place appointed to him with your skillful men, and with the skillful men of my lord David your father.'),
  ('b88219b6-a860-5262-a2d2-05f245450834', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 15, 15, '"Now therefore the wheat and the barley, the oil and the wine, which my lord has spoken of, let him send to his servants:'),
  ('a5c786e2-d52c-5986-af5b-3ac4eaf48ea6', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 16, 16, 'and we will cut wood out of Lebanon, as much as you shall need; and we will bring it to you in floats by sea to Joppa; and you shall carry it up to Jerusalem."'),
  ('c72af194-4b46-54e4-a5d5-7d1ee8d8d04d', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 17, 17, 'Solomon numbered all the foreigners who were in the land of Israel, after the numbering with which David his father had numbered them; and they were found one hundred fifty-three thousand six hundred.'),
  ('fdaf4988-86ea-55f1-aa77-bf1d26505d4a', '6f618060-6ff7-599e-a042-88f08995226d', NULL, 18, 18, 'He set seventy thousand of them to bear burdens, and eighty thousand who were stone cutters in the mountains, and three thousand six hundred overseers to set the people at work.'),
  ('630b2868-809a-5761-ab59-28715e7b4839', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 1, 1, 'Then Solomon began to build the house of Yahweh at Jerusalem on Mount Moriah, where [Yahweh] appeared to David his father, which he prepared in the place that David had appointed, in the threshing floor of Ornan the Jebusite.'),
  ('884976da-2ac8-5fc7-a382-a4b9bdb952de', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 2, 2, 'He began to build in the second [day] of the second month, in the fourth year of his reign.'),
  ('71cd4a46-def9-576a-a998-801eecda869e', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 3, 3, 'Now these are the foundations which Solomon laid for the building of the house of God. The length by cubits after the first measure was sixty cubits, and the breadth twenty cubits.'),
  ('c480bed6-4e61-5d38-aa4c-2cd9b373466c', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 4, 4, 'The porch that was before [the house], its length, according to the breadth of the house, was twenty cubits, and the height one hundred twenty; and he overlaid it within with pure gold.'),
  ('2a6da69d-8e3c-528c-a342-62d508f9d441', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 5, 5, 'The greater house he made a ceiling with fir wood, which he overlaid with fine gold, and ornamented it with palm trees and chains.'),
  ('b03502e3-5d58-58c0-a3d2-ccc3d9507789', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 6, 6, 'He garnished the house with precious stones for beauty: and the gold was gold of Parvaim.'),
  ('e9ab97c2-7029-50df-a295-e4e8ec2befcb', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 7, 7, 'He overlaid also the house, the beams, the thresholds, and its walls, and its doors, with gold; and engraved cherubim on the walls.'),
  ('8578b50e-2d37-5bde-a135-daeab0784aba', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 8, 8, 'He made the most holy house: its length, according to the breadth of the house, was twenty cubits, and its breadth twenty cubits; and he overlaid it with fine gold, amounting to six hundred talents.'),
  ('a646a17b-6e6c-5718-a994-db84c2d6e4cc', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 9, 9, 'The weight of the nails was fifty shekels of gold. He overlaid the upper rooms with gold.'),
  ('5f3ee361-9d94-556c-a254-a692a91e6ba6', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 10, 10, 'In the most holy house he made two cherubim of image work; and they overlaid them with gold.'),
  ('4a8cb9c2-3be4-51f7-a66a-362b59ec4165', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 11, 11, 'The wings of the cherubim were twenty cubits long: the wing of the one [cherub] was five cubits, reaching to the wall of the house; and the other wing was [likewise] five cubits, reaching to the wing of the other cherub.'),
  ('8f69bd05-fe08-5f0e-a44a-75d0845dbdfa', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 12, 12, 'The wing of the other cherub was five cubits, reaching to the wall of the house; and the other wing was five cubits [also], joining to the wing of the other cherub.'),
  ('5ca6e8c0-020c-5aac-a53b-2fa8370471ce', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 13, 13, 'The wings of these cherubim spread themselves forth twenty cubits: and they stood on their feet, and their faces were toward the house.'),
  ('558326df-e215-5502-a78d-1c93ebef1b65', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 14, 14, 'He made the veil of blue, and purple, and crimson, and fine linen, and ornamented it with cherubim.'),
  ('9bc3bd99-1ecc-5cac-a92b-55c0822b2334', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 15, 15, 'Also he made before the house two pillars of thirty-five cubits high, and the capital that was on the top of each of them was five cubits.'),
  ('f36cb8a9-705c-5f4d-ae6a-6b7c35bd0818', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 16, 16, 'He made chains in the oracle, and put [them] on the tops of the pillars; and he made one hundred pomegranates, and put them on the chains.'),
  ('d6d12b78-516e-5cd8-afa6-db22b57eb79c', 'cae107dd-884c-5a82-ab1c-6a385c6977ca', NULL, 17, 17, 'He set up the pillars before the temple, one on the right hand, and the other on the left; and called the name of that on the right hand Jachin, and the name of that on the left Boaz.'),
  ('e4a00d09-cf49-53ed-a291-ba19b0331fe6', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 1, 1, 'Then he made an altar of brass, twenty cubits its length, and twenty cubits its breadth, and ten cubits its height.'),
  ('cc12fb4c-3e65-561d-aed1-4529c2297eb0', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 2, 2, 'Also he made the molten sea of ten cubits from brim to brim, round in compass; and its height was five cubits; and a line of thirty cubits encircled it.'),
  ('ae776c0e-06ee-5bb9-a174-52ff86cb1067', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 3, 3, 'Under it was the likeness of oxen, which encircled it, for ten cubits, encircling the sea. The oxen were in two rows, cast when it was cast.'),
  ('4ed127b4-cd4b-5a23-a463-9c82f223f988', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 4, 4, 'It stood on twelve oxen, three looking toward the north, and three looking toward the west, and three looking toward the south, and three looking toward the east: and the sea was set on them above, and all their hinder parts were inward.'),
  ('de67398b-0ddd-5d25-a41a-f6fc0a6ce4b9', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 5, 5, 'It was a handbreadth thick; and its brim was worked like the brim of a cup, like the flower of a lily: it received and held three thousand baths.'),
  ('4c7b5e0b-6c82-58e4-abf4-14df30b496d5', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 6, 6, 'He made also ten basins, and put five on the right hand, and five on the left, to wash in them; such things as belonged to the burnt offering they washed in them; but the sea was for the priests to wash in.'),
  ('41d6d6a0-bc28-5cd5-a09a-e5d6e37b7228', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 7, 7, 'He made the ten lampstands of gold according to the ordinance concerning them; and he set them in the temple, five on the right hand, and five on the left.'),
  ('91655d1f-0dd1-5615-a3c3-e87f773d00b7', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 8, 8, 'He made also ten tables, and placed them in the temple, five on the right side, and five on the left. He made one hundred basins of gold.'),
  ('19d9dd08-7bf5-54cd-a260-fb3f37f66999', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 9, 9, 'Furthermore he made the court of the priests, and the great court, and doors for the court, and overlaid the doors of them with brass.'),
  ('e4b9f43f-5c24-5212-aae1-c631428ce6a9', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 10, 10, 'He set the sea on the right side [of the house] eastward, toward the south.'),
  ('f3ace3ef-9458-5169-ad64-67bbf5d746a2', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 11, 11, 'Huram made the pots, and the shovels, and the basins. So Huram made an end of doing the work that he did for king Solomon in the house of God:'),
  ('7962a512-93c9-5236-af93-f73061371248', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 12, 12, 'the two pillars, and the bowls, and the two capitals which were on the top of the pillars, and the two networks to cover the two bowls of the capitals that were on the top of the pillars,'),
  ('b941e5db-a9db-5969-a424-056ce5af4f68', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 13, 13, 'and the four hundred pomegranates for the two networks; two rows of pomegranates for each network, to cover the two bowls of the capitals that were on the pillars.'),
  ('b9506197-28b1-5860-a507-04b719f44aab', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 14, 14, 'He made also the bases, and the basins made he on the bases;'),
  ('af8e86d0-cb3a-56ca-aca6-8dff2feb60f8', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 15, 15, 'one sea, and the twelve oxen under it.'),
  ('9a4a7ba0-fa54-53a5-acd9-f869b750d9ff', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 16, 16, 'The pots also, and the shovels, and the forks, and all its vessels, did Huram his father make for king Solomon for the house of Yahweh of bright brass.'),
  ('e207dbb9-0379-50d1-a609-4e9d3f11765b', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 17, 17, 'In the plain of the Jordan did the king cast them, in the clay ground between Succoth and Zeredah.'),
  ('5d433457-646f-51b0-a060-51f013f78932', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 18, 18, 'Thus Solomon made all these vessels in great abundance: for the weight of the brass could not be found out.'),
  ('ac2a64d7-782a-579d-a820-572f0989b687', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 19, 19, 'Solomon made all the vessels that were in the house of God, the golden altar also, and the tables with the show bread on them;'),
  ('a9b6274b-3bb2-574e-a9b3-48f6d44a9844', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 20, 20, 'and the lampstands with their lamps, to burn according to the ordinance before the oracle, of pure gold;'),
  ('dbecc76e-6155-5679-ac0b-f88cffd8cd56', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 21, 21, 'and the flowers, and the lamps, and the tongs, of gold, and that perfect gold;'),
  ('0d2e86c4-a169-5944-a02a-9dc11d64645a', '313e61f0-ea4d-5f83-a6dc-4376bcbd77f4', NULL, 22, 22, 'and the snuffers, and the basins, and the spoons, and the fire pans, of pure gold: and as for the entry of the house, the inner doors of it for the most holy place, and the doors of the main hall of the temple were of gold.'),
  ('1a3aefed-bd02-55f1-a146-b02ba3b5f426', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 1, 1, 'Thus all the work that Solomon did for the house of Yahweh was finished. Solomon brought in the things that David his father had dedicated, even the silver, and the gold, and all the vessels, and put them in the treasuries of the house of God.'),
  ('60fc3eee-332d-5e6a-acc4-3b72013c5223', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 2, 2, 'Then Solomon assembled the elders of Israel, and all the heads of the tribes, the princes of the fathers'' [houses] of the children of Israel, to Jerusalem, to bring up the ark of the covenant of Yahweh out of the city of David, which is Zion.'),
  ('dbdcaf75-5c8c-5bff-af6c-87653d154a41', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 3, 3, 'And all the men of Israel assembled themselves to the king at the feast, which was [in] the seventh month.'),
  ('5209153f-9f55-58d1-a4e8-cef30ac0ca2b', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 4, 4, 'All the elders of Israel came: and the Levites took up the ark;'),
  ('f09df142-f021-5f11-a909-0aa10517d4f4', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 5, 5, 'and they brought up the ark, and the Tent of Meeting, and all the holy vessels that were in the Tent; these did the priests the Levites bring up.'),
  ('d1a336e9-3b46-5ee1-a52a-8d5a055feb8c', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 6, 6, 'King Solomon and all the congregation of Israel, that were assembled to him, were before the ark, sacrificing sheep and cattle, that could not be counted nor numbered for multitude.'),
  ('e476b922-6d21-5488-a315-98bbca2315fe', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 7, 7, 'The priests brought in the ark of the covenant of Yahweh to its place, into the oracle of the house, to the most holy place, even under the wings of the cherubim.'),
  ('a2e0aefa-9d0f-5e68-a37d-4311edac8858', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 8, 8, 'For the cherubim spread forth their wings over the place of the ark, and the cherubim covered the ark and its poles above.'),
  ('65e3f546-355f-5eca-a731-d06b125af923', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 9, 9, 'The poles were so long that the ends of the poles were seen from the ark before the oracle; but they were not seen outside: and there it is to this day.'),
  ('e2051506-dd5b-5365-a974-9f746bbfeb61', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 10, 10, 'There was nothing in the ark except the two tables which Moses put [there] at Horeb, when Yahweh made a covenant with the children of Israel, when they came out of Egypt.'),
  ('1ab5c1f7-eedc-52e7-ae9a-a872e52bacca', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 11, 11, 'It happened, when the priests were come out of the holy place, (for all the priests who were present had sanctified themselves, and did not keep their divisions;'),
  ('b3b85bdc-43d2-5c67-aed5-375acaf9031a', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 12, 12, 'also the Levites who were the singers, all of them, even Asaph, Heman, Jeduthun, and their sons and their brothers, arrayed in fine linen, with cymbals and stringed instruments and harps, stood at the east end of the altar, and with them one hundred twenty priests sounding with trumpets;)'),
  ('bdd7ce7e-33e2-5c16-a7db-c0280b85261e', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 13, 13, 'it happened, when the trumpeters and singers were as one, to make one sound to be heard in praising and thanking Yahweh; and when they lifted up their voice with the trumpets and cymbals and instruments of music, and praised Yahweh, [saying], "For he is good; for his loving kindness endures forever!" that then the house was filled with a cloud, even the house of Yahweh,'),
  ('ddf44356-6a18-5353-a0d2-b5edcc98d444', '01412c38-0eb8-5a39-ae9a-431ffe8e296c', NULL, 14, 14, 'so that the priests could not stand to minister by reason of the cloud: for the glory of Yahweh filled the house of God.'),
  ('e66e26e0-43c8-5f77-a2b4-f30170e7169b', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 1, 1, 'Then Solomon said, "Yahweh has said that he would dwell in the thick darkness.'),
  ('943fae76-835d-5649-ae85-3c237d6f52b9', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 2, 2, 'But I have built you a house of habitation, and a place for you to dwell in forever."'),
  ('893743a1-a648-5b85-a0d1-82ef86844778', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 3, 3, 'The king turned his face, and blessed all the assembly of Israel: and all the assembly of Israel stood.'),
  ('39122589-fa15-56be-a650-921e3ba9832a', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 4, 4, 'He said, "Blessed be Yahweh, the God of Israel, who spoke with his mouth to David my father, and has with his hands fulfilled it, saying,'),
  ('41172ec3-c316-55c7-a690-45102cff93c7', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 5, 5, '''Since the day that I brought forth my people out of the land of Egypt, I chose no city out of all the tribes of Israel to build a house in, that my name might be there; neither chose I any man to be prince over my people Israel:'),
  ('a78e06cc-34d3-5545-aec6-3098336bde39', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 6, 6, 'but I have chosen Jerusalem, that my name might be there; and have chosen David to be over my people Israel.'''),
  ('93c271bd-1a33-5ec0-a541-0d50cc20bb6a', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 7, 7, 'Now it was in the heart of David my father to build a house for the name of Yahweh, the God of Israel.'),
  ('6a052577-5b5f-55e4-a98e-2eb0821910c2', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 8, 8, 'But Yahweh said to David my father, ''Whereas it was in your heart to build a house for my name, you did well that it was in your heart:'),
  ('a53ef5e8-1f4d-5b32-ad0f-b755e7229c73', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 9, 9, 'nevertheless you shall not build the house; but your son who shall come forth out of your body, he shall build the house for my name.'''),
  ('fcc0450c-57d5-52a7-af81-b060d12553bb', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 10, 10, '"Yahweh has performed his word that he spoke; for I have risen up in the place of David my father, and sit on the throne of Israel, as Yahweh promised, and have built the house for the name of Yahweh, the God of Israel.'),
  ('f2bb6f9e-44fc-50eb-ae1f-b9108a7d3d4e', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 11, 11, 'There I have set the ark, in which is the covenant of Yahweh, which he made with the children of Israel."'),
  ('a68bc87e-3633-5e65-a64b-b9c19fb656f1', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 12, 12, 'He stood before the altar of Yahweh in the presence of all the assembly of Israel, and spread forth his hands'),
  ('e2b48a97-47bd-57b9-af85-c21ff55c04d8', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 13, 13, '(for Solomon had made a bronze scaffold, five cubits long, and five cubits broad, and three cubits high, and had set it in the midst of the court; and on it he stood, and kneeled down on his knees before all the assembly of Israel, and spread forth his hands toward heaven;)'),
  ('f5fa7cc8-df67-5782-a4a9-47e7debfce6a', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 14, 14, 'and he said, "Yahweh, the God of Israel, there is no God like you, in heaven, or on earth; you who keep covenant and loving kindness with your servants, who walk before you with all their heart;'),
  ('051b7a4a-3a28-5af8-a3f7-2c2fdd0d5342', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 15, 15, 'who have kept with your servant David my father that which you promised him: yes, you spoke with your mouth, and have fulfilled it with your hand, as it is this day.'),
  ('191b0933-1704-5cc7-a291-3596308c8f10', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 16, 16, '"Now therefore, Yahweh, the God of Israel, keep with your servant David my father that which you have promised him, saying, ''There shall not fail you a man in my sight to sit on the throne of Israel, if only your children take heed to their way, to walk in my law as you have walked before me.'''),
  ('5436dbff-d3d3-55e9-a77c-f6fbdbb22eb1', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 17, 17, 'Now therefore, Yahweh, the God of Israel, let your word be verified, which you spoke to your servant David.'),
  ('f0ff6266-b168-5c6b-a7f4-faca29643fef', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 18, 18, '"But will God indeed dwell with men on the earth? Behold, heaven and the heaven of heavens can''t contain you; how much less this house which I have built!'),
  ('d1a7a4cb-5a89-540d-aedf-a2dd36ba9bf0', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 19, 19, 'Yet have respect for the prayer of your servant, and to his supplication, Yahweh my God, to listen to the cry and to the prayer which your servant prays before you;'),
  ('6ddd01c2-0cb3-50e6-a31a-dfa6af1b9177', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 20, 20, 'that your eyes may be open toward this house day and night, even toward the place where you have said that you would put your name; to listen to the prayer which your servant shall pray toward this place.'),
  ('6b3ae3f6-68eb-5d95-a041-8f97eaad308c', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 21, 21, 'Listen to the petitions of your servant, and of your people Israel, when they shall pray toward this place: yes, hear from your dwelling place, even from heaven; and when you hear, forgive.'),
  ('6e6cbdca-4136-5d8c-ad0a-8dd8ac22e549', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 22, 22, '"If a man sin against his neighbor, and an oath is laid on him to cause him to swear, and he comes and swears before your altar in this house;'),
  ('b04894e8-c0ae-52a1-aa42-1cf00c1fd0e7', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 23, 23, 'then hear from heaven, and do, and judge your servants, bringing retribution to the wicked, to bring his way on his own head; and justifying the righteous, to give him according to his righteousness.'),
  ('d627c11a-d284-5213-a587-a8e36b30c9d2', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 24, 24, '"If your people Israel be struck down before the enemy, because they have sinned against you, and shall turn again and confess your name, and pray and make supplication before you in this house;'),
  ('f808d1a0-125a-562e-a37a-7fc9a65e49a1', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 25, 25, 'then hear from heaven, and forgive the sin of your people Israel, and bring them again to the land which you gave to them and to their fathers.'),
  ('5df51c62-ca3c-551f-a839-198611ea4d3a', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 26, 26, '"When the sky is shut up, and there is no rain, because they have sinned against you; if they pray toward this place, and confess your name, and turn from their sin, when you afflict them:'),
  ('0fefe660-a880-52f2-abb1-3a462cb97e71', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 27, 27, 'then hear in heaven, and forgive the sin of your servants, and of your people Israel, when you teach them the good way in which they should walk; and send rain on your land, which you have given to your people for an inheritance.'),
  ('64755972-a40c-571d-a03f-8139edb7b2c2', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 28, 28, '"If there is famine in the land, if there is pestilence, if there is blight or mildew, locust or caterpillar; if their enemies besiege them in the land of their cities; whatever plague or whatever sickness there is;'),
  ('57fd499c-a837-584c-a0a3-96a8976704ae', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 29, 29, 'whatever prayer and supplication be made by any man, or by all your people Israel, who shall know every man his own plague and his own sorrow, and shall spread forth his hands toward this house:'),
  ('d4e1f102-ebfe-5aae-a60c-7685df0a459b', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 30, 30, 'then hear from heaven, your dwelling place and forgive, and render to every man according to all his ways, whose heart you know; (for you, even you only, know the hearts of the children of men;)'),
  ('9e8168a8-d00f-59ed-a33e-81a6469213c3', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 31, 31, 'that they may fear you, to walk in your ways, so long as they live in the land which you gave to our fathers.'),
  ('c2991b74-d8a0-57c6-ad2d-45ef5b5ce1ac', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 32, 32, '"Moreover concerning the foreigner, who is not of your people Israel, when he shall come from a far country for your great name''s sake, and your mighty hand, and your outstretched arm; when they shall come and pray toward this house:'),
  ('247f7809-fad3-5d80-a624-93473f4f4355', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 33, 33, 'then hear from heaven, even from your dwelling place, and do according to all that the foreigner calls to you for; that all the peoples of the earth may know your name, and fear you, as does your people Israel, and that they may know that this house which I have built is called by your name.'),
  ('e7721ae3-13ac-53b7-a266-ff43993baafc', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 34, 34, '"If your people go out to battle against their enemies, by whatever way you shall send them, and they pray to you toward this city which you have chosen, and the house which I have built for your name;'),
  ('59f286aa-82b1-5d89-add4-74cf84a5090b', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 35, 35, 'then hear from heaven their prayer and their supplication, and maintain their cause.'),
  ('e8ceb014-6202-5335-ab96-3d9ff3304e4d', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 36, 36, '"If they sin against you (for there is no man who doesn''t sin), and you are angry with them, and deliver them to the enemy, so that they carry them away captive to a land far off or near;'),
  ('103e215e-bf66-507d-a2ce-464b7ac85cdc', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 37, 37, 'yet if they shall repent themselves in the land where they are carried captive, and turn again, and make supplication to you in the land of their captivity, saying, ''We have sinned, we have done perversely, and have dealt wickedly;'''),
  ('4117d7b2-42aa-5463-a18e-a94b72002180', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 38, 38, 'if they return to you with all their heart and with all their soul in the land of their captivity, where they have carried them captive, and pray toward their land, which you gave to their fathers, and the city which you have chosen, and toward the house which I have built for your name:'),
  ('7bccd7c1-99cf-5efe-abb1-5845b3ce6ef4', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 39, 39, 'then hear from heaven, even from your dwelling place, their prayer and their petitions, and maintain their cause, and forgive your people who have sinned against you.'),
  ('da999072-5c16-557f-af09-0907e3be64ab', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 40, 40, '"Now, my God, let, I beg you, your eyes be open, and let your ears be attentive, to the prayer that is made in this place.'),
  ('27929a9e-3eff-5f26-afa2-b73e6abbe1c9', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 41, 41, '"Now therefore arise, Yahweh God, into your resting place, you, and the ark of your strength: let your priests, Yahweh God, be clothed with salvation, and let your saints rejoice in goodness.'),
  ('3a9da7ef-6620-5ee5-ab6f-7fd3e4a4a4a3', 'cfd3f060-0c11-5223-a638-f8dab6eef6fe', NULL, 42, 42, '"Yahweh God, don''t turn away the face of your anointed: remember [your] loving kindnesses to David your servant."'),
  ('086ea4bc-aeff-5044-a713-ea78c68c8e19', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 1, 1, 'Now when Solomon had made an end of praying, the fire came down from heaven, and consumed the burnt offering and the sacrifices; and the glory of Yahweh filled the house.'),
  ('5550a158-ab99-5d6d-a969-0aaed6e940f6', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 2, 2, 'The priests could not enter into the house of Yahweh, because the glory of Yahweh filled Yahweh''s house.'),
  ('9567b73b-688b-50be-ab1a-88ba412b6e62', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 3, 3, 'All the children of Israel looked on, when the fire came down, and the glory of Yahweh was on the house; and they bowed themselves with their faces to the ground on the pavement, and worshiped, and gave thanks to Yahweh, [saying], "For he is good; for his loving kindness endures for ever."'),
  ('32b0ed68-1cbe-529c-a7cb-67fc465a48bf', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 4, 4, 'Then the king and all the people offered sacrifice before Yahweh.'),
  ('cc37c364-53d8-5f0e-aa91-7e8ea5d5dcff', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 5, 5, 'King Solomon offered a sacrifice of twenty-two thousand head of cattle, and a hundred and twenty thousand sheep. So the king and all the people dedicated the house of God.'),
  ('fd56f214-70b6-5601-a7eb-b622011faca1', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 6, 6, 'The priests stood, according to their positions; the Levites also with instruments of music of Yahweh, which David the king had made to give thanks to Yahweh, when David praised by their ministry, saying "For his loving kindness endures for ever." The priests sounded trumpets before them; and all Israel stood.'),
  ('d0f1dfd5-15e6-5574-a3a2-3106b4ca1db5', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 7, 7, 'Moreover Solomon made the middle of the court holy that was before the house of Yahweh; for there he offered the burnt offerings, and the fat of the peace offerings, because the bronze altar which Solomon had made was not able to receive the burnt offering, and the meal offering, and the fat.'),
  ('25792eb9-f617-56e9-af7a-5d4718e6b92c', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 8, 8, 'So Solomon held the feast at that time seven days, and all Israel with him, a very great assembly, from the entrance of Hamath to the brook of Egypt.'),
  ('48e7c057-5541-5b30-aa8e-61e9d81767fb', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 9, 9, 'On the eighth day they held a solemn assembly: for they kept the dedication of the altar seven days, and the feast seven days.'),
  ('624b20c2-1b57-572f-a330-9b95e9e729a2', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 10, 10, 'On the three and twentieth day of the seventh month he sent the people away to their tents, joyful and glad of heart for the goodness that Yahweh had shown to David, and to Solomon, and to Israel his people.'),
  ('c41522b8-244b-5c69-aa68-f5db421cf857', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 11, 11, 'Thus Solomon finished the house of Yahweh, and the king''s house: and he successfully completed all that came into Solomon''s heart to make in the house of Yahweh, and in his own house.'),
  ('3e956e8c-63d9-5c15-a668-6de7be36467a', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 12, 12, 'Yahweh appeared to Solomon by night, and said to him, "I have heard your prayer, and have chosen this place to myself for a house of sacrifice.'),
  ('6985d472-ef2a-5753-a663-4281d9476e5d', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 13, 13, '"If I shut up the sky so that there is no rain, or if I command the locust to devour the land, or if I send pestilence among my people;'),
  ('258b9709-bc58-5761-a028-bb9aa9e904da', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 14, 14, 'if my people, who are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.'),
  ('8b616a52-e2bd-5be1-a0e0-c9a44889d230', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 15, 15, 'Now my eyes shall be open, and my ears attentive, to the prayer that is made in this place.'),
  ('83510ce7-6082-584c-a555-566166943336', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 16, 16, 'For now have I chosen and made this house holy, that my name may be there forever; and my eyes and my heart shall be there perpetually.'),
  ('905c4a84-1da1-5ba8-a2c2-ca239f788ff8', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 17, 17, '"As for you, if you will walk before me as David your father walked, and do according to all that I have commanded you, and will keep my statutes and my ordinances;'),
  ('57accfff-7128-5368-a443-930ad02716b6', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 18, 18, 'then I will establish the throne of your kingdom, according as I covenanted with David your father, saying, ''There shall not fail you a man to be ruler in Israel.'''),
  ('70772c12-34b5-5826-a14d-7e8d05f6fe90', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 19, 19, 'But if you turn away, and forsake my statutes and my commandments which I have set before you, and shall go and serve other gods, and worship them;'),
  ('a02cad50-8674-51bf-a917-16e0195dd4a1', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 20, 20, 'then I will pluck them up by the roots out of my land which I have given them; and this house, which I have made holy for my name, I will cast out of my sight, and I will make it a proverb and a byword among all peoples.'),
  ('2c3f5c0b-b417-5a14-a509-5ec8cd42d634', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 21, 21, 'This house, which is so high, everyone who passes by it shall be astonished, and shall say, ''Why has Yahweh done thus to this land, and to this house?'''),
  ('59eae8d1-8bd2-5878-a044-5166455cd766', 'cf636027-e3b6-5aae-afc5-56585026f885', NULL, 22, 22, 'They shall answer, ''Because they abandoned Yahweh, the God of their fathers, who brought them forth out of the land of Egypt, and took other gods, worshiped them, and served them. Therefore he has brought all this evil on them.''"'),
  ('462d801c-5fad-5d2a-adb3-71d0e39cb006', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 1, 1, 'It happened at the end of twenty years, in which Solomon had built the house of Yahweh, and his own house,'),
  ('5da365d6-b123-535d-a119-6634300bad4f', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 2, 2, 'that the cities which Huram had given to Solomon, Solomon built them, and caused the children of Israel to dwell there.'),
  ('d467d0f6-f639-5503-a76c-4dc2a060989b', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 3, 3, 'Solomon went to Hamath Zobah, and prevailed against it.'),
  ('0799ebeb-7d98-5fac-ad3b-9855fd501e6d', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 4, 4, 'He built Tadmor in the wilderness, and all the storage cities, which he built in Hamath.'),
  ('c85b065a-fa99-59d6-a3e6-3db62b2aaae1', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 5, 5, 'Also he built Beth Horon the upper, and Beth Horon the lower, fortified cities, with walls, gates, and bars;'),
  ('91819c61-472a-5dc1-a093-99ead72ae5c7', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 6, 6, 'and Baalath, and all the storage cities that Solomon had, and all the cities for his chariots, and the cities for his horsemen, and all that Solomon desired to build for his pleasure in Jerusalem, and in Lebanon, and in all the land of his dominion.'),
  ('7a551fd2-6d98-50df-a038-d9adfa6fda01', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 7, 7, 'As for all the people who were left of the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, who were not of Israel;'),
  ('ef27b725-6e79-5b3a-af5a-7843eb40bf78', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 8, 8, 'of their children who were left after them in the land, whom the children of Israel didn''t consume, of them Solomon conscripted forced labor to this day.'),
  ('0fe8bc0c-905e-59f2-abe1-cdb92a0cf52c', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 9, 9, 'But of the children of Israel did Solomon make no servants for his work; but they were men of war, and chief of his captains, and rulers of his chariots and of his horsemen.'),
  ('f2ae359a-bbbb-55a6-ae06-700dcaf13cc7', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 10, 10, 'These were the chief officers of king Solomon, even two-hundred fifty, who ruled over the people.'),
  ('38d38a16-16a3-5545-a0e5-702e1ab24e2e', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 11, 11, 'Solomon brought up the daughter of Pharaoh out of the city of David to the house that he had built for her; for he said, "My wife shall not dwell in the house of David king of Israel, because the places where the ark of Yahweh has come are holy."'),
  ('629c8f43-8071-5e1c-a3dd-ee4584732e6e', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 12, 12, 'Then Solomon offered burnt offerings to Yahweh on the altar of Yahweh, which he had built before the porch,'),
  ('b7cbd056-0213-5517-a4b8-648dc2d795ab', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 13, 13, 'even as the duty of every day required, offering according to the commandment of Moses, on the Sabbaths, and on the new moons, and on the set feasts, three times in the year, [even] in the feast of unleavened bread, and in the feast of weeks, and in the feast of tents.'),
  ('b696a65f-e439-50c4-ad60-34a2956eeff1', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 14, 14, 'He appointed, according to the ordinance of David his father, the divisions of the priests to their service, and the Levites to their offices, to praise, and to minister before the priests, as the duty of every day required; the doorkeepers also by their divisions at every gate: for so had David the man of God commanded.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8e8f92fc-527b-5f3d-a416-69b04b38dffa', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 15, 15, 'They didn''t depart from the commandment of the king to the priests and Levites concerning any matter, or concerning the treasures.'),
  ('8b6fa781-fa9a-5fd5-a40b-c12f8f8a84a2', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 16, 16, 'Now all the work of Solomon was prepared to the day of the foundation of the house of Yahweh, and until it was finished. [So] the house of Yahweh was completed.'),
  ('9c6b7abc-6294-57c3-ae50-7b3aebb776d2', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 17, 17, 'Then went Solomon to Ezion Geber, and to Eloth, on the seashore in the land of Edom.'),
  ('0d3f0278-9542-541b-a13a-76ccd2d0530e', 'c47b1adf-0774-5975-abcc-386150dbdc1c', NULL, 18, 18, 'Huram sent him ships and servants who had knowledge of the sea by the hands of his servants; and they came with the servants of Solomon to Ophir, and fetched from there four hundred fifty talents of gold, and brought them to king Solomon.'),
  ('6c43f0a9-b0c7-5483-a889-a04a06c88ed6', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 1, 1, 'When the queen of Sheba heard of the fame of Solomon, she came to prove Solomon with hard questions at Jerusalem, with a very great train, and camels that bore spices, and gold in abundance, and precious stones: and when she was come to Solomon, she talked with him of all that was in her heart.'),
  ('42a36bcf-b395-58db-a83c-b3bda0a1ced2', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 2, 2, 'Solomon told her all her questions; and there was not anything hidden from Solomon which he didn''t tell her.'),
  ('720aacaf-62bc-5fc9-a192-de60cdcadf06', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 3, 3, 'When the queen of Sheba had seen the wisdom of Solomon, and the house that he had built,'),
  ('f9a18a85-53da-5d35-a9b7-9b076749e2ff', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 4, 4, 'and the food of his table, and the sitting of his servants, and the attendance of his ministers, and their clothing, his cup bearers also, and their clothing, and his ascent by which he went up to the house of Yahweh; there was no more spirit in her.'),
  ('f5d6cc38-a902-5fc8-a6d4-fa738109aaa9', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 5, 5, 'She said to the king, "It was a true report that I heard in my own land of your acts, and of your wisdom.'),
  ('bd873a31-e848-5cdd-ab04-a0893948ba44', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 6, 6, 'However I didn''t believe their words, until I came, and my eyes had seen it; and behold, the half of the greatness of your wisdom was not told me: you exceed the fame that I heard.'),
  ('64da3e4b-483f-5d7f-af4a-e671557f5e8c', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 7, 7, 'Happy are your men, and happy are these your servants, who stand continually before you, and hear your wisdom.'),
  ('653ad2d4-5af5-5704-af44-87bc39bb0a17', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 8, 8, 'Blessed be Yahweh your God, who delighted in you, to set you on his throne, to be king for Yahweh your God: because your God loved Israel, to establish them forever, therefore made he you king over them, to do justice and righteousness."'),
  ('35d2dca3-d92c-587b-ab40-e14fecd6a4ec', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 9, 9, 'She gave the king one hundred and twenty talents of gold, and spices in great abundance, and precious stones: neither was there any such spice as the queen of Sheba gave to king Solomon.'),
  ('49ab00fd-0bce-5d39-a5a5-4e2f0995c924', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 10, 10, 'The servants also of Huram, and the servants of Solomon, who brought gold from Ophir, brought algum trees and precious stones.'),
  ('52bbc90e-5e92-5121-a6eb-4eb034a86259', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 11, 11, 'The king made of the algum trees terraces for the house of Yahweh, and for the king''s house, and harps and stringed instruments for the singers: and there were none like these seen before in the land of Judah.'),
  ('badbd8fd-3310-5afd-ac3d-6cd43e4e3786', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 12, 12, 'King Solomon gave to the queen of Sheba all her desire, whatever she asked, besides that which she had brought to the king. So she turned, and went to her own land, she and her servants.'),
  ('0a8a1296-bf91-5212-aaf3-2de1cfde4283', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 13, 13, 'Now the weight of gold that came to Solomon in one year was six hundred and sixty-six talents of gold,'),
  ('740cae6c-321a-52ad-a564-086098931160', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 14, 14, 'besides that which the traders and merchants brought: and all the kings of Arabia and the governors of the country brought gold and silver to Solomon.'),
  ('436841db-2d44-5088-acea-822c91d4c524', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 15, 15, 'King Solomon made two hundred bucklers of beaten gold; six hundred [shekels] of beaten gold went to one buckler.'),
  ('7a39d1ca-cc23-5ab5-a30d-8ac3e854362a', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 16, 16, '[he made] three hundred shields of beaten gold; three hundred [shekels] of gold went to one shield: and the king put them in the house of the forest of Lebanon.'),
  ('ec7eebb1-3085-55da-a303-0314d69e033b', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 17, 17, 'Moreover the king made a great throne of ivory, and overlaid it with pure gold.'),
  ('b35d8100-b99d-518f-ab39-bbe662cfba08', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 18, 18, 'And there were six steps to the throne, with a footstool of gold, which were fastened to the throne, and stays on either side by the place of the seat, and two lions standing beside the stays.'),
  ('6b224c82-1a33-5138-a353-d467947fdd74', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 19, 19, 'Twelve lions stood there on the one side and on the other on the six steps: there was nothing like it made in any kingdom.'),
  ('138aa356-9b0e-51b4-a5a9-d12b4f84228a', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 20, 20, 'All king Solomon''s drinking vessels were of gold, and all the vessels of the house of the forest of Lebanon were of pure gold: silver was nothing accounted of in the days of Solomon.'),
  ('37d64a65-c102-5733-a275-afe9b4525607', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 21, 21, 'For the king had ships that went to Tarshish with the servants of Huram; once every three years came the ships of Tarshish, bringing gold, and silver, ivory, and apes, and peacocks.'),
  ('f3434ca0-53e5-5334-aff7-32c4c84c61e7', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 22, 22, 'So king Solomon exceeded all the kings of the earth in riches and wisdom.'),
  ('ba3c7b1e-914a-5468-aa67-dc43e9e534c5', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 23, 23, 'All the kings of the earth sought the presence of Solomon, to hear his wisdom, which God had put in his heart.'),
  ('6a797351-ef9c-59e8-ab45-c85ef6a49479', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 24, 24, 'They brought every man his tribute, vessels of silver, and vessels of gold, and clothing, armor, and spices, horses, and mules, a rate year by year.'),
  ('84230039-990f-5700-ac2a-e4a85df5120a', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 25, 25, 'Solomon had four thousand stalls for horses and chariots, and twelve thousand horsemen, that he stationed in the chariot cities, and with the king at Jerusalem.'),
  ('fb73b4d2-0856-523f-a0ee-db10f17142c4', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 26, 26, 'He ruled over all the kings from the River even to the land of the Philistines, and to the border of Egypt.'),
  ('2f1e1a58-da0b-5e9c-ac5c-9d533f510358', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 27, 27, 'The king made silver to be in Jerusalem as stones, and he made cedars to be as the sycamore trees that are in the lowland, for abundance.'),
  ('cd93fa60-50ce-5534-acb7-76983999dce4', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 28, 28, 'They brought horses for Solomon out of Egypt, and out of all lands.'),
  ('86ac8d3f-c9b0-521e-ab64-a5f0cca4f401', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 29, 29, 'Now the rest of the acts of Solomon, first and last, aren''t they written in the history of Nathan the prophet, and in the prophecy of Ahijah the Shilonite, and in the visions of Iddo the seer concerning Jeroboam the son of Nebat?'),
  ('3574d98d-a749-5515-ad0c-f70dea69fcff', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 30, 30, 'Solomon reigned in Jerusalem over all Israel forty years.'),
  ('204c430a-b16f-5d1e-a766-de1521e86222', 'fa16a2b2-5a4f-5d84-ad93-6bf78772de21', NULL, 31, 31, 'Solomon slept with his fathers, and he was buried in the city of David his father: and Rehoboam his son reigned in his place.'),
  ('1557ccc7-2ed5-57fc-ab4f-8ae1c6d1e03e', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 1, 1, 'Rehoboam went to Shechem; for all Israel were come to Shechem to make him king.'),
  ('92e954d5-17d4-56c8-adc8-2e91cd6ed84b', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 2, 2, 'It happened, when Jeroboam the son of Nebat heard of it, (for he was in Egypt, where he had fled from the presence of king Solomon), that Jeroboam returned out of Egypt.'),
  ('c031f4f7-b040-521e-a865-600a945ccad8', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 3, 3, 'They sent and called him; and Jeroboam and all Israel came, and they spoke to Rehoboam, saying,'),
  ('2e8a74ed-e571-5f1c-a433-9691e3f09229', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 4, 4, '"Your father made our yoke grievous: now therefore make you the grievous service of your father, and his heavy yoke which he put on us, lighter, and we will serve you."'),
  ('95f948b5-22f7-5319-af45-b5589d63634c', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 5, 5, 'He said to them, "Come again to me after three days." The people departed.'),
  ('8f54b61f-7915-5713-afba-af1cdc11192c', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 6, 6, 'King Rehoboam took counsel with the old men, who had stood before Solomon his father while he yet lived, saying, "What counsel do you give me to return answer to this people?"'),
  ('11e2a598-ef71-56f1-afee-334193cfc336', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 7, 7, 'They spoke to him, saying, "If you are kind to this people, and please them, and speak good words to them, then they will be your servants forever."'),
  ('d7a59020-e95d-523f-a072-59bde3b1b5a1', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 8, 8, 'But he forsook the counsel of the old men which they had given him, and took counsel with the young men who had grown up with him, who stood before him.'),
  ('4ea8f3c6-fab5-53ee-a906-2299478390ba', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 9, 9, 'He said to them, "What counsel do you give, that we may return answer to this people, who have spoken to me, saying, ''Make the yoke that your father did put on us lighter?''"'),
  ('a05bd386-4889-5586-a9a9-b512a54e6f6d', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 10, 10, 'The young men who had grown up with him spoke to him, saying, "Thus you shall tell the people who spoke to you, saying, ''Your father made our yoke heavy, but make it lighter on us;'' thus you shall say to them, ''My little finger is thicker than my father''s waist.'),
  ('9f9715fa-3a01-53fb-aefb-50d5e87b8719', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 11, 11, 'Now whereas my father burdened you with a heavy yoke, I will add to your yoke. My father chastised you with whips, but I [will chastise you] with scorpions.''"'),
  ('8a0b5410-f96d-515a-aabd-c556bb780788', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 12, 12, 'So Jeroboam and all the people came to Rehoboam the third day, as the king asked, saying, "Come to me again the third day."'),
  ('d7466503-0dd5-5bf0-a154-2e37d50caf20', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 13, 13, 'The king answered them roughly; and king Rehoboam forsook the counsel of the old men,'),
  ('b1ca5654-6f7e-5749-ae03-9d8762f5b2fc', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 14, 14, 'and spoke to them after the counsel of the young men, saying, "My father made your yoke heavy, but I will add to it. My father chastised you with whips, but I will chastise you with scorpions."'),
  ('10d2a74f-577c-5fcb-a2e6-4457b5d76d7b', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 15, 15, 'So the king didn''t listen to the people; for it was brought about of God, that Yahweh might establish his word, which he spoke by Ahijah the Shilonite to Jeroboam the son of Nebat.'),
  ('1df81852-7cab-51c9-abe1-3babae481b90', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 16, 16, 'When all Israel saw that the king didn''t listen to them, the people answered the king, saying, "What portion have we in David? Neither have we inheritance in the son of Jesse! Every man to your tents, Israel! Now see to your own house, David." So all Israel departed to their tents.'),
  ('8644e51e-5b4a-50b4-a685-c182fa6ddb98', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 17, 17, 'But as for the children of Israel who lived in the cities of Judah, Rehoboam reigned over them.'),
  ('a193a06e-aacf-5a57-a4f7-b643ea4049ff', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 18, 18, 'Then king Rehoboam sent Hadoram, who was over the men subject to forced labor; and the children of Israel stoned him to death with stones. King Rehoboam made speed to get himself up to his chariot, to flee to Jerusalem.'),
  ('33755165-1301-57ee-a637-747e47a2a948', 'c61e85f3-1a8c-56ae-a645-9f310e36ba3b', NULL, 19, 19, 'So Israel rebelled against the house of David to this day.'),
  ('0dfbdd4c-410c-5f39-af98-875db56de1b2', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 1, 1, 'When Rehoboam was come to Jerusalem, he assembled the house of Judah and Benjamin, one hundred eighty thousand chosen men, who were warriors, to fight against Israel, to bring the kingdom again to Rehoboam.'),
  ('d02f802b-0394-51a2-a184-e780133900da', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 2, 2, 'But the word of Yahweh came to Shemaiah the man of God, saying,'),
  ('f693e7ba-05c1-596a-a02b-0c1a539fe42a', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 3, 3, '"Speak to Rehoboam the son of Solomon, king of Judah, and to all Israel in Judah and Benjamin, saying,'),
  ('2687d51c-c105-5f59-ac4e-a1ffa99cd53d', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 4, 4, '''Thus says Yahweh, "You shall not go up, nor fight against your brothers! Return every man to his house; for this thing is of me."''" So they listened to the words of Yahweh, and returned from going against Jeroboam.'),
  ('06c29074-c335-51cf-a0a1-616ddc13f1f5', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 5, 5, 'Rehoboam lived in Jerusalem, and built cities for defense in Judah.'),
  ('673e3f04-97de-59fb-a5a7-5e6d031ca7bb', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 6, 6, 'He built Bethlehem, and Etam, and Tekoa,'),
  ('3e112a91-f7c0-5901-a3e7-6ad24cd2ac7d', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 7, 7, 'Beth Zur, and Soco, and Adullam,'),
  ('0948b063-cfd1-5001-a41c-e5b045ab373e', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 8, 8, 'and Gath, and Mareshah, and Ziph,'),
  ('fc78e370-9b55-581e-a478-91517d5ccb86', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 9, 9, 'and Adoraim, and Lachish, and Azekah,'),
  ('f79ecf35-84fb-55b1-a60a-ba651c928e4f', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 10, 10, 'and Zorah, and Aijalon, and Hebron, which are in Judah and in Benjamin, fortified cities.'),
  ('99701616-5499-5a62-acd6-17ca060a2e91', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 11, 11, 'He fortified the strongholds, and put captains in them, and stores of food, and oil and wine.'),
  ('3785acd7-5af0-57ea-a3f1-10b3e53cf582', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 12, 12, 'In every city [he put] shields and spears, and made them exceeding strong. Judah and Benjamin belonged to him.'),
  ('0bc38e74-0a8b-5466-a21e-9463f71e825d', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 13, 13, 'The priests and the Levites who were in all Israel resorted to him out of all their border.'),
  ('eea5d3c2-4053-52bc-aaed-6870a3428576', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 14, 14, 'For the Levites left their suburbs and their possession, and came to Judah and Jerusalem: for Jeroboam and his sons cast them off, that they should not execute the priest''s office to Yahweh;'),
  ('c10ff260-1aa7-51d8-a03d-56b27733e561', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 15, 15, 'and he appointed him priests for the high places, and for the male goats, and for the calves which he had made.'),
  ('e14531ab-df49-5647-a761-5104172d1999', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 16, 16, 'After them, out of all the tribes of Israel, such as set their hearts to seek Yahweh, the God of Israel, came to Jerusalem to sacrifice to Yahweh, the God of their fathers.'),
  ('8be581e8-20a5-5fe9-a950-786c174e5d73', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 17, 17, 'So they strengthened the kingdom of Judah, and made Rehoboam the son of Solomon strong, three years; for they walked three years in the way of David and Solomon.'),
  ('f66a8831-b92b-53ab-affb-f07518327515', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 18, 18, 'Rehoboam took him a wife, Mahalath the daughter of Jerimoth the son of David, [and of] Abihail the daughter of Eliab the son of Jesse;'),
  ('a10ee593-9f5a-5ee7-a448-98d11fac3c5a', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 19, 19, 'and she bore him sons: Jeush, and Shemariah, and Zaham.'),
  ('6e16fd9b-cad5-5d2c-accc-14f3e967421c', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 20, 20, 'After her he took Maacah the daughter of Absalom; and she bore him Abijah, and Attai, and Ziza, and Shelomith.'),
  ('8a967fd7-1091-53e8-a1d4-f14be66b0edb', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 21, 21, 'Rehoboam loved Maacah the daughter of Absalom above all his wives and his concubines: (for he took eighteen wives, and sixty concubines, and became the father of twenty-eight sons and sixty daughters.)'),
  ('a79abcba-644d-5462-ad3c-b4349b1771bf', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 22, 22, 'Rehoboam appointed Abijah the son of Maacah to be chief, [even] the prince among his brothers; for [he was minded] to make him king.'),
  ('becb01e7-1cac-5671-a286-1f51a3c11296', 'f7c32b8c-ab59-5e01-a306-e1b410518406', NULL, 23, 23, 'He dealt wisely, and dispersed of all his sons throughout all the lands of Judah and Benjamin, to every fortified city: and he gave them food in abundance. He sought [for them] many wives.'),
  ('e15c2478-e04a-5c47-a652-f93f0e474a25', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 1, 1, 'It happened, when the kingdom of Rehoboam was established, and he was strong, that he forsook the law of Yahweh, and all Israel with him.'),
  ('c1fa5bb3-a70a-511a-a3c1-e680c33b41ec', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 2, 2, 'It happened in the fifth year of king Rehoboam, that Shishak king of Egypt came up against Jerusalem, because they had trespassed against Yahweh,'),
  ('3cd8099c-bc93-5ac0-a83a-4b27a2a13c6e', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 3, 3, 'with twelve hundred chariots, and sixty thousand horsemen. The people were without number who came with him out of Egypt: the Lubim, the Sukkiim, and the Ethiopians.'),
  ('b043f8ec-c2e3-5493-af14-9b5718f22819', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 4, 4, 'He took the fortified cities which pertained to Judah, and came to Jerusalem.'),
  ('59786b53-ecd5-5b8b-af35-ec7f390876b6', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 5, 5, 'Now Shemaiah the prophet came to Rehoboam, and to the princes of Judah, who were gathered together to Jerusalem because of Shishak, and said to them, "Thus says Yahweh, ''You have forsaken me, therefore have I also left you in the hand of Shishak.''"'),
  ('1243957b-1136-5fdb-a6f1-0870f1218a51', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 6, 6, 'Then the princes of Israel and the king humbled themselves; and they said, "Yahweh is righteous."'),
  ('b9071352-4cad-5aab-ada6-c0bf4016c916', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 7, 7, 'When Yahweh saw that they humbled themselves, the word of Yahweh came to Shemaiah, saying, "They have humbled themselves. I will not destroy them; but I will grant them some deliverance, and my wrath shall not be poured out on Jerusalem by the hand of Shishak.'),
  ('edb9904f-2aa0-5872-ad2d-89c49e0cdcab', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 8, 8, 'Nevertheless they shall be his servants, that they may know my service, and the service of the kingdoms of the countries."'),
  ('9643e319-1b3d-59f4-a8d5-1a01a6792e4a', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 9, 9, 'So Shishak king of Egypt came up against Jerusalem, and took away the treasures of the house of Yahweh, and the treasures of the king''s house. He took it all away. He also took away the shields of gold which Solomon had made.'),
  ('ad3ba909-a7ad-50bd-a809-f38afe74b585', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 10, 10, 'King Rehoboam made in their place shields of brass, and committed them to the hands of the captains of the guard, who kept the door of the king''s house.'),
  ('4bfce0df-ad43-5f1c-a238-2c24b69526fd', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 11, 11, 'It was so, that as often as the king entered into the house of Yahweh, the guard came and bore them, and brought them back into the guard room.'),
  ('fd882248-8066-5f70-a624-d3ba93dc78fc', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 12, 12, 'When he humbled himself, the wrath of Yahweh turned from him, so as not to destroy him altogether: and moreover in Judah there were good things [found].'),
  ('cc1446bd-3c70-5c2b-a2b4-1a4475a7c17a', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 13, 13, 'So king Rehoboam strengthened himself in Jerusalem, and reigned: for Rehoboam was forty-one years old when he began to reign, and he reigned seventeen years in Jerusalem, the city which Yahweh had chosen out of all the tribes of Israel, to put his name there: and his mother''s name was Naamah the Ammonitess.'),
  ('cf7d4a1d-7cc8-50e5-a97b-35f52560cc28', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 14, 14, 'He did that which was evil, because he didn''t set his heart to seek Yahweh.'),
  ('dcc772c8-8aea-5b66-a9b2-6699d434df4f', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 15, 15, 'Now the acts of Rehoboam, first and last, aren''t they written in the histories of Shemaiah the prophet and of Iddo the seer, after the way of genealogies? There were wars between Rehoboam and Jeroboam continually.'),
  ('1bd28ac1-3a01-5863-a6df-07d87a5ade41', 'b1420085-fb69-54b8-a2ce-2180286c1b79', NULL, 16, 16, 'Rehoboam slept with his fathers, and was buried in the city of David: and Abijah his son reigned in his place.'),
  ('84a237b7-d462-5886-af02-9140d42b3728', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 1, 1, 'In the eighteenth year of king Jeroboam began Abijah to reign over Judah.'),
  ('dcd83d66-1b5e-50a4-ab14-0095c53a1aec', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 2, 2, 'Three years reigned he in Jerusalem: and his mother''s name was Micaiah the daughter of Uriel of Gibeah. There was war between Abijah and Jeroboam.'),
  ('4f2cdb12-cd7b-5206-a366-403511b9eab6', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 3, 3, 'Abijah joined battle with an army of valiant men of war, even four hundred thousand chosen men: and Jeroboam set the battle in array against him with eight hundred thousand chosen men, who were mighty men of valor.'),
  ('7e49f11a-7d5a-59dd-a65d-1a9fcceaa1cd', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 4, 4, 'Abijah stood up on Mount Zemaraim, which is in the hill country of Ephraim, and said, "Hear me, Jeroboam and all Israel:'),
  ('4868c887-7f55-549c-ab4f-0396c9538c3e', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 5, 5, 'Ought you not to know that Yahweh, the God of Israel, gave the kingdom over Israel to David forever, even to him and to his sons by a covenant of salt?'),
  ('30c69827-c0c2-59cd-a091-9b02e3fb2ae6', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 6, 6, 'Yet Jeroboam the son of Nebat, the servant of Solomon the son of David, rose up, and rebelled against his lord.'),
  ('61321a5b-45a4-5e71-ac75-0109c5c04614', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 7, 7, 'There were gathered to him worthless men, base fellows, who strengthened themselves against Rehoboam the son of Solomon, when Rehoboam was young and tenderhearted, and could not withstand them.'),
  ('747ffffc-ab58-51f1-aeb5-8af77a6affc6', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 8, 8, '"Now you think to withstand the kingdom of Yahweh in the hand of the sons of David; and you are a great multitude, and there are with you the golden calves which Jeroboam made you for gods.'),
  ('290b28fb-23fa-5d1b-a285-83cfa524c2cf', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 9, 9, 'Haven''t you driven out the priests of Yahweh, the sons of Aaron, and the Levites, and made priests for yourselves after the ways of the peoples of [other] lands? so that whoever comes to consecrate himself with a young bull and seven rams, the same may be a priest of [those who are] no gods.'),
  ('5bc47309-8797-5a8d-a2a8-528eee94edc1', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 10, 10, '"But as for us, Yahweh is our God, and we have not forsaken him; and [we have] priests ministering to Yahweh, the sons of Aaron, and the Levites in their work:'),
  ('0b0ced19-1430-5404-a629-5b02e2890a0f', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 11, 11, 'and they burn to Yahweh every morning and every evening burnt offerings and sweet incense: the show bread also [set they] in order on the pure table; and the lampstand of gold with its lamps, to burn every evening: for we keep the instruction of Yahweh our God; but you have forsaken him.'),
  ('d963f024-7c27-577b-a18f-c1177e8e51f5', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 12, 12, 'Behold, God is with us at our head, and his priests with the trumpets of alarm to sound an alarm against you. Children of Israel, don''t fight against Yahweh, the God of your fathers; for you shall not prosper."'),
  ('e477fe63-dcd3-558b-a686-68eb733d6f79', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 13, 13, 'But Jeroboam caused an ambush to come about behind them: so they were before Judah, and the ambush was behind them.'),
  ('594ec7fa-559c-540a-a7d9-0651c674e5ab', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 14, 14, 'When Judah looked back, behold, the battle was before and behind them; and they cried to Yahweh, and the priests sounded with the trumpets.'),
  ('a2f3dcee-1a50-513d-a82d-5383a20b0664', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 15, 15, 'Then the men of Judah gave a shout: and as the men of Judah shouted, it happened, that God struck Jeroboam and all Israel before Abijah and Judah.'),
  ('90ea3c30-fdfd-555f-a19c-dd0680163524', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 16, 16, 'The children of Israel fled before Judah; and God delivered them into their hand.'),
  ('54fa5c86-64b1-585d-aad8-cfde04b97756', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 17, 17, 'Abijah and his people killed them with a great slaughter: so there fell down slain of Israel five hundred thousand chosen men.'),
  ('b00f39e5-1418-55c6-ad09-119182434efd', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 18, 18, 'Thus the children of Israel were brought under at that time, and the children of Judah prevailed, because they relied on Yahweh, the God of their fathers.'),
  ('4e4fcfd1-46bf-5be7-a904-da7a479269ce', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 19, 19, 'Abijah pursued after Jeroboam, and took cities from him, Bethel with its towns, and Jeshanah with its towns, and Ephron with its towns.'),
  ('7086be16-c1e9-5286-adb2-c9b858296cfc', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 20, 20, 'Neither did Jeroboam recover strength again in the days of Abijah: and Yahweh struck him, and he died.'),
  ('997638f7-9ac0-5c06-a22e-5b00ad24a7f1', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 21, 21, 'But Abijah grew mighty, and took to himself fourteen wives, and became the father of twenty-two sons, and sixteen daughters.'),
  ('299b9191-0cf9-5c94-ae89-bcd24d7f29d6', '90e3f413-4241-52c6-a182-78199f9f598a', NULL, 22, 22, 'The rest of the acts of Abijah, and his ways, and his sayings, are written in the commentary of the prophet Iddo.'),
  ('92c9f5aa-9d38-54b1-a2b7-6f439f2bc3aa', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 1, 1, 'So Abijah slept with his fathers, and they buried him in the city of David; and Asa his son reigned in his place. In his days the land was quiet ten years.'),
  ('709112f2-2d2d-5575-af4b-f6096683d36d', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 2, 2, 'Asa did that which was good and right in the eyes of Yahweh his God:'),
  ('ef226e9d-ea4b-5977-a3e5-f894fc80cd48', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 3, 3, 'for he took away the foreign altars, and the high places, and broke down the pillars, and cut down the Asherim,'),
  ('b870f86c-1b94-5b4d-ad70-04baa6187494', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 4, 4, 'and commanded Judah to seek Yahweh, the God of their fathers, and to do the law and the commandment.'),
  ('b1c4c12f-3e80-59f9-af5d-8789bbefc6ac', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 5, 5, 'Also he took away out of all the cities of Judah the high places and the sun images: and the kingdom was quiet before him.'),
  ('d206cadf-c986-50f6-aceb-a8cb5ac70498', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 6, 6, 'He built fortified cities in Judah; for the land was quiet, and he had no war in those years, because Yahweh had given him rest.'),
  ('4f613d44-5acf-5908-ae78-0ce55d9fd1b6', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 7, 7, 'For he said to Judah, "Let us build these cities, and make walls around them, with towers, gates, and bars. The land is yet before us, because we have sought Yahweh our God; we have sought him, and he has given us rest on every side." So they built and prospered.'),
  ('2c1dff21-46ac-5534-a879-21068ee0c84e', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 8, 8, 'Asa had an army that bore bucklers and spears, out of Judah three hundred thousand; and out of Benjamin, that bore shields and drew bows, two hundred eighty thousand: all these were mighty men of valor.'),
  ('13c2fc5e-7bbf-5c15-a6e3-094ca61a719d', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 9, 9, 'There came out against them Zerah the Ethiopian with an army of a million troops, and three hundred chariots; and he came to Mareshah.'),
  ('e907129e-29c1-5aec-aa6d-5361c21db8de', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 10, 10, 'Then Asa went out to meet him, and they set the battle in array in the valley of Zephathah at Mareshah.'),
  ('54cc6711-29c1-57df-a47d-e393f700aa09', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 11, 11, 'Asa cried to Yahweh his God, and said, "Yahweh, there is none besides you to help, between the mighty and him who has no strength. Help us, Yahweh our God; for we rely on you, and in your name are we come against this multitude. Yahweh, you are our God. Don''t let man prevail against you."'),
  ('7c911da3-fcb5-5645-ab2b-c4735a3643b3', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 12, 12, 'So Yahweh struck the Ethiopians before Asa, and before Judah; and the Ethiopians fled.'),
  ('6cb71e5f-c922-5623-a937-dbe859db530b', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 13, 13, 'Asa and the people who were with him pursued them to Gerar: and there fell of the Ethiopians so many that they could not recover themselves; for they were destroyed before Yahweh, and before his army; and they carried away very much booty.'),
  ('d0e1b087-9605-579e-a61f-4ee43e899df2', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 14, 14, 'They struck all the cities around Gerar; for the fear of Yahweh came on them: and they despoiled all the cities; for there was much spoil in them.'),
  ('71391d3e-c502-5c3f-a231-23632bf06ceb', 'ed488863-b53a-5c5e-ace9-6d017505f30c', NULL, 15, 15, 'They struck also the tents of livestock, and carried away sheep in abundance, and camels, and returned to Jerusalem.'),
  ('c84ac719-24cb-5902-ad5e-12f12652712c', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 1, 1, 'The Spirit of God came on Azariah the son of Oded:'),
  ('4210ff10-0559-5f8e-a775-aa322c4277a7', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 2, 2, 'and he went out to meet Asa, and said to him, "Hear me, Asa, and all Judah and Benjamin! Yahweh is with you, while you are with him; and if you seek him, he will be found by you; but if you forsake him, he will forsake you.'),
  ('c4a7dbef-9f39-51ed-a9f9-fa0babad96f8', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 3, 3, 'Now for a long time Israel was without the true God, and without a teaching priest, and without law.'),
  ('0b81b983-cc48-5b7d-aade-fcbd1204ef54', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 4, 4, 'But when in their distress they turned to Yahweh, the God of Israel, and sought him, he was found by them.'),
  ('afc2f347-18f9-56eb-a483-c9ce9b66887d', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 5, 5, 'In those times there was no peace to him who went out, nor to him who came in; but great troubles were on all the inhabitants of the lands.'),
  ('f1a1b6f1-986d-5ba8-a951-2167f6826d88', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 6, 6, 'They were broken in pieces, nation against nation, and city against city; for God troubled them with all adversity.'),
  ('4e4ce532-563a-5350-a72d-e44f2ab090da', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 7, 7, 'But you be strong, and don''t let your hands be slack; for your work shall be rewarded."'),
  ('f179fa8c-f38e-5f5c-a13b-0219678d50ce', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 8, 8, 'When Asa heard these words, and the prophecy of Oded the prophet, he took courage, and put away the abominations out of all the land of Judah and Benjamin, and out of the cities which he had taken from the hill country of Ephraim; and he renewed the altar of Yahweh, that was before the porch of Yahweh.'),
  ('b3eefd9c-583c-5639-a7d6-b24c8b4d94d1', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 9, 9, 'He gathered all Judah and Benjamin, and those who lived with them out of Ephraim and Manasseh, and out of Simeon: for they fell to him out of Israel in abundance, when they saw that Yahweh his God was with him.'),
  ('35939ffc-d475-505e-aa52-b5fcdbb6d439', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 10, 10, 'So they gathered themselves together at Jerusalem in the third month, in the fifteenth year of the reign of Asa.'),
  ('07e1a33f-b7af-50fa-acf5-658d58965b9f', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 11, 11, 'They sacrificed to Yahweh in that day, of the spoil which they had brought, seven hundred head of cattle and seven thousand sheep.'),
  ('016efac8-3d21-56b0-ae42-2bdd87f29b5b', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 12, 12, 'They entered into the covenant to seek Yahweh, the God of their fathers, with all their heart and with all their soul;'),
  ('279b9d77-4675-5527-a228-57bb9187c0e2', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 13, 13, 'and that whoever would not seek Yahweh, the God of Israel, should be put to death, whether small or great, whether man or woman.'),
  ('1048a8d0-a39c-57f4-ae2a-9b97cec1dd62', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 14, 14, 'They swore to Yahweh with a loud voice, and with shouting, and with trumpets, and with cornets.'),
  ('47219d8d-7dd9-5f6a-a1f8-00d082dd14d7', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 15, 15, 'All Judah rejoiced at the oath; for they had sworn with all their heart, and sought him with their whole desire; and he was found of them: and Yahweh gave them rest all around.'),
  ('6eab9cc0-6289-5bda-a027-82d77b29cb99', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 16, 16, 'Also Maacah, the mother of Asa the king, he removed from being queen, because she had made an abominable image for an Asherah; and Asa cut down her image, and made dust of it, and burnt it at the brook Kidron.'),
  ('f3984788-3b5e-5ddf-ae97-fb83b8a2b16d', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 17, 17, 'But the high places were not taken away out of Israel: nevertheless the heart of Asa was perfect all his days.'),
  ('a34f29d5-dd32-5036-a3cb-9503ace01249', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 18, 18, 'He brought into the house of God the things that his father had dedicated, and that he himself had dedicated, silver, and gold, and vessels.'),
  ('c95f899d-0230-51f5-abd4-33100c150d04', '848c152a-117b-5092-afe5-c8b38d58e655', NULL, 19, 19, 'There was no more war to the five and thirtieth year of the reign of Asa.'),
  ('fa93280e-388d-5f54-a0d1-685ec6814167', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 1, 1, 'In the six and thirtieth year of the reign of Asa, Baasha king of Israel went up against Judah, and built Ramah, that he might not allow anyone to go out or come in to Asa king of Judah.'),
  ('03e19bef-65e9-55c6-a275-c98c31aab71e', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 2, 2, 'Then Asa brought out silver and gold out of the treasures of the house of Yahweh and of the king''s house, and sent to Ben Hadad king of Syria, who lived at Damascus, saying,'),
  ('d9f20b3c-9866-5e89-a32b-45879cc04d66', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 3, 3, '"Let there be a treaty between me and you, as there was between my father and your father. Behold, I have sent you silver and gold. Go, break your treaty with Baasha king of Israel, that he may depart from me."'),
  ('95ab26bb-8c3a-575c-a369-51af144a02ff', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 4, 4, 'Ben Hadad listened to king Asa, and sent the captains of his armies against the cities of Israel; and they struck Ijon, and Dan, and Abel Maim, and all the storage cities of Naphtali.'),
  ('7fa6bd85-7b0a-50c0-a965-c96b5467efdf', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 5, 5, 'It happened, when Baasha heard of it, that he left off building Ramah, and let his work cease.'),
  ('832127f8-be42-5eee-aa69-eda07edd75fa', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 6, 6, 'Then Asa the king took all Judah; and they carried away the stones of Ramah, and its timber, with which Baasha had built; and he built therewith Geba and Mizpah.'),
  ('826d9f94-0047-51a4-a5ce-963ee54ef846', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 7, 7, 'At that time Hanani the seer came to Asa king of Judah, and said to him, "Because you have relied on the king of Syria, and have not relied on Yahweh your God, therefore is the army of the king of Syria escaped out of your hand.'),
  ('e7293c99-10c2-5729-a46a-03a490678e3b', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 8, 8, 'Weren''t the Ethiopians and the Lubim a huge army, with chariots and horsemen exceeding many? Yet, because you relied on Yahweh, he delivered them into your hand.'),
  ('6bc0215f-bd6d-595b-a223-7844634ecca7', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 9, 9, 'For the eyes of Yahweh run back and forth throughout the whole earth, to show himself strong in the behalf of them whose heart is perfect toward him. Herein you have done foolishly; for from henceforth you shall have wars."'),
  ('a903a6fe-8b3d-576f-a17b-d2db6a768801', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 10, 10, 'Then Asa was angry with the seer, and put him in the prison; for he was in a rage with him because of this thing. Asa oppressed some of the people at the same time.'),
  ('ad86d052-f741-568c-a2b1-a95ef82a26b2', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 11, 11, 'Behold, the acts of Asa, first and last, behold, they are written in the book of the kings of Judah and Israel.'),
  ('18c8e5cd-48be-59da-a31f-1b5f5a84fbef', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 12, 12, 'In the thirty-ninth year of his reign Asa was diseased in his feet; his disease was exceeding great: yet in his disease he didn''t seek Yahweh, but to the physicians.'),
  ('12633e81-e5dc-5039-a956-b18c03326ca5', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 13, 13, 'Asa slept with his fathers, and died in the one and fortieth year of his reign.'),
  ('45cd0ab2-aebf-5f10-ace0-6eed871a204e', '3dbb18ca-604f-5ceb-a13a-baf9827d6894', NULL, 14, 14, 'They buried him in his own tombs, which he had dug out for himself in the city of David, and laid him in the bed which was filled with sweet odors and various kinds [of spices] prepared by the perfumers'' art: and they made a very great burning for him.'),
  ('294cfc69-7c4f-5861-a2e8-91fc222969ce', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 1, 1, 'Jehoshaphat his son reigned in his place, and strengthened himself against Israel.'),
  ('f22d763d-cbd4-5c78-ac73-8ff83f92cbac', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 2, 2, 'He placed forces in all the fortified cities of Judah, and set garrisons in the land of Judah, and in the cities of Ephraim, which Asa his father had taken.'),
  ('59d7fba6-1d03-5d69-ac35-de2947c508cd', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 3, 3, 'Yahweh was with Jehoshaphat, because he walked in the first ways of his father David, and didn''t seek the Baals,'),
  ('9bde3ec2-37c1-589f-acbf-55ca521863a8', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 4, 4, 'but sought to the God of his father, and walked in his commandments, and not after the doings of Israel.'),
  ('ac27fe79-0772-5a88-aed7-93a6a33f6d51', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 5, 5, 'Therefore Yahweh established the kingdom in his hand; and all Judah brought to Jehoshaphat tribute; and he had riches and honor in abundance.'),
  ('e452229b-06f0-5765-aff3-a7f6894a125f', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 6, 6, 'His heart was lifted up in the ways of Yahweh: and furthermore he took away the high places and the Asherim out of Judah.'),
  ('1a838fb2-bdd2-5e63-a4a4-6710e1dae630', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 7, 7, 'Also in the third year of his reign he sent his princes, even Ben Hail, and Obadiah, and Zechariah, and Nethanel, and Micaiah, to teach in the cities of Judah;'),
  ('99a7160c-487a-5d86-ac22-da4b355c0a9d', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 8, 8, 'and with them the Levites, even Shemaiah, and Nethaniah, and Zebadiah, and Asahel, and Shemiramoth, and Jehonathan, and Adonijah, and Tobijah, and Tobadonijah, the Levites; and with them Elishama and Jehoram, the priests.'),
  ('a122a6f1-2fa3-5d83-a935-acf856188075', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 9, 9, 'They taught in Judah, having the book of the law of Yahweh with them; and they went about throughout all the cities of Judah, and taught among the people.'),
  ('61124d21-81cd-5ce3-a667-7a4543e82ca3', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 10, 10, 'The fear of Yahweh fell on all the kingdoms of the lands that were around Judah, so that they made no war against Jehoshaphat.'),
  ('3156e2e4-47f6-5fae-afd5-697f049776ae', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 11, 11, 'Some of the Philistines brought Jehoshaphat presents, and silver for tribute; the Arabians also brought him flocks, seven thousand and seven hundred rams, and seven thousand and seven hundred male goats.'),
  ('1cbe4189-d637-55e5-a7ab-1f1053750132', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 12, 12, 'Jehoshaphat grew great exceedingly; and he built in Judah castles and cities of store.'),
  ('de16b4b2-dd89-54e9-ad58-a407dfbb3d99', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 13, 13, 'He had many works in the cities of Judah; and men of war, mighty men of valor, in Jerusalem.'),
  ('6b38332c-7f39-54f4-afd3-41f8d8205059', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 14, 14, 'This was the numbering of them according to their fathers'' houses: Of Judah, the captains of thousands: Adnah the captain, and with him mighty men of valor three hundred thousand;'),
  ('61213e14-eece-5261-a817-ffab1da13f35', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 15, 15, 'and next to him Jehohanan the captain, and with him two hundred eighty thousand;'),
  ('54e43cc5-9059-51d9-a89f-5b036405c1e9', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 16, 16, 'and next to him Amasiah the son of Zichri, who willingly offered himself to Yahweh; and with him two hundred thousand mighty men of valor.'),
  ('19723098-5455-55f5-a3db-2bff05dc20a4', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 17, 17, 'Of Benjamin: Eliada a mighty man of valor, and with him two hundred thousand armed with bow and shield;'),
  ('999fa3aa-4d1c-5f96-adee-b680616f235d', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 18, 18, 'and next to him Jehozabad and with him one hundred eighty thousand ready prepared for war.'),
  ('2ef4daa8-0497-5422-adf8-54e445432d4a', '7690a039-ebc9-5702-acd0-f15ce3d49d57', NULL, 19, 19, 'These were those who waited on the king, besides those whom the king put in the fortified cities throughout all Judah.'),
  ('fc0e1549-b411-5c7a-acf6-73e33465a1b2', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 1, 1, 'Now Jehoshaphat had riches and honor in abundance; and he joined affinity with Ahab.'),
  ('9c566a0e-19c5-5861-a1e3-06076331ac28', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 2, 2, 'After certain years he went down to Ahab to Samaria. Ahab killed sheep and cattle for him in abundance, and for the people who were with him, and moved him to go up [with him] to Ramoth Gilead.'),
  ('9d6f2cf8-3dbd-5ff8-a7cf-f8503f376d6c', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 3, 3, 'Ahab king of Israel said to Jehoshaphat king of Judah, "Will you go with me to Ramoth Gilead?" He answered him, "I am as you are, and my people as your people. We will be with you in the war."'),
  ('aff06165-e93d-5e10-a1ba-a8a8ae2613a4', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 4, 4, 'Jehoshaphat said to the king of Israel, "Please inquire first for the word of Yahweh."'),
  ('23b99773-d51e-55bd-ab47-d422230a94f4', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 5, 5, 'Then the king of Israel gathered the prophets together, four hundred men, and said to them, "Shall we go to Ramoth Gilead to battle, or shall I forbear?" They said, "Go up; for God will deliver it into the hand of the king."'),
  ('c55cf1e9-e4b2-57eb-a00e-f0722e13bc24', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 6, 6, 'But Jehoshaphat said, "Isn''t there here a prophet of Yahweh besides, that we may inquire of him?"'),
  ('3eadc83f-2ab3-53b9-a8e2-fd75dda5b8f8', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 7, 7, 'The king of Israel said to Jehoshaphat, "There is yet one man by whom we may inquire of Yahweh; but I hate him, for he never prophesies good concerning me, but always evil. He is Micaiah the son of Imla." Jehoshaphat said, "Don''t let the king say so."'),
  ('55be86a3-0be9-5e72-ab1e-482ef5fbc8f5', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 8, 8, 'Then the king of Israel called an officer, and said, "Get Micaiah the son of Imla quickly."'),
  ('851e381c-6427-5f17-a4da-e85f780d8867', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 9, 9, 'Now the king of Israel and Jehoshaphat the king of Judah sat each on his throne, arrayed in their robes, and they were sitting in an open place at the entrance of the gate of Samaria; and all the prophets were prophesying before them.'),
  ('6f0b1316-fe07-5126-a9fb-cbfd13fd18cc', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 10, 10, 'Zedekiah the son of Chenaanah made him horns of iron, and said, "Thus says Yahweh, ''With these you shall push the Syrians, until they are consumed.''"'),
  ('7d416c8a-7653-5b22-a938-4fd3f32c6231', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 11, 11, 'All the prophets prophesied so, saying, "Go up to Ramoth Gilead, and prosper; for Yahweh will deliver it into the hand of the king."'),
  ('16773dc5-04dd-51ad-a677-c14336a6b0c4', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 12, 12, 'The messenger who went to call Micaiah spoke to him, saying, "Behold, the words of the prophets [declare] good to the king with one mouth. Let your word therefore, please be like one of theirs, and speak good."'),
  ('d3c1d353-3291-50c0-a0a6-8c918ffe3682', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 13, 13, 'Micaiah said, "As Yahweh lives, what my God says, that will I speak."'),
  ('21c52935-ccb8-5509-a94c-314788bb5179', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 14, 14, 'When he had come to the king, the king said to him, "Micaiah, shall we go to Ramoth Gilead to battle, or shall I forbear?" He said, "Go up, and prosper. They shall be delivered into your hand."'),
  ('a19a6dae-31cc-5f46-addc-7d510520cd81', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 15, 15, 'The king said to him, "How many times shall I adjure you that you speak to me nothing but the truth in the name of Yahweh?"'),
  ('e5e8cb90-247b-53a0-a08f-284eaca46a7d', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 16, 16, 'He said, "I saw all Israel scattered on the mountains, as sheep that have no shepherd. Yahweh said, ''These have no master. Let them return every man to his house in peace.''"'),
  ('74611693-a458-570f-ac0b-27cc9bf873fd', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 17, 17, 'The king of Israel said to Jehoshaphat, "Didn''t I tell you that he would not prophesy good concerning me, but evil?"'),
  ('a137075f-1fc8-566b-aa3e-4c5c9cd72ccb', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 18, 18, '[Micaiah] said, "Therefore hear the word of Yahweh: I saw Yahweh sitting on his throne, and all the army of heaven standing on his right hand and on his left.'),
  ('af8c0eab-6d35-5c3d-aca8-06faad406a40', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 19, 19, 'Yahweh said, ''Who shall entice Ahab king of Israel, that he may go up and fall at Ramoth Gilead?'' One spoke saying in this way, and another saying in that way.'),
  ('b88adc3c-9405-5448-a9c3-660ba9670712', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 20, 20, 'A spirit came out, stood before Yahweh, and said, ''I will entice him.'' "Yahweh said to him, ''How?'''),
  ('67aa54cd-166e-53c2-a91e-1a283ed37958', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 21, 21, '"He said, ''I will go forth, and will be a lying spirit in the mouth of all his prophets.'' "He said, ''You will entice him, and will prevail also. Go forth, and do so.'''),
  ('16ee5bc1-6372-5615-a7c9-3468a33f338a', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 22, 22, '"Now therefore, behold, Yahweh has put a lying spirit in the mouth of these your prophets; and Yahweh has spoken evil concerning you."'),
  ('0579a2db-2622-5341-a3b8-621fa9a71632', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 23, 23, 'Then Zedekiah the son of Chenaanah came near, and struck Micaiah on the cheek, and said, "Which way did the Spirit of Yahweh go from me to speak to you?"'),
  ('60ff706e-cdcd-598f-a8a5-f686449b5980', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 24, 24, 'Micaiah said, "Behold, you shall see on that day, when you shall go into an inner room to hide yourself."'),
  ('54058a8f-543b-5edb-ad3e-4f4fbb488a86', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 25, 25, 'The king of Israel said, "Take Micaiah, and carry him back to Amon the governor of the city, and to Joash the king''s son;'),
  ('d485c8b4-01bc-5e73-a98f-d261ef23bb93', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 26, 26, 'and say, ''Thus says the king, "Put this fellow in the prison, and feed him with bread of affliction and with water of affliction, until I return in peace."''"'),
  ('031b3375-55ee-5641-af32-64ba57da9358', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 27, 27, 'Micaiah said, "If you return at all in peace, Yahweh has not spoken by me." He said, "Listen, you peoples, all of you!"'),
  ('9adc9cf6-2a9f-5cb1-a2c2-d21c1e6217c7', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 28, 28, 'So the king of Israel and Jehoshaphat the king of Judah went up to Ramoth Gilead.'),
  ('00bfa6cf-1215-55bc-a0c5-2532e18b8b1e', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 29, 29, 'The king of Israel said to Jehoshaphat, "I will disguise myself, and go into the battle; but you put on your robes." So the king of Israel disguised himself; and they went into the battle.'),
  ('613a8bf2-7335-5af0-ac29-88670326d9c1', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 30, 30, 'Now the king of Syria had commanded the captains of his chariots, saying, "Fight neither with small nor great, except only with the king of Israel."'),
  ('e3d0057d-d107-5643-aa29-2bb3a88644f4', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 31, 31, 'It happened, when the captains of the chariots saw Jehoshaphat, that they said, "It is the king of Israel!" Therefore they turned around to fight against him. But Jehoshaphat cried out, and Yahweh helped him; and God moved them to depart from him.'),
  ('8ae7ec93-0b1e-59c4-a945-656458363ee1', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 32, 32, 'It happened, when the captains of the chariots saw that it was not the king of Israel, that they turned back from pursuing him.'),
  ('756d4817-5cf9-592a-a2af-c6238646fcc1', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 33, 33, 'A certain man drew his bow at random, and struck the king of Israel between the joints of the armor. Therefore he said to the driver of the chariot, "Turn your hand, and carry me out of the army; for I am severely wounded."'),
  ('0620e319-9d72-5480-aad6-d9d7a12fc72f', 'ed8e1efd-8eb4-530f-a5af-71b7cc6fe6c8', NULL, 34, 34, 'The battle increased that day. However the king of Israel propped himself up in his chariot against the Syrians until the evening; and about the time of the going down of the sun, he died.'),
  ('f31e782f-ab78-5dcf-ab14-50e368006fe2', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 1, 1, 'Jehoshaphat the king of Judah returned to his house in peace to Jerusalem.'),
  ('f4483f32-db46-5e79-afd0-790ec7b9599e', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 2, 2, 'Jehu the son of Hanani the seer went out to meet him, and said to king Jehoshaphat, "Should you help the wicked, and love those who hate Yahweh? Because of this, wrath is on you from before Yahweh.'),
  ('78f0ac7b-20dd-52a1-a0f5-22ff3f91938d', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 3, 3, 'Nevertheless there are good things found in you, in that you have put away the Asheroth out of the land, and have set your heart to seek God."'),
  ('3aca851b-aedf-52b4-aab8-9f4162fe095a', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 4, 4, 'Jehoshaphat lived at Jerusalem: and he went out again among the people from Beersheba to the hill country of Ephraim, and brought them back to Yahweh, the God of their fathers.'),
  ('a99d91ca-2085-57c5-a0e3-003770b1c059', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 5, 5, 'He set judges in the land throughout all the fortified cities of Judah, city by city,'),
  ('be06b882-4d0a-55e7-a563-cb5110d2fb61', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 6, 6, 'and said to the judges, "Consider what you do: for you don''t judge for man, but for Yahweh; and [he is] with you in the judgment.'),
  ('1213663e-0993-560e-abf1-941c1e9bbf79', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 7, 7, 'Now therefore let the fear of Yahweh be on you. Take heed and do it: for there is no iniquity with Yahweh our God, nor respect of persons, nor taking of bribes."'),
  ('edacce77-ebe0-50b6-ab71-d6fa73f2628e', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 8, 8, 'Moreover in Jerusalem Jehoshaphat appointed Levites and priests, and of the heads of the fathers'' [houses] of Israel, for the judgment of Yahweh, and for controversies. They returned to Jerusalem.'),
  ('46de16e0-3701-59a4-af42-18dc7112cdf3', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 9, 9, 'He commanded them, saying, "Thus you shall do in the fear of Yahweh, faithfully, and with a perfect heart.'),
  ('cdd7d232-8146-57e5-aae4-9cafc067cabc', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 10, 10, 'Whenever any controversy shall come to you from your brothers who dwell in their cities, between blood and blood, between law and commandment, statutes and ordinances, you shall warn them, that they not be guilty towards Yahweh, and so wrath come on you and on your brothers. Do this, and you shall not be guilty.'),
  ('7145cc04-731f-538f-a7a0-62e1fe8d70e0', 'e2a80bbf-4078-5dc4-ab49-f9cba69c9730', NULL, 11, 11, 'Behold, Amariah the chief priest is over you in all matters of Yahweh; and Zebadiah the son of Ishmael, the ruler of the house of Judah, in all the king''s matters: also the Levites shall be officers before you. Deal courageously, and may Yahweh be with the good."'),
  ('6d5d33dd-3562-583b-a240-4c7e07e9aa0a', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 1, 1, 'It happened after this, that the children of Moab, and the children of Ammon, and with them some of the Ammonites, came against Jehoshaphat to battle.'),
  ('7536aeaf-28a9-5553-a497-d47e14b7fd5f', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 2, 2, 'Then some came who told Jehoshaphat, saying, "A great multitude is coming against you from beyond the sea from Syria. Behold, they are in Hazazon Tamar" (that is, En Gedi).'),
  ('fedf15da-5f97-5a08-ac92-bf3adeb92e7c', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 3, 3, 'Jehoshaphat was alarmed, and set himself to seek to Yahweh. He proclaimed a fast throughout all Judah.'),
  ('12dacd7d-5089-51a9-af89-1a5d4038a7d9', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 4, 4, 'Judah gathered themselves together, to seek help from Yahweh. They came out of all the cities of Judah to seek Yahweh.'),
  ('8e28c46e-f594-5f32-af4c-d389f138c714', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 5, 5, 'Jehoshaphat stood in the assembly of Judah and Jerusalem, in the house of Yahweh, before the new court;'),
  ('7fa8cfef-afd9-5e01-a15e-e862ca01eb4f', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 6, 6, 'and he said, "Yahweh, the God of our fathers, aren''t you God in heaven? Aren''t you ruler over all the kingdoms of the nations? Power and might are in your hand, so that no one is able to withstand you.'),
  ('81a9ff4a-156e-5cf0-a78f-13109e873389', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 7, 7, 'Didn''t you, our God, drive out the inhabitants of this land before your people Israel, and give it to the seed of Abraham your friend forever?'),
  ('f7406516-0cc0-5ab7-a066-11479c4f11fe', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 8, 8, 'They lived in it, and have built you a sanctuary in it for your name, saying,'),
  ('7033253e-4bb3-58e2-a991-894282d3fd85', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 9, 9, '''If evil comes on us--the sword, judgment, pestilence, or famine--we will stand before this house, and before you, (for your name is in this house), and cry to you in our affliction, and you will hear and save.'''),
  ('98a9a461-31ba-590d-a259-4f18c0a33760', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 10, 10, 'Now, behold, the children of Ammon and Moab and Mount Seir, whom you would not let Israel invade, when they came out of the land of Egypt, but they turned aside from them, and didn''t destroy them;'),
  ('338c00ee-b06d-5f6f-ac9c-9acddc5e9cbb', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 11, 11, 'behold, how they reward us, to come to cast us out of your possession, which you have given us to inherit.'),
  ('5cd335d3-1c88-5105-abcf-81a278de7446', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 12, 12, 'Our God, will you not judge them? For we have no might against this great company that comes against us; neither know we what to do, but our eyes are on you."'),
  ('9c02e825-94f5-538f-a8fa-0ed8a303480b', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 13, 13, 'All Judah stood before Yahweh, with their little ones, their wives, and their children.'),
  ('dcfaad2c-7c38-5a77-af9a-fa6ffeb56ceb', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 14, 14, 'Then the Spirit of Yahweh came on Jahaziel the son of Zechariah, the son of Benaiah, the son of Jeiel, the son of Mattaniah, the Levite, of the sons of Asaph, in the midst of the assembly;'),
  ('ce9c9df2-ff5d-5817-a5f0-900c7f8a52ab', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 15, 15, 'and he said, "Listen, all Judah, and you inhabitants of Jerusalem, and you king Jehoshaphat. Thus says Yahweh to you, ''Don''t be afraid, neither be dismayed by reason of this great multitude; for the battle is not yours, but God''s.'),
  ('e370f059-a895-5efd-a4fc-e87ea5310505', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 16, 16, 'Tomorrow go down against them. Behold, they are coming up by the ascent of Ziz. You shall find them at the end of the valley, before the wilderness of Jeruel.'),
  ('e2a0a387-1195-528c-a840-1a7253b9b4ef', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 17, 17, 'You will not need to fight this battle. Set yourselves, stand still, and see the salvation of Yahweh with you, O Judah and Jerusalem. Don''t be afraid, nor be dismayed. Go out against them tomorrow, for Yahweh is with you.''"'),
  ('d1dee9f0-e7c0-599e-a1da-e62569c98dc1', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 18, 18, 'Jehoshaphat bowed his head with his face to the ground; and all Judah and the inhabitants of Jerusalem fell down before Yahweh, worshipping Yahweh.'),
  ('bd4e7551-0c92-5fe6-a549-8592b1553c67', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 19, 19, 'The Levites, of the children of the Kohathites and of the children of the Korahites, stood up to praise Yahweh, the God of Israel, with an exceeding loud voice.'),
  ('80552936-04dc-5d5f-af99-ddec875918de', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 20, 20, 'They rose early in the morning, and went forth into the wilderness of Tekoa: and as they went forth, Jehoshaphat stood and said, "Listen to me, Judah, and you inhabitants of Jerusalem! Believe in Yahweh your God, so you shall be established! Believe his prophets, so you shall prosper."'),
  ('525723f8-7d0f-5a83-a5fc-b26abbbca756', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 21, 21, 'When he had taken counsel with the people, he appointed those who should sing to Yahweh, and give praise in holy array, as they went out before the army, and say, Give thanks to Yahweh; for his loving kindness endures forever.'),
  ('48668e8c-53ef-5af7-a081-fceee0905e19', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 22, 22, 'When they began to sing and to praise, Yahweh set ambushers against the children of Ammon, Moab, and Mount Seir, who had come against Judah; and they were struck.'),
  ('e730bbab-d46e-52b9-a87c-12f580182ccc', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 23, 23, 'For the children of Ammon and Moab stood up against the inhabitants of Mount Seir, utterly to kill and destroy them: and when they had made an end of the inhabitants of Seir, everyone helped to destroy another.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('360e0a62-6dbf-5414-a5be-8089e016748e', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 24, 24, 'When Judah came to the place overlooking the wilderness, they looked at the multitude; and behold, they were dead bodies fallen to the earth, and there were none who escaped.'),
  ('27cd6aea-1e6c-59a3-acf6-ca147b87ea8e', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 25, 25, 'When Jehoshaphat and his people came to take the spoil of them, they found among them in abundance both riches and dead bodies, and precious jewels, which they stripped off for themselves, more than they could carry away: and they were three days in taking the spoil, it was so much.'),
  ('4de1b059-85c9-58b8-a1bb-8e9979aee6bf', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 26, 26, 'On the fourth day they assembled themselves in the valley of Beracah; for there they blessed Yahweh: therefore the name of that place was called The valley of Beracah to this day.'),
  ('994f4a2c-6236-5627-a93d-0da0fb008a31', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 27, 27, 'Then they returned, every man of Judah and Jerusalem, and Jehoshaphat in the forefront of them, to go again to Jerusalem with joy; for Yahweh had made them to rejoice over their enemies.'),
  ('c430214d-faf9-5240-a6f8-ee3d2f77b4b4', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 28, 28, 'They came to Jerusalem with stringed instruments and harps and trumpets to the house of Yahweh.'),
  ('7555d8c1-9e87-59c4-a490-f3765685c0d2', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 29, 29, 'The fear of God was on all the kingdoms of the countries, when they heard that Yahweh fought against the enemies of Israel.'),
  ('15d55b67-f27c-5969-a987-d3420a270454', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 30, 30, 'So the realm of Jehoshaphat was quiet; for his God gave him rest all around.'),
  ('795dc194-4564-5973-a318-e78c8f77bd7c', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 31, 31, 'Jehoshaphat reigned over Judah: he was thirty-five years old when he began to reign; and he reigned twenty-five years in Jerusalem: and his mother''s name was Azubah the daughter of Shilhi.'),
  ('1f5ab3b5-5e5e-5ae4-ae3d-d22cf72cdf98', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 32, 32, 'He walked in the way of Asa his father, and didn''t turn aside from it, doing that which was right in the eyes of Yahweh.'),
  ('89bd40f3-b146-5271-a108-3752dff432ec', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 33, 33, 'However the high places were not taken away; neither as yet had the people set their hearts to the God of their fathers.'),
  ('5d021be7-29a3-5bb4-a3c2-4998d3c19a4b', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 34, 34, 'Now the rest of the acts of Jehoshaphat, first and last, behold, they are written in the history of Jehu the son of Hanani, which is inserted in the book of the kings of Israel.'),
  ('150b86a2-bcb4-5d93-ad1b-198e148cf5cd', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 35, 35, 'After this did Jehoshaphat king of Judah join himself with Ahaziah king of Israel; the same did very wickedly:'),
  ('bc646e23-b905-5738-ab9e-0d7411dd0b92', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 36, 36, 'and he joined himself with him to make ships to go to Tarshish; and they made the ships in Ezion Geber.'),
  ('334e5ed4-862d-5309-a2e9-02ad597516ee', 'feba7a0a-daea-536a-a428-eb20ca7da67b', NULL, 37, 37, 'Then Eliezer the son of Dodavahu of Mareshah prophesied against Jehoshaphat, saying, "Because you have joined yourself with Ahaziah, Yahweh has destroyed your works." The ships were broken, so that they were not able to go to Tarshish.'),
  ('3a665365-69a9-559d-ad39-26e2e97d87df', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 1, 1, 'Jehoshaphat slept with his fathers, and was buried with his fathers in the city of David: and Jehoram his son reigned in his place.'),
  ('5d1ae99c-e652-52d7-a382-9ac151caf7d4', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 2, 2, 'He had brothers, the sons of Jehoshaphat: Azariah, and Jehiel, and Zechariah, and Azariah, and Michael, and Shephatiah; all these were the sons of Jehoshaphat king of Israel.'),
  ('6ad5838b-663f-5234-a29b-9f92b18903d1', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 3, 3, 'Their father gave them great gifts, of silver, and of gold, and of precious things, with fortified cities in Judah: but the kingdom gave he to Jehoram, because he was the firstborn.'),
  ('216a066c-17d6-549c-a326-86423bd8562c', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 4, 4, 'Now when Jehoram was risen up over the kingdom of his father, and had strengthened himself, he killed all his brothers with the sword, and various also of the princes of Israel.'),
  ('166a6cd4-746d-5188-aef5-407d92320a14', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 5, 5, 'Jehoram was thirty-two years old when he began to reign; and he reigned eight years in Jerusalem.'),
  ('2bedd43a-dec8-5d63-abc6-c7160648a632', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 6, 6, 'He walked in the way of the kings of Israel, as did the house of Ahab; for he had the daughter of Ahab as wife: and he did that which was evil in the sight of Yahweh.'),
  ('f79ec45e-a091-5833-a867-0f7a9eb3ccb5', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 7, 7, 'However Yahweh would not destroy the house of David, because of the covenant that he had made with David, and as he promised to give a lamp to him and to his children always.'),
  ('3048a127-6f7e-5f3d-a915-ab19da1baf72', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 8, 8, 'In his days Edom revolted from under the hand of Judah, and made a king over themselves.'),
  ('c93d4c0a-45e6-55f9-a89a-e9390c71ddf5', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 9, 9, 'Then Jehoram passed over with his captains, and all his chariots with him: and he rose up by night, and struck the Edomites who surrounded him, along with the captains of the chariots.'),
  ('b73342b2-b2e6-5fc2-adcc-820b2bae54aa', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 10, 10, 'So Edom revolted from under the hand of Judah to this day: then did Libnah revolt at the same time from under his hand, because he had forsaken Yahweh, the God of his fathers.'),
  ('744eac17-0bde-5d94-a0da-700d01f6be13', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 11, 11, 'Moreover he made high places in the mountains of Judah, and made the inhabitants of Jerusalem to play the prostitute, and led Judah astray.'),
  ('c1a91659-2f5d-5b26-acf8-c643ddb40ac4', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 12, 12, 'A letter came to him from Elijah the prophet, saying, "Thus says Yahweh, the God of David your father, ''Because you have not walked in the ways of Jehoshaphat your father, nor in the ways of Asa king of Judah,'),
  ('07ea67ab-bc48-51dd-af31-7e52993f3f34', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 13, 13, 'but have walked in the way of the kings of Israel, and have made Judah and the inhabitants of Jerusalem to play the prostitute, like the house of Ahab did, and also have slain your brothers of your father''s house, who were better than yourself:'),
  ('5027772d-9975-51f1-af63-08043841e8bf', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 14, 14, 'behold, Yahweh will strike with a great plague your people, and your children, and your wives, and all your substance;'),
  ('0526a05b-9c6a-5c30-ac37-86ecfbf439ba', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 15, 15, 'and you shall have great sickness by disease of your bowels, until your bowels fall out by reason of the sickness, day by day.''"'),
  ('f1eb97dc-db93-558b-ae31-1bc3ccaaa3f2', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 16, 16, 'Yahweh stirred up against Jehoram the spirit of the Philistines, and of the Arabians who are beside the Ethiopians:'),
  ('88aed4d5-e1e1-5b03-afd9-07f1d75a3e18', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 17, 17, 'and they came up against Judah, and broke into it, and carried away all the substance that was found in the king''s house, and his sons also, and his wives; so that there was never a son left him, except Jehoahaz, the youngest of his sons.'),
  ('28387052-5ad8-5dc8-a1c3-64b8f5b10b23', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 18, 18, 'After all this Yahweh struck him in his bowels with an incurable disease.'),
  ('de24c9fb-ca75-54d8-a732-95d2f780bc2c', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 19, 19, 'It happened, in process of time, at the end of two years, that his bowels fell out by reason of his sickness, and he died of severe diseases. His people made no burning for him, like the burning of his fathers.'),
  ('2b19b9af-4f58-563d-a823-6d8069bd8678', 'd0c9fc34-4eb4-58df-a649-26bc0d13a36f', NULL, 20, 20, 'Thirty-two years old was he when he began to reign, and he reigned in Jerusalem eight years: and he departed without being desired; and they buried him in the city of David, but not in the tombs of the kings.'),
  ('00d18621-44b8-5a66-ae2e-539e45fe758c', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 1, 1, 'The inhabitants of Jerusalem made Ahaziah his youngest son king in his place; for the band of men who came with the Arabians to the camp had slain all the eldest. So Ahaziah the son of Jehoram king of Judah reigned.'),
  ('5cbe93e9-e006-5d5c-ae96-087bd45cc244', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 2, 2, 'Forty-two years old was Ahaziah when he began to reign; and he reigned one year in Jerusalem: and his mother''s name was Athaliah the daughter of Omri.'),
  ('06d053f5-a708-5a8e-a28c-0789b8b1d8b4', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 3, 3, 'He also walked in the ways of the house of Ahab; for his mother was his counselor to do wickedly.'),
  ('6db395bb-2984-5441-aead-b9cb7eb48395', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 4, 4, 'He did that which was evil in the sight of Yahweh, as did the house of Ahab; for they were his counselors after the death of his father, to his destruction.'),
  ('702ddac9-e3df-56d7-ac22-696182d7a1df', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 5, 5, 'He walked also after their counsel, and went with Jehoram the son of Ahab king of Israel to war against Hazael king of Syria at Ramoth Gilead: and the Syrians wounded Joram.'),
  ('66b087ff-31aa-55f1-a41d-de5632097ccb', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 6, 6, 'He returned to be healed in Jezreel of the wounds which they had given him at Ramah, when he fought against Hazael king of Syria. Azariah the son of Jehoram king of Judah went down to see Jehoram the son of Ahab in Jezreel, because he was sick.'),
  ('47455285-a6dd-57d3-aa1b-0da17c2eaf6e', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 7, 7, 'Now the destruction of Ahaziah was of God, in that he went to Joram: for when he was come, he went out with Jehoram against Jehu the son of Nimshi, whom Yahweh had anointed to cut off the house of Ahab.'),
  ('1bb805e4-cb36-5aef-ae56-d7e97d62d2c7', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 8, 8, 'It happened, when Jehu was executing judgment on the house of Ahab, that he found the princes of Judah, and the sons of the brothers of Ahaziah, ministering to Ahaziah, and killed them.'),
  ('c2e1bd91-2b9d-5461-affb-d9c22e527eac', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 9, 9, 'He sought Ahaziah, and they caught him (now he was hiding in Samaria), and they brought him to Jehu, and killed him; and they buried him, for they said, "He is the son of Jehoshaphat, who sought Yahweh with all his heart." The house of Ahaziah had no power to hold the kingdom.'),
  ('68ce179f-37d4-557d-ab65-cbcd2e81757a', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 10, 10, 'Now when Athaliah the mother of Ahaziah saw that her son was dead, she arose and destroyed all the royal seed of the house of Judah.'),
  ('9bc98847-39c3-5fb0-a39e-23876149cba6', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 11, 11, 'But Jehoshabeath, the daughter of the king, took Joash the son of Ahaziah, and stole him away from among the king''s sons who were slain, and put him and his nurse in the bedroom. So Jehoshabeath, the daughter of king Jehoram, the wife of Jehoiada the priest (for she was the sister of Ahaziah), hid him from Athaliah, so that she didn''t kill him.'),
  ('4c92abc5-cd0c-5113-af31-38bc7f1efaf2', 'b661265b-96e3-5ae2-a5b7-f9f17d552e60', NULL, 12, 12, 'He was with them hidden in the house of God six years: and Athaliah reigned over the land.'),
  ('e4d1b3d7-0730-52a8-a54e-2ed170e9bbad', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 1, 1, 'In the seventh year Jehoiada strengthened himself, and took the captains of hundreds, Azariah the son of Jeroham, and Ishmael the son of Jehohanan, and Azariah the son of Obed, and Maaseiah the son of Adaiah, and Elishaphat the son of Zichri, into covenant with him.'),
  ('a98e4900-d5f0-576b-af6f-355499382774', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 2, 2, 'They went about in Judah, and gathered the Levites out of all the cities of Judah, and the heads of fathers'' [houses] of Israel, and they came to Jerusalem.'),
  ('f8a8389e-b63c-581b-a7ba-010834dcbfc7', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 3, 3, 'All the assembly made a covenant with the king in the house of God. He said to them, "Behold, the king''s son shall reign, as Yahweh has spoken concerning the sons of David.'),
  ('aa1bb034-0f90-5351-a70d-cbd7477d014e', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 4, 4, 'This is the thing that you shall do. A third part of you, who come in on the Sabbath, of the priests and of the Levites, shall be porters of the thresholds.'),
  ('0a29b664-4a45-50f9-a6e3-d03a4ef532c9', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 5, 5, 'A third part shall be at the king''s house; and a third part at the gate of the foundation. All the people shall be in the courts of Yahweh''s house.'),
  ('961b193a-80c6-5d25-a87d-1ba93799a9f4', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 6, 6, 'But let no one come into the house of Yahweh, except the priests, and those who minister of the Levites. They shall come in, for they are holy, but all the people shall follow Yahweh''s instructions.'),
  ('57236930-18e9-52af-a06c-9545985f32e7', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 7, 7, 'The Levites shall surround the king, every man with his weapons in his hand. Whoever comes into the house, let him be slain. Be with the king when he comes in, and when he goes out."'),
  ('be067e72-ccca-5804-af8e-d64862d40af2', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 8, 8, 'So the Levites and all Judah did according to all that Jehoiada the priest commanded: and they took every man his men, those who were to come in on the Sabbath; with those who were to go out on the Sabbath; for Jehoiada the priest didn''t dismiss the shift.'),
  ('026929df-4172-5442-a946-0a80999dc101', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 9, 9, 'Jehoiada the priest delivered to the captains of hundreds the spears, and bucklers, and shields, that had been king David''s, which were in the house of God.'),
  ('f6a796c6-7522-509b-a2c9-40cf33d632f9', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 10, 10, 'He set all the people, every man with his weapon in his hand, from the right side of the house to the left side of the house, along by the altar and the house, around the king.'),
  ('461e0f87-4227-55e1-aac1-e556b8cc6681', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 11, 11, 'Then they brought out the king''s son, and put the crown on him, and [gave him] the testimony, and made him king: and Jehoiada and his sons anointed him; and they said, "Long live the king!"'),
  ('b150185a-a334-559a-a9f8-5d117a27d6b2', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 12, 12, 'When Athaliah heard the noise of the people running and praising the king, she came to the people into the house of Yahweh:'),
  ('cf87dd49-cabb-55c9-a427-674b6264a16c', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 13, 13, 'and she looked, and, behold, the king stood by his pillar at the entrance, and the captains and the trumpets by the king; and all the people of the land rejoiced, and blew trumpets; the singers also played musical instruments, and led the singing of praise. Then Athaliah tore her clothes, and said, "Treason! treason!"'),
  ('90c89642-fc4d-542d-a597-9899c4438716', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 14, 14, 'Jehoiada the priest brought out the captains of hundreds who were set over the army, and said to them, "Bring her out between the ranks; and whoever follows her, let him be slain with the sword." For the priest said, "Don''t kill her in the Yahweh''s house."'),
  ('0da47411-6607-5df6-a3f9-b8a90df18dba', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 15, 15, 'So they made way for her. She went to the entrance of the horse gate to the king''s house; and they killed her there.'),
  ('1ca789f6-3617-5ab5-ae32-71e0229ec291', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 16, 16, 'Jehoiada made a covenant between himself, and all the people, and the king, that they should be Yahweh''s people.'),
  ('5a3981d2-45ad-53cf-a381-ecda198ebc36', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 17, 17, 'All the people went to the house of Baal, and broke it down, and broke his altars and his images in pieces, and killed Mattan the priest of Baal before the altars.'),
  ('692afa17-8a1a-53c5-ac3b-c8d19566a40e', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 18, 18, 'Jehoiada appointed the officers of the house of Yahweh under the hand of the priests the Levites, whom David had distributed in the house of Yahweh, to offer the burnt offerings of Yahweh, as it is written in the law of Moses, with rejoicing and with singing, according to the order of David.'),
  ('ba1aba99-23e1-5581-a702-22ed3bfdc20d', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 19, 19, 'He set the porters at the gates of the house of Yahweh, that no one who was unclean in anything should enter in.'),
  ('cffe9608-063a-519d-ac68-c8c4a80f6025', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 20, 20, 'He took the captains of hundreds, and the nobles, and the governors of the people, and all the people of the land, and brought down the king from the house of Yahweh: and they came through the upper gate to the king''s house, and set the king on the throne of the kingdom.'),
  ('088efa4a-a4a6-5860-a709-9f94dc755e99', '1ea9f4c3-e3a2-5057-adea-7f34a20a147b', NULL, 21, 21, 'So all the people of the land rejoiced, and the city was quiet. Athaliah they had slain with the sword.'),
  ('d48a7786-2eeb-55d8-a8cd-b3f174515e08', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 1, 1, 'Joash was seven years old when he began to reign; and he reigned forty years in Jerusalem: and his mother''s name was Zibiah, of Beersheba.'),
  ('210094db-6062-58cd-a541-d98a251fb48c', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 2, 2, 'Joash did that which was right in the eyes of Yahweh all the days of Jehoiada the priest.'),
  ('46f09937-9ad1-5239-a2a6-0c992bf60a31', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 3, 3, 'Jehoiada took for him two wives; and he became the father of sons and daughters.'),
  ('9e515c67-6770-5fe8-a3f7-43de346e0035', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 4, 4, 'It happened after this, that Joash was minded to restore the house of Yahweh.'),
  ('9f920ee4-f18c-5265-a6ae-76932846cc15', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 5, 5, 'He gathered together the priests and the Levites, and said to them, "Go out to the cities of Judah, and gather money to repair the house of your God from all Israel from year to year. See that you expedite this matter." However the Levites didn''t do it right away.'),
  ('00bd1290-d084-5100-a09f-fc9dc549bc90', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 6, 6, 'The king called for Jehoiada the chief, and said to him, "Why haven''t you required of the Levites to bring in the tax of Moses the servant of Yahweh, and of the assembly of Israel, out of Judah and out of Jerusalem, for the tent of the testimony?"'),
  ('89372858-5cf0-5c61-a663-02c202077e3d', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 7, 7, 'For the sons of Athaliah, that wicked woman, had broken up the house of God; and also all the dedicated things of the house of Yahweh did they bestow on the Baals.'),
  ('b9b3eb83-6942-54e7-a36e-ce0187b37252', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 8, 8, 'So the king commanded, and they made a chest, and set it outside at the gate of the house of Yahweh.'),
  ('1d24683e-0be3-54ff-a7ff-f68c3fec8786', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 9, 9, 'They made a proclamation through Judah and Jerusalem, to bring in for Yahweh the tax that Moses the servant of God laid on Israel in the wilderness.'),
  ('4b369cc6-f997-55ac-aedc-2455bf0dfa54', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 10, 10, 'All the princes and all the people rejoiced, and brought in, and cast into the chest, until they had made an end.'),
  ('fac18c21-9544-58aa-a2ae-dd96e7997601', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 11, 11, 'It was so, that whenever the chest was brought to the king''s officers by the hand of the Levites, and when they saw that there was much money, the king''s scribe and the chief priest''s officer came and emptied the chest, and took it, and carried it to its place again. Thus they did day by day, and gathered money in abundance.'),
  ('b37afe30-4d22-599f-ae26-5c9b250b7e20', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 12, 12, 'The king and Jehoiada gave it to such as did the work of the service of the house of Yahweh; and they hired masons and carpenters to restore the house of Yahweh, and also such as worked iron and brass to repair the house of Yahweh.'),
  ('c051a5e8-1575-58ee-a286-409d6e89147e', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 13, 13, 'So the workmen worked, and the work of repairing went forward in their hands, and they set up the house of God in its state, and strengthened it.'),
  ('efd1d188-29d2-59a3-a29d-ade5b577a1c4', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 14, 14, 'When they had made an end, they brought the rest of the money before the king and Jehoiada, of which were made vessels for the house of Yahweh, even vessels with which to minister and to offer, and spoons, and vessels of gold and silver. They offered burnt offerings in the house of Yahweh continually all the days of Jehoiada.'),
  ('4a118023-84cb-500c-a106-92acf4514760', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 15, 15, 'But Jehoiada grew old and was full of days, and he died; one hundred thirty years old was he when he died.'),
  ('ab38a245-f895-5686-a6d1-42ac26beb237', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 16, 16, 'They buried him in the city of David among the kings, because he had done good in Israel, and toward God and his house.'),
  ('85fc2223-5796-584c-ad73-03d0b88a5d75', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 17, 17, 'Now after the death of Jehoiada came the princes of Judah, and made obeisance to the king. Then the king listened to them.'),
  ('9bf976f8-9ac4-5eff-afe2-1298f7cf3c21', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 18, 18, 'They forsook the house of Yahweh, the God of their fathers, and served the Asherim and the idols: and wrath came on Judah and Jerusalem for this their guiltiness.'),
  ('c4b53ddd-aa78-5f91-a8b0-9267a2d09af7', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 19, 19, 'Yet he sent prophets to them, to bring them again to Yahweh; and they testified against them: but they would not give ear.'),
  ('11b71707-1a85-5ead-a0f9-70a55242aff5', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 20, 20, 'The Spirit of God came on Zechariah the son of Jehoiada the priest; and he stood above the people, and said to them, "Thus says God, ''Why do you disobey the commandments of Yahweh, so that you can''t prosper? Because you have forsaken Yahweh, he has also forsaken you.''"'),
  ('46e1f1c9-ebf2-5eb0-a21c-38204b6f2b59', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 21, 21, 'They conspired against him, and stoned him with stones at the commandment of the king in the court of the house of Yahweh.'),
  ('519494a8-5818-56d2-a0d1-f5255fc0558e', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 22, 22, 'Thus Joash the king didn''t remember the kindness which Jehoiada his father had done to him, but killed his son. When he died, he said, "May Yahweh look at it, and repay it."'),
  ('7af94803-5ff0-5a75-a536-b9f169769fcd', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 23, 23, 'It happened at the end of the year, that the army of the Syrians came up against him: and they came to Judah and Jerusalem, and destroyed all the princes of the people from among the people, and sent all the spoil of them to the king of Damascus.'),
  ('4cd2cdd5-e360-581e-a290-21a64dae7432', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 24, 24, 'For the army of the Syrians came with a small company of men; and Yahweh delivered a very great army into their hand, because they had forsaken Yahweh, the God of their fathers. So they executed judgment on Joash.'),
  ('2d7573cc-deef-5e1f-a60f-cde3e74268a3', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 25, 25, 'When they were departed for him (for they left him very sick), his own servants conspired against him for the blood of the sons of Jehoiada the priest, and killed him on his bed, and he died; and they buried him in the city of David, but they didn''t bury him in the tombs of the kings.'),
  ('44b98c23-84bf-5842-a4f5-14fad0be4e53', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 26, 26, 'These are those who conspired against him: Zabad the son of Shimeath the Ammonitess, and Jehozabad the son of Shimrith the Moabitess.'),
  ('10a598c2-d824-586b-a3e0-5988c76941e8', 'b94d1d3b-bbbc-5b5c-a841-319a655b5f84', NULL, 27, 27, 'Now concerning his sons, and the greatness of the burdens [laid] on him, and the rebuilding of the house of God, behold, they are written in the commentary of the book of the kings. Amaziah his son reigned in his place.'),
  ('931e15f4-67f7-5d05-a7f9-d8a23f7e474c', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 1, 1, 'Amaziah was twenty-five years old when he began to reign; and he reigned twenty-nine years in Jerusalem: and his mother''s name was Jehoaddan, of Jerusalem.'),
  ('1fe0d82b-1316-5b0e-a08f-e3b9787a6d53', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 2, 2, 'He did that which was right in the eyes of Yahweh, but not with a perfect heart.'),
  ('1e82d457-bce5-525b-a9b8-31df23970f5f', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 3, 3, 'Now it happened, when the kingdom was established to him, that he killed his servants who had killed the king his father.'),
  ('4cb4dc70-a618-5362-a168-14d5da423d94', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 4, 4, 'But he didn''t put their children to death, but did according to that which is written in the law in the book of Moses, as Yahweh commanded, saying, "The fathers shall not die for the children, neither shall the children die for the fathers; but every man shall die for his own sin."'),
  ('b31362fb-b5d2-5f45-a2db-1b2815bbedd0', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 5, 5, 'Moreover Amaziah gathered Judah together, and ordered them according to their fathers'' houses, under captains of thousands and captains of hundreds, even all Judah and Benjamin: and he numbered them from twenty years old and upward, and found them three hundred thousand chosen men, able to go forth to war, who could handle spear and shield.'),
  ('1900e7c3-8c74-5946-a888-d57d912b3b54', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 6, 6, 'He hired also one hundred thousand mighty men of valor out of Israel for one hundred talents of silver.'),
  ('0cc4a4b1-6c50-5467-acb5-c8b535827a3f', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 7, 7, 'A man of God came to him, saying, "O king, don''t let the army of Israel go with you; for Yahweh is not with Israel, with all the children of Ephraim.'),
  ('55699500-9af2-5afc-a3ed-415f4f24a336', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 8, 8, 'But if you will go, take action, be strong for the battle. God will overthrow you before the enemy; for God has power to help, and to overthrow."'),
  ('12721131-8ab9-50f0-a62b-e7ceaf49e377', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 9, 9, 'Amaziah said to the man of God, "But what shall we do for the hundred talents which I have given to the army of Israel?" The man of God answered, "Yahweh is able to give you much more than this."'),
  ('87c28182-be1e-58bb-ac87-2d4b42d978ae', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 10, 10, 'Then Amaziah separated them, [to wit], the army that had come to him out of Ephraim, to go home again: therefore their anger was greatly kindled against Judah, and they returned home in fierce anger.'),
  ('115e42ab-a854-528c-a9ab-80cd6ae3de1c', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 11, 11, 'Amaziah took courage, and led forth his people, and went to the Valley of Salt, and struck of the children of Seir ten thousand.'),
  ('502e18d8-0190-5033-a83b-f32268e16432', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 12, 12, '[other] ten thousand did the children of Judah carry away alive, and brought them to the top of the rock, and cast them down from the top of the rock, so that they all were broken in pieces.'),
  ('bb4fd5bd-958e-51c8-acf4-c3b4e41f4afb', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 13, 13, 'But the men of the army whom Amaziah sent back, that they should not go with him to battle, fell on the cities of Judah, from Samaria even to Beth Horon, and struck of them three thousand, and took much spoil.'),
  ('928d0157-41c2-59b0-a6f3-f64347c62cda', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 14, 14, 'Now it happened, after that Amaziah was come from the slaughter of the Edomites, that he brought the gods of the children of Seir, and set them up to be his gods, and bowed down himself before them, and burned incense to them.'),
  ('5f11a644-e6f7-5c7e-a90c-0d5f125a8964', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 15, 15, 'Therefore the anger of Yahweh was kindled against Amaziah, and he sent to him a prophet, who said to him, "Why have you sought after the gods of the people, which have not delivered their own people out of your hand?"'),
  ('712c22e6-b5e3-5ec4-ab2f-d0b5c3061a05', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 16, 16, 'It happened, as he talked with him, that [the king] said to him, "Have we made you one of the king''s counselors? Stop! Why should you be struck down?" Then the prophet stopped, and said, "I know that God has determined to destroy you, because you have done this, and have not listened to my counsel."'),
  ('87a7f265-4dd2-5df0-abe9-79df3f9945ef', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 17, 17, 'Then Amaziah king of Judah consulted his advisers, and sent to Joash, the son of Jehoahaz the son of Jehu, king of Israel, saying, "Come, let us look one another in the face."'),
  ('ddcff20b-9052-5030-aa18-d407626bcfc5', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 18, 18, 'Joash king of Israel sent to Amaziah king of Judah, saying, "The thistle that was in Lebanon sent to the cedar that was in Lebanon, saying, ''Give your daughter to my son as his wife; then a wild animal that was in Lebanon passed by, and trampled down the thistle.'),
  ('ff6aa0c8-6c65-5ecf-aa9f-f06a81b5408f', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 19, 19, 'You say to yourself that you have struck Edom; and your heart lifts you up to boast. Now stay at home. Why should you meddle with trouble, that you should fall, even you, and Judah with you?''"'),
  ('148b6566-abdf-521c-ada2-d984694d63ac', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 20, 20, 'But Amaziah would not listen; for it was of God, that he might deliver them into the hand [of their enemies], because they had sought after the gods of Edom.'),
  ('d8a3833f-718b-51f9-a956-a3bfe53805a6', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 21, 21, 'So Joash king of Israel went up; and he and Amaziah king of Judah looked one another in the face at Beth Shemesh, which belongs to Judah.'),
  ('367ef205-7138-59a6-a58c-ba6013fbd6ef', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 22, 22, 'Judah was defeated by Israel; and they fled every man to his tent.'),
  ('0df9e6e8-b54c-5cd1-ac0f-5ea4030d39de', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 23, 23, 'Joash king of Israel took Amaziah king of Judah, the son of Joash the son of Jehoahaz, at Beth Shemesh, and brought him to Jerusalem, and broke down the wall of Jerusalem from the gate of Ephraim to the corner gate, four hundred cubits.'),
  ('88fd68b7-805e-5827-a835-135bcd87009e', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 24, 24, '[He took] all the gold and silver, and all the vessels that were found in the house of God with Obed-Edom, and the treasures of the king''s house, the hostages also, and returned to Samaria.'),
  ('19b13a34-af6e-5915-ac91-76d21d4b59a3', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 25, 25, 'Amaziah the son of Joash king of Judah lived after the death of Joash son of Jehoahaz king of Israel fifteen years.'),
  ('4de43b61-f3a3-5364-a1b0-87e32e9352da', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 26, 26, 'Now the rest of the acts of Amaziah, first and last, behold, aren''t they written in the book of the kings of Judah and Israel?'),
  ('b82bd510-a8d4-5cd0-aebc-3fb649851999', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 27, 27, 'Now from the time that Amaziah did turn away from following Yahweh they made a conspiracy against him in Jerusalem; and he fled to Lachish: but they sent after him to Lachish, and killed him there.'),
  ('8c3cb3d4-b1ba-5c4a-a841-ed5ef696d759', 'd9b296b7-ea9e-54d0-a095-c4163af06a88', NULL, 28, 28, 'They brought him on horses, and buried him with his fathers in the city of Judah.'),
  ('c6312f9d-f34e-5c00-aae9-e7c062aa6a81', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 1, 1, 'All the people of Judah took Uzziah, who was sixteen years old, and made him king in the place of his father Amaziah.'),
  ('7f2314f4-dcbb-50fc-ada2-5f70d16f5406', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 2, 2, 'He built Eloth, and restored it to Judah, after that the king slept with his fathers.'),
  ('e9f85a00-f5c5-5bd6-a1a0-8e61751fad35', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 3, 3, 'Sixteen years old was Uzziah when he began to reign; and he reigned fifty-two years in Jerusalem: and his mother''s name was Jechiliah, of Jerusalem.'),
  ('9b84a0c5-8d46-51e5-af75-60d19de3143b', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 4, 4, 'He did that which was right in the eyes of Yahweh, according to all that his father Amaziah had done.'),
  ('9d88ab78-2865-5321-aa64-c0ec4eca71ff', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 5, 5, 'He set himself to seek God in the days of Zechariah, who had understanding in the vision of God: and as long as he sought Yahweh, God made him to prosper.'),
  ('7576bb58-d1c4-543f-a1b8-db113d7610bd', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 6, 6, 'He went forth and warred against the Philistines, and broke down the wall of Gath, and the wall of Jabneh, and the wall of Ashdod; and he built cities in [the country of] Ashdod, and among the Philistines.'),
  ('dfb850bb-bd95-5c59-ad5f-59ed0cfc0c86', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 7, 7, 'God helped him against the Philistines, and against the Arabians who lived in Gur Baal, and the Meunim.'),
  ('d7024e6e-9b08-5524-a2c6-1b96436815f5', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 8, 8, 'The Ammonites gave tribute to Uzziah: and his name spread abroad even to the entrance of Egypt; for he grew exceeding strong.'),
  ('c0ac3e72-8e5c-55b4-ab19-66be8a04a716', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 9, 9, 'Moreover Uzziah built towers in Jerusalem at the corner gate, and at the valley gate, and at the turning [of the wall], and fortified them.'),
  ('dbcbd399-622f-5b0e-a725-7a4b58b7ac16', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 10, 10, 'He built towers in the wilderness, and dug out many cisterns, for he had much livestock; in the lowland also, and in the plain: [and he had] farmers and vineyard keepers in the mountains and in the fruitful fields; for he loved farming.'),
  ('87248a37-3d2e-59f9-a49c-895cecdb4432', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 11, 11, 'Moreover Uzziah had an army of fighting men, who went out to war by bands, according to the number of their reckoning made by Jeiel the scribe and Maaseiah the officer, under the hand of Hananiah, one of the king''s captains.'),
  ('0abc9f85-70f7-5484-abdf-44de7616e8e9', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 12, 12, 'The whole number of the heads of fathers'' [houses], even the mighty men of valor, was two thousand and six hundred.'),
  ('5f0f37ee-80f7-58a6-a68d-1d6468b6af41', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 13, 13, 'Under their hand was an army, three hundred thousand and seven thousand and five hundred, who made war with mighty power, to help the king against the enemy.'),
  ('9cc4e110-a9ea-57be-ab0e-1492e46a7e29', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 14, 14, 'Uzziah prepared for them, even for all the army, shields, and spears, and helmets, and coats of mail, and bows, and stones for slinging.'),
  ('0a9def03-0010-5dcf-ae75-33b0ab9cc84c', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 15, 15, 'He made in Jerusalem engines, invented by skillful men, to be on the towers and on the battlements, with which to shoot arrows and great stones. His name spread far abroad; for he was marvelously helped, until he was strong.'),
  ('f1d77cbe-7d10-52cd-a818-a39e0287fba2', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 16, 16, 'But when he was strong, his heart was lifted up, so that he did corruptly, and he trespassed against Yahweh his God; for he went into the temple of Yahweh to burn incense on the altar of incense.'),
  ('94a3b2e0-160b-5f69-af0a-84a05bdf1cae', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 17, 17, 'Azariah the priest went in after him, and with him eighty priests of Yahweh, who were valiant men:'),
  ('12f27a47-256c-5e68-a39e-20335c7dabaf', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 18, 18, 'and they resisted Uzziah the king, and said to him, "It isn''t for you, Uzziah, to burn incense to Yahweh, but for the priests the sons of Aaron, who are consecrated to burn incense. Go out of the sanctuary; for you have trespassed; neither shall it be for your honor from Yahweh God."'),
  ('a9b669e5-fb6e-5719-a95f-bcb33747e84b', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 19, 19, 'Then Uzziah was angry; and he had a censer in his hand to burn incense; and while he was angry with the priests, the leprosy broke forth in his forehead before the priests in the house of Yahweh, beside the altar of incense.'),
  ('f384e213-d675-52f6-a5bd-bee7444614c8', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 20, 20, 'Azariah the chief priest, and all the priests, looked on him, and behold, he was leprous in his forehead, and they thrust him out quickly from there; yes, himself hurried also to go out, because Yahweh had struck him.'),
  ('89c42cd9-4756-50aa-ab8f-07265971c8ca', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 21, 21, 'Uzziah the king was a leper to the day of his death, and lived in a separate house, being a leper; for he was cut off from the house of Yahweh: and Jotham his son was over the king''s house, judging the people of the land.'),
  ('ca596bfa-4a54-5069-a720-3258b85bdc5e', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 22, 22, 'Now the rest of the acts of Uzziah, first and last, did Isaiah the prophet, the son of Amoz, write.'),
  ('8c013760-a7a0-5bb6-ae6b-33454d12b3cc', 'e47199a7-8756-5f01-a69e-609da64417f3', NULL, 23, 23, 'So Uzziah slept with his fathers; and they buried him with his fathers in the field of burial which belonged to the kings; for they said, "He is a leper." Jotham his son reigned in his place.'),
  ('0af0b46b-0375-50ac-a12e-47ce82734553', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 1, 1, 'Jotham was twenty-five years old when he began to reign; and he reigned sixteen years in Jerusalem: and his mother''s name was Jerushah the daughter of Zadok.'),
  ('06063120-fe0f-511e-ace9-f60359e5b96a', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 2, 2, 'He did that which was right in the eyes of Yahweh, according to all that his father Uzziah had done: however he didn''t enter into the temple of Yahweh. The people did yet corruptly.'),
  ('716c7ae3-aa23-5952-aeb3-2bcdaaa53cc5', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 3, 3, 'He built the upper gate of the house of Yahweh, and on the wall of Ophel he built much.'),
  ('2ddd2926-f7d6-5e69-a233-2a00695b8686', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 4, 4, 'Moreover he built cities in the hill country of Judah, and in the forests he built castles and towers.'),
  ('70b7be7f-e947-5a1e-a301-a3cdc0f7feab', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 5, 5, 'He fought also with the king of the children of Ammon, and prevailed against them. The children of Ammon gave him the same year one hundred talents of silver, and ten thousand measures of wheat, and ten thousand of barley. So much did the children of Ammon render to him, in the second year also, and in the third.'),
  ('088ea9b5-943c-5d26-aa1a-71d76e245743', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 6, 6, 'So Jotham became mighty, because he ordered his ways before Yahweh his God.'),
  ('cead8701-8398-53be-a29f-e361a27c6b12', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 7, 7, 'Now the rest of the acts of Jotham, and all his wars, and his ways, behold, they are written in the book of the kings of Israel and Judah.'),
  ('d94dedac-eb03-5394-a28f-681d2791857a', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 8, 8, 'He was five and twenty years old when he began to reign, and reigned sixteen years in Jerusalem.'),
  ('870736ef-1f1c-5955-ab91-ccbc157668c3', '1f3bf6aa-1152-53b6-a1a9-8216564e53bd', NULL, 9, 9, 'Jotham slept with his fathers, and they buried him in the city of David: and Ahaz his son reigned in his place.'),
  ('de98d14c-b617-505b-a91c-ddcc3b8814b2', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 1, 1, 'Ahaz was twenty years old when he began to reign; and he reigned sixteen years in Jerusalem: and he didn''t do that which was right in the eyes of Yahweh, like David his father;'),
  ('16cabcf0-7f33-5807-a963-f0106e6392c0', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 2, 2, 'but he walked in the ways of the kings of Israel, and made also molten images for the Baals.'),
  ('c2ed7563-708c-54fb-a356-b990cd58082d', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 3, 3, 'Moreover he burnt incense in the valley of the son of Hinnom, and burnt his children in the fire, according to the abominations of the nations whom Yahweh cast out before the children of Israel.'),
  ('db08dd74-3fed-58b0-a106-75d53f8f51cc', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 4, 4, 'He sacrificed and burnt incense in the high places, and on the hills, and under every green tree.'),
  ('e01dcac5-f87f-5373-aa0a-fc951218e34d', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 5, 5, 'Therefore Yahweh his God delivered him into the hand of the king of Syria; and they struck him, and carried away of his a great multitude of captives, and brought them to Damascus. He was also delivered into the hand of the king of Israel, who struck him with a great slaughter.'),
  ('9d75cf8c-aaf1-564e-a874-a7976c2599bd', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 6, 6, 'For Pekah the son of Remaliah killed in Judah one hundred twenty thousand in one day, all of them valiant men; because they had forsaken Yahweh, the God of their fathers.'),
  ('d13d9db0-86fc-5fd8-af59-5f002c74a141', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 7, 7, 'Zichri, a mighty man of Ephraim, killed Maaseiah the king''s son, and Azrikam the ruler of the house, and Elkanah who was next to the king.'),
  ('0819420e-ff90-5d2b-a575-b4a4ec2fed67', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 8, 8, 'The children of Israel carried away captive of their brothers two hundred thousand, women, sons, and daughters, and took also away much spoil from them, and brought the spoil to Samaria.'),
  ('969bcceb-b5e8-56a8-a643-0ec6004f8483', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 9, 9, 'But a prophet of Yahweh was there, whose name was Oded: and he went out to meet the army that came to Samaria, and said to them, "Behold, because Yahweh, the God of your fathers, was angry with Judah, he has delivered them into your hand, and you have slain them in a rage which has reached up to heaven.'),
  ('8dd479d3-d82c-53fe-a38e-cf7b4057de03', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 10, 10, 'Now you purpose to keep under the children of Judah and Jerusalem for bondservants and bondmaids for yourselves. Aren''t there even with you trespasses of your own against Yahweh your God?'),
  ('52ee71aa-5085-5d98-a37c-b33a8a36974c', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 11, 11, 'Now hear me therefore, and send back the captives, that you have taken captive from your brothers; for the fierce wrath of Yahweh is on you."'),
  ('1e08a2e4-9ae5-54b7-ad5f-8bac21652b5d', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 12, 12, 'Then some of the heads of the children of Ephraim, Azariah the son of Johanan, Berechiah the son of Meshillemoth, and Jehizkiah the son of Shallum, and Amasa the son of Hadlai, stood up against those who came from the war,'),
  ('bf431e98-1f40-537b-ac37-b17f959c9e34', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 13, 13, 'and said to them, "You shall not bring in the captives here: for you purpose that which will bring on us a trespass against Yahweh, to add to our sins and to our trespass; for our trespass is great, and there is fierce wrath against Israel."'),
  ('58a566de-9a61-5831-ad56-47c2f763c4c0', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 14, 14, 'So the armed men left the captives and the spoil before the princes and all the assembly.'),
  ('7a6c3db3-584a-5eb7-ab79-c4c05033586f', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 15, 15, 'The men who have been mentioned by name rose up, and took the captives, and with the spoil clothed all who were naked among them, dressed them, gave them sandals, and gave them something to eat and to drink, anointed them, carried all the feeble of them on donkeys, and brought them to Jericho, the city of palm trees, to their brothers. Then they returned to Samaria.'),
  ('c89d78aa-f952-5c64-ade4-db66ed58d8b8', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 16, 16, 'At that time king Ahaz sent to the kings of Assyria to help him.'),
  ('175cc99c-45ba-5d3d-a23e-04087d1a0e02', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 17, 17, 'For again the Edomites had come and struck Judah, and carried away captives.'),
  ('29a239d8-a99d-5559-a891-ca839d072023', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 18, 18, 'The Philistines also had invaded the cities of the lowland, and of the South of Judah, and had taken Beth Shemesh, and Aijalon, and Gederoth, and Soco with its towns, and Timnah with its towns, Gimzo also and its towns: and they lived there.'),
  ('ce6ea3cc-2a65-5691-aae8-56f3f4e4a0e4', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 19, 19, 'For Yahweh brought Judah low because of Ahaz king of Israel; for he had dealt wantonly in Judah, and trespassed severely against Yahweh.'),
  ('8697c872-d765-53d8-a095-2ad2c21ba900', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 20, 20, 'Tilgath Pilneser king of Assyria came to him, and distressed him, but didn''t strengthen him.'),
  ('296b1a83-bf4a-5368-af1a-775a2159be67', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 21, 21, 'For Ahaz took away a portion out of the house of Yahweh, and out of the house of the king and of the princes, and gave it to the king of Assyria: but it didn''t help him.'),
  ('4f4727b4-df01-50b7-ab41-56e1a2ffaed0', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 22, 22, 'In the time of his distress did he trespass yet more against Yahweh, this same king Ahaz.'),
  ('8a5e1a43-831a-5a20-a59e-351771551495', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 23, 23, 'For he sacrificed to the gods of Damascus, which struck him; and he said, "Because the gods of the kings of Syria helped them, so I will sacrifice to them, that they may help me." But they were the ruin of him, and of all Israel.'),
  ('d0c0aca4-3c46-583e-a828-cc24ce0ad93f', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 24, 24, 'Ahaz gathered together the vessels of the house of God, and cut in pieces the vessels of the house of God, and shut up the doors of the house of Yahweh; and he made him altars in every corner of Jerusalem.'),
  ('7dfb2ac0-283b-582e-ae03-a00055dc6694', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 25, 25, 'In every city of Judah he made high places to burn incense to other gods, and provoked to anger Yahweh, the God of his fathers.'),
  ('27338ebe-9a79-5fd6-a6fe-e1c993f5855f', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 26, 26, 'Now the rest of his acts, and all his ways, first and last, behold, they are written in the book of the kings of Judah and Israel.'),
  ('e6ad1812-7705-520d-a522-910b86e7593f', 'c0d7b7df-c194-5d8c-affb-2aa3684f1b67', NULL, 27, 27, 'Ahaz slept with his fathers, and they buried him in the city, even in Jerusalem; for they didn''t bring him into the tombs of the kings of Israel: and Hezekiah his son reigned in his place.'),
  ('b3557b5d-df72-5d72-abaa-02783e6c1d07', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 1, 1, 'Hezekiah began to reign when he was twenty-five years old; and he reigned twenty-nine years in Jerusalem: and his mother''s name was Abijah, the daughter of Zechariah.'),
  ('03556855-d43a-562c-af79-4e1626723c1c', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 2, 2, 'He did that which was right in the eyes of Yahweh, according to all that David his father had done.'),
  ('bb20e01d-f4ae-5713-ad50-dee5bda88284', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 3, 3, 'He in the first year of his reign, in the first month, opened the doors of the house of Yahweh, and repaired them.'),
  ('a7d0d639-8d4b-5d82-ae51-d6385074930e', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 4, 4, 'He brought in the priests and the Levites, and gathered them together into the broad place on the east,'),
  ('8bf89a26-ceb9-51a5-ac58-adba95d50521', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 5, 5, 'and said to them, "Listen to me, you Levites! Now sanctify yourselves, and sanctify the house of Yahweh, the God of your fathers, and carry out the filthiness out of the holy place.'),
  ('c0ead115-a58a-5ef7-a5fe-294183595249', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 6, 6, 'For our fathers have trespassed, and done that which was evil in the sight of Yahweh our God, and have forsaken him, and have turned away their faces from the habitation of Yahweh, and turned their backs.'),
  ('ca220461-0386-5601-aca5-ed3edfd2a103', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 7, 7, 'Also they have shut up the doors of the porch, and put out the lamps, and have not burned incense nor offered burnt offerings in the holy place to the God of Israel.'),
  ('039b8320-64e8-5b3e-abc2-59bd40cdd05b', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 8, 8, 'Therefore the wrath of Yahweh was on Judah and Jerusalem, and he has delivered them to be tossed back and forth, to be an astonishment, and a hissing, as you see with your eyes.'),
  ('5b16c02a-16f8-5da1-a22d-8ee93c8a8da4', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 9, 9, 'For, behold, our fathers have fallen by the sword, and our sons and our daughters and our wives are in captivity for this.'),
  ('b64e3cfb-eafb-5f88-aa53-b406bd312e5c', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 10, 10, 'Now it is in my heart to make a covenant with Yahweh, the God of Israel, that his fierce anger may turn away from us.'),
  ('a7106f6a-e812-590e-a912-28aa8ce95240', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 11, 11, 'My sons, don''t be negligent now; for Yahweh has chosen you to stand before him, to minister to him, and that you should be his ministers, and burn incense."'),
  ('ec975074-5a35-5e81-a5ea-4dc334b65ba8', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 12, 12, 'Then the Levites arose, Mahath, the son of Amasai, and Joel the son of Azariah, of the sons of the Kohathites; and of the sons of Merari, Kish the son of Abdi, and Azariah the son of Jehallelel; and of the Gershonites, Joah the son of Zimmah, and Eden the son of Joah;'),
  ('f7778633-bda4-5a8d-acf4-0fdab020c4df', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 13, 13, 'and of the sons of Elizaphan, Shimri and Jeuel; and of the sons of Asaph, Zechariah and Mattaniah;'),
  ('2f434029-237a-548b-aefb-badb5e9a7bb4', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 14, 14, 'and of the sons of Heman, Jehuel and Shimei; and of the sons of Jeduthun, Shemaiah and Uzziel.'),
  ('9079a9b1-c93e-5080-af42-599e2cc8ea72', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 15, 15, 'They gathered their brothers, and sanctified themselves, and went in, according to the commandment of the king by the words of Yahweh, to cleanse the house of Yahweh.'),
  ('0f668055-f9a8-55a3-a9df-c735973814af', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 16, 16, 'The priests went in to the inner part of the house of Yahweh, to cleanse it, and brought out all the uncleanness that they found in the temple of Yahweh into the court of the house of Yahweh. The Levites took it, to carry it out abroad to the brook Kidron.'),
  ('6df4516a-1d4c-5c69-af9c-3a51bdbf751f', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 17, 17, 'Now they began on the first [day] of the first month to sanctify, and on the eighth day of the month came they to the porch of Yahweh; and they sanctified the house of Yahweh in eight days: and on the sixteenth day of the first month they made an end.'),
  ('ebba5ea9-07e7-58b6-a082-e773f3bfdc44', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 18, 18, 'Then they went in to Hezekiah the king within [the palace], and said, "We have cleansed all the house of Yahweh, and the altar of burnt offering, with all its vessels, and the table of show bread, with all its vessels.'),
  ('168bcf2f-4271-5c05-ab16-0ab03f84b1fc', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 19, 19, 'Moreover all the vessels, which king Ahaz in his reign did cast away when he trespassed, have we prepared and sanctified; and behold, they are before the altar of Yahweh."'),
  ('23d782f9-9902-56e4-aae0-7382e0d37dfa', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 20, 20, 'Then Hezekiah the king arose early, and gathered the princes of the city, and went up to the house of Yahweh.'),
  ('f8b69229-ed8d-5c90-af90-b72da4ecceb0', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 21, 21, 'They brought seven bulls, and seven rams, and seven lambs, and seven male goats, for a sin offering for the kingdom and for the sanctuary and for Judah. He commanded the priests the sons of Aaron to offer them on the altar of Yahweh.'),
  ('3151b39c-5a82-56a4-afa5-0f9f70d87d0d', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 22, 22, 'So they killed the bulls, and the priests received the blood, and sprinkled it on the altar: and they killed the rams, and sprinkled the blood on the altar: they killed also the lambs, and sprinkled the blood on the altar.'),
  ('a175271e-b3dc-563c-a7d3-9a96accb0cb7', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 23, 23, 'They brought near the male goats for the sin offering before the king and the assembly; and they laid their hands on them:'),
  ('201c942b-1e8b-5cf6-acd7-7c56e3648a26', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 24, 24, 'and the priests killed them, and they made a sin offering with their blood on the altar, to make atonement for all Israel; for the king commanded [that] the burnt offering and the sin offering [should be made] for all Israel.'),
  ('60d59c3d-d916-5b8a-a8c9-b6170777248b', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 25, 25, 'He set the Levites in the house of Yahweh with cymbals, with stringed instruments, and with harps, according to the commandment of David, and of Gad the king''s seer, and Nathan the prophet; for the commandment was of Yahweh by his prophets.'),
  ('fe807f7e-fc44-515b-a589-122014215685', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 26, 26, 'The Levites stood with the instruments of David, and the priests with the trumpets.'),
  ('d783ea2c-5ebf-5fd4-a603-d3963e30a690', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 27, 27, 'Hezekiah commanded to offer the burnt offering on the altar. When the burnt offering began, the song of Yahweh began also, and the trumpets, together with the instruments of David king of Israel.'),
  ('548c2e81-eb63-5156-ab35-19a4f2a9e533', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 28, 28, 'All the assembly worshiped, and the singers sang, and the trumpeters sounded; all this [continued] until the burnt offering was finished.'),
  ('6aec20db-5b26-50ee-a962-f0c692887afb', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 29, 29, 'When they had made an end of offering, the king and all who were present with him bowed themselves and worshiped.'),
  ('95b25752-bedb-5156-a81b-11388198b572', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 30, 30, 'Moreover Hezekiah the king and the princes commanded the Levites to sing praises to Yahweh with the words of David, and of Asaph the seer. They sang praises with gladness, and they bowed their heads and worshiped.'),
  ('227c75ec-481b-5760-aa65-df604fe1c3f9', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 31, 31, 'Then Hezekiah answered, "Now you have consecrated yourselves to Yahweh; come near and bring sacrifices and thank offerings into the house of Yahweh." The assembly brought in sacrifices and thank offerings; and as many as were of a willing heart [brought] burnt offerings.'),
  ('452cd237-6ea8-588a-adb0-cbbdab90aa23', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 32, 32, 'The number of the burnt offerings which the assembly brought was seventy bulls, one hundred rams, and two hundred lambs: all these were for a burnt offering to Yahweh.'),
  ('0fd0aaf4-4ad3-5e2c-a326-7e6abca2a757', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 33, 33, 'The consecrated things were six hundred head of cattle and three thousand sheep.'),
  ('2c535677-e991-5d59-abdd-94bed144b91d', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 34, 34, 'But the priests were too few, so that they could not flay all the burnt offerings: therefore their brothers the Levites helped them, until the work was ended, and until the priests had sanctified themselves; for the Levites were more upright in heart to sanctify themselves than the priests.'),
  ('be42dee0-4a61-5a34-a879-48acc0f75dd4', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 35, 35, 'Also the burnt offerings were in abundance, with the fat of the peace offerings, and with the drink offerings for every burnt offering. So the service of the house of Yahweh was set in order.'),
  ('3620e027-8f8d-5986-a02a-22934d93d3f0', 'a2c299ea-b0cd-571a-a7c2-e2d67f2fb69f', NULL, 36, 36, 'Hezekiah rejoiced, and all the people, because of that which God had prepared for the people: for the thing was done suddenly.'),
  ('5aae3bf5-131c-5cb8-a963-5658235cb2da', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 1, 1, 'Hezekiah sent to all Israel and Judah, and wrote letters also to Ephraim and Manasseh, that they should come to the house of Yahweh at Jerusalem, to keep the Passover to Yahweh, the God of Israel.'),
  ('721f7e6d-b15b-5565-a1be-5cedd801b5c6', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 2, 2, 'For the king had taken counsel, and his princes, and all the assembly in Jerusalem, to keep the Passover in the second month.'),
  ('06ed9669-d46d-57b6-ae73-ab5213dc5f10', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 3, 3, 'For they could not keep it at that time, because the priests had not sanctified themselves in sufficient number, neither had the people gathered themselves together to Jerusalem.'),
  ('1b272fdd-6986-52c1-a8b8-fb49470318ad', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 4, 4, 'The thing was right in the eyes of the king and of all the assembly.'),
  ('03285df0-6b67-52cc-a752-1b0c7aabfb7a', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 5, 5, 'So they established a decree to make proclamation throughout all Israel, from Beersheba even to Dan, that they should come to keep the Passover to Yahweh, the God of Israel, at Jerusalem: for they had not kept it in great numbers in such sort as it is written.'),
  ('8c8adda9-d656-5f1f-a547-ec4ff46a8c98', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 6, 6, 'So the couriers went with the letters from the king and his princes throughout all Israel and Judah, and according to the commandment of the king, saying, "You children of Israel, turn again to Yahweh, the God of Abraham, Isaac, and Israel, that he may return to the remnant that have escaped of you out of the hand of the kings of Assyria.'),
  ('886015e8-23d8-576e-afce-796daf4e99e1', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 7, 7, 'Don''t be like your fathers, and like your brothers, who trespassed against Yahweh, the God of their fathers, so that he gave them up to desolation, as you see.'),
  ('702bed06-6be7-5c6f-ab33-87ed5e094817', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 8, 8, 'Now don''t be stiff-necked, as your fathers were; but yield yourselves to Yahweh, and enter into his sanctuary, which he has sanctified forever, and serve Yahweh your God, that his fierce anger may turn away from you.'),
  ('82a79900-b708-5d09-a423-dfb70fa29132', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 9, 9, 'For if you turn again to Yahweh, your brothers and your children shall find compassion before those who led them captive, and shall come again into this land: for Yahweh your God is gracious and merciful, and will not turn away his face from you, if you return to him."'),
  ('1ce39161-e1a7-5a09-a9b8-c70d46c051d9', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 10, 10, 'So the couriers passed from city to city through the country of Ephraim and Manasseh, even to Zebulun: but they ridiculed them, and mocked them.'),
  ('d663c002-bd5d-598f-a669-86eab55875ad', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 11, 11, 'Nevertheless certain men of Asher and Manasseh and of Zebulun humbled themselves, and came to Jerusalem.'),
  ('3b864566-5d85-5a67-a54b-db3c9e30b313', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 12, 12, 'Also on Judah came the hand of God to give them one heart, to do the commandment of the king and of the princes by the word of Yahweh.'),
  ('fe6dba7d-96e3-57ac-ab94-1d0b57347e66', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 13, 13, 'Many people assembled at Jerusalem to keep the feast of unleavened bread in the second month, a very great assembly.'),
  ('d9a73632-b0fe-578e-a3e0-f40a0038487a', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 14, 14, 'They arose and took away the altars that were in Jerusalem, and all the altars for incense took they away, and cast them into the brook Kidron.'),
  ('f3b4bc5b-8f2e-5945-aa84-b50a1eb2f6b1', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 15, 15, 'Then they killed the Passover on the fourteenth [day] of the second month: and the priests and the Levites were ashamed, and sanctified themselves, and brought burnt offerings into the house of Yahweh.'),
  ('199a3439-1da4-5e7d-ad3d-34a064777490', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 16, 16, 'They stood in their place after their order, according to the law of Moses the man of God: the priests sprinkled the blood [which they received] of the hand of the Levites.'),
  ('43906817-d07e-53c7-a6bc-b10df1a61cc9', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 17, 17, 'For there were many in the assembly who had not sanctified themselves: therefore the Levites were in charge of killing the Passovers for everyone who was not clean, to sanctify them to Yahweh.'),
  ('ee74128d-3f16-5b3f-ade0-587ae82f2063', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 18, 18, 'For a multitude of the people, even many of Ephraim and Manasseh, Issachar and Zebulun, had not cleansed themselves, yet they ate the Passover otherwise than it is written. For Hezekiah had prayed for them, saying, "May the good Yahweh pardon everyone'),
  ('9fd1af0f-b8fe-5337-a3c2-18ed2f16ae45', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 19, 19, 'who sets his heart to seek God, Yahweh, the God of his fathers, even if they aren''t clean according to the purification of the sanctuary."'),
  ('1c76ea02-13af-5a02-a75b-9bdd610f71b9', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 20, 20, 'Yahweh listened to Hezekiah, and healed the people.'),
  ('91ba08fc-9e07-5f7a-a750-5b489f2ce938', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 21, 21, 'The children of Israel who were present at Jerusalem kept the feast of unleavened bread seven days with great gladness; and the Levites and the priests praised Yahweh day by day, [singing] with loud instruments to Yahweh.'),
  ('d74fd4aa-a189-5439-ae6a-661f5e1d95df', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 22, 22, 'Hezekiah spoke comfortably to all the Levites who had good understanding [in the service] of Yahweh. So they ate throughout the feast for the seven days, offering sacrifices of peace offerings, and making confession to Yahweh, the God of their fathers.'),
  ('be7b7113-4bf4-504e-a029-0b719efcff50', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 23, 23, 'The whole assembly took counsel to keep other seven days; and they kept [other] seven days with gladness.'),
  ('461978d8-e098-5d7b-af91-890c67f1ab96', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 24, 24, 'For Hezekiah king of Judah did give to the assembly for offerings one thousand bulls and seven thousand sheep; and the princes gave to the assembly a thousand bulls and ten thousand sheep: and a great number of priests sanctified themselves.'),
  ('8a24aa0e-b642-5c5e-a571-a09e22d7fad3', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 25, 25, 'All the assembly of Judah, with the priests and the Levites, and all the assembly who came out of Israel, and the foreigners who came out of the land of Israel, and who lived in Judah, rejoiced.'),
  ('16fcb949-4c7c-5851-a2a4-f1229d2ff0a1', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 26, 26, 'So there was great joy in Jerusalem; for since the time of Solomon the son of David king of Israel there was not the like in Jerusalem.'),
  ('1ca64612-d9f4-5b60-a844-dffb227a28b7', '0aaa2ed4-41da-5409-a5e6-9b08da7af66a', NULL, 27, 27, 'Then the priests the Levites arose and blessed the people: and their voice was heard, and their prayer came up to his holy habitation, even to heaven.'),
  ('f2bba12c-720f-5bde-abdd-94041599215e', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 1, 1, 'Now when all this was finished, all Israel who were present went out to the cities of Judah, and broke in pieces the pillars, and cut down the Asherim, and broke down the high places and the altars out of all Judah and Benjamin, in Ephraim also and Manasseh, until they had destroyed them all. Then all the children of Israel returned, every man to his possession, into their own cities.'),
  ('11fc6972-28d8-5eda-ae89-dea279d50101', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 2, 2, 'Hezekiah appointed the divisions of the priests and the Levites after their divisions, every man according to his service, both the priests and the Levites, for burnt offerings and for peace offerings, to minister, and to give thanks, and to praise in the gates of the camp of Yahweh.'),
  ('c07e6073-35c9-57a3-a687-29744bbf9ec7', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 3, 3, '[He appointed] also the king''s portion of his substance for the burnt offerings, [to wit], for the morning and evening burnt offerings, and the burnt offerings for the Sabbaths, and for the new moons, and for the set feasts, as it is written in the law of Yahweh.'),
  ('93cd0bac-4c34-5805-ab2b-5566c230e1ba', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 4, 4, 'Moreover he commanded the people who lived in Jerusalem to give the portion of the priests and the Levites, that they might give themselves to the law of Yahweh.'),
  ('950f4d84-99df-5c17-ada5-23494445c1af', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 5, 5, 'As soon as the commandment came abroad, the children of Israel gave in abundance the first fruits of grain, new wine, and oil, and honey, and of all the increase of the field; and the tithe of all things brought they in abundantly.'),
  ('5fbc13a3-6c88-550e-a384-9fd21930be8c', '3eb32b37-4b51-5fed-ad60-af88ca2d29a5', NULL, 6, 6, 'The children of Israel and Judah, who lived in the cities of Judah, they also brought in the tithe of cattle and sheep, and the tithe of dedicated things which were consecrated to Yahweh their God, and laid them by heaps.')
